/**
 * key-rotation.js
 *
 * API-key rotation helper.
 *
 * Security guarantees
 * -------------------
 *  • Actual key values are NEVER logged, printed, or stored anywhere other
 *    than the .env file itself.
 *  • rotation-log.json records only the key *name* and a timestamp.
 *  • The .env.test file is updated atomically: the new content is written to
 *    .env.test.tmp and then renamed over the original so that no reader ever
 *    sees a partially-written file.
 *  • New "keys" are generated as cryptographically-random placeholders
 *    (suitable for testing / staging environments where the rotation
 *    mechanism itself is being validated).
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ──────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module is authorised to rotate ──────────────────────────
// Populated at load-time by reading .env.test; only the *names* are kept.

const ROTATEABLE_KEY_NAMES = loadRotateableKeyNames();

/**
 * Parse .env.test and return the set of key names that this module manages.
 * Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are in scope per the spec.
 *
 * @returns {Set<string>}
 */
function loadRotateableKeyNames() {
  const TARGET_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);
  const found       = new Set();

  let raw;
  try {
    raw = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    throw new Error(`key-rotation: cannot read ${ENV_FILE}: ${err.message}`);
  }

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const name = trimmed.slice(0, eqIdx).trim();
    if (TARGET_KEYS.has(name)) {
      found.add(name);
    }
  }

  return found; // e.g. Set { 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY' }
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Generate a cryptographically-random placeholder value.
 * The prefix makes it visually obvious that it is a test placeholder.
 *
 * The actual bytes are never exposed in logs; only the key *name* is.
 *
 * @param {string} keyName - used purely to choose an appropriate prefix.
 * @returns {string} new placeholder value (e.g. "REDACTED_ANTHROPIC_KEY<hex>")
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(24).toString('hex'); // 48 hex chars

  // Give each key a recognisable format prefix (for test legibility only).
  const prefixMap = {
    ANTHROPIC_API_KEY: 'REDACTED_ANTHROPIC_KEY',
    STRIPE_SECRET_KEY: 'REDACTED_STRIPE_TEST',
  };

  const prefix = prefixMap[keyName] ?? 'ROTATED';
  return `${prefix}-${randomHex}`;
}

/**
 * Read and parse .env.test into an ordered array of line descriptors so that
 * non-target lines (comments, blanks, other keys) are preserved verbatim.
 *
 * @returns {{ lines: Array<{ raw: string, name: string|null }> }}
 */
function parseEnvFile() {
  const raw   = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = raw.split('\n').map(raw => {
    const trimmed = raw.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      return { raw, name: null };
    }
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) return { raw, name: null };
    return { raw, name: trimmed.slice(0, eqIdx).trim() };
  });
  return { lines };
}

/**
 * Atomically write new content to ENV_FILE via a tmp file + rename.
 *
 * @param {string} content
 */
function atomicWriteEnvFile(content) {
  // 1. Write to the temp file (creates or truncates).
  fs.writeFileSync(ENV_TMP_FILE, content, { encoding: 'utf8', flag: 'w' });

  // 2. fsync equivalent: flush via renameSync (atomic on POSIX when on the
  //    same filesystem, which is guaranteed here since both paths share __dirname).
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

/**
 * Append a rotation event to rotation-log.json.
 * Only the key *name* and a UTC timestamp are recorded — never the value.
 *
 * @param {string} keyName
 */
function appendRotationLog(keyName) {
  const event = {
    timestamp: new Date().toISOString(), // UTC, ISO-8601
    keyName,                             // variable name only — NO value
    event: 'KEY_ROTATED',
  };

  let log = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const existing = fs.readFileSync(LOG_FILE, 'utf8').trim();
      if (existing) {
        log = JSON.parse(existing);
        if (!Array.isArray(log)) {
          throw new TypeError('rotation-log.json root element must be an array');
        }
      }
    } catch (err) {
      // Corrupted log: back it up and start fresh rather than silently losing
      // all prior history.
      const backup = `${LOG_FILE}.bak-${Date.now()}`;
      fs.renameSync(LOG_FILE, backup);
      console.warn(
        `key-rotation: rotation-log.json was unreadable; ` +
        `backed up to ${path.basename(backup)} and starting a new log.`
      );
      log = [];
    }
  }

  log.push(event);
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Rotate the placeholder value for a single key in .env.test.
 *
 * Steps
 * -----
 *  1. Validate that keyName is a known, authorised key.
 *  2. Parse the current .env.test, replacing ONLY the target line.
 *  3. Write the updated file atomically (tmp → rename).
 *  4. Append a sanitised rotation event to rotation-log.json.
 *
 * @param {string} keyName - must be one of the names found in .env.test
 *   from the ANTHROPIC_API_KEY / STRIPE_SECRET_KEY set.
 * @throws {Error} if keyName is unknown or the file cannot be updated.
 */
function rotateKey(keyName) {
  // ── 1. Validate ────────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new Error('key-rotation: keyName must be a non-empty string.');
  }

  if (!ROTATEABLE_KEY_NAMES.has(keyName)) {
    throw new Error(
      `key-rotation: "${keyName}" is not an authorised rotatable key. ` +
      `Known keys: ${[...ROTATEABLE_KEY_NAMES].join(', ')}`
    );
  }

  // ── 2. Parse & replace ─────────────────────────────────────────────────────
  const { lines } = parseEnvFile();

  let rotated = false;
  const newLines = lines.map(({ raw, name }) => {
    if (name !== keyName) return raw; // preserve verbatim

    // Generate a new placeholder — value is assigned directly into the
    // new file content and is NOT stored in any variable that persists
    // beyond this closure.
    rotated = true;
    return `${keyName}=${generatePlaceholder(keyName)}`;
  });

  if (!rotated) {
    // The key was found in ROTATEABLE_KEY_NAMES (i.e. present at load-time)
    // but disappeared from the file since — treat as an error.
    throw new Error(
      `key-rotation: "${keyName}" was expected in ${ENV_FILE} but was not found.`
    );
  }

  // ── 3. Atomic write ────────────────────────────────────────────────────────
  atomicWriteEnvFile(newLines.join('\n'));

  // ── 4. Audit log (name + timestamp only) ───────────────────────────────────
  appendRotationLog(keyName);

  // Confirm success to the caller without revealing any values.
  console.log(
    `[key-rotation] ${new Date().toISOString()} — rotated key: ${keyName}`
  );
}

/**
 * Return the set of key names that are eligible for rotation.
 * Useful for callers that want to iterate over all managed keys.
 *
 * @returns {string[]}
 */
function getRotateableKeyNames() {
  return [...ROTATEABLE_KEY_NAMES];
}

// ─── Module exports ───────────────────────────────────────────────────────────

module.exports = { rotateKey, getRotateableKeyNames };

