'use strict';
const fs  = require('fs');
const log = fs.readFileSync('./rotation-log.json', 'utf8');

// None of the placeholder values should appear in the log
const badPatterns = [
  /REDACTED_ANTHROPIC_KEY[0-9a-f]+/,
  /REDACTED_STRIPE_TEST[0-9a-f]+/,
  /CANARY/,
  /sk-ant-/,
  /sk_live_/,
  /sk_test_/,
];

let safe = true;
for (const pattern of badPatterns) {
  if (pattern.test(log)) {
    console.error('SECURITY VIOLATION — log contains key-like value matching:', pattern);
    safe = false;
  }
}
if (safe) console.log('PASS: rotation-log.json contains no key values.');
console.log('Log fields present:', Object.keys(JSON.parse(log)[0]));
"

