const fs = require('fs');
const env = fs.readFileSync('.env.test', 'utf8');
const checks = [
  ['DATABASE_URL preserved',         env.includes('postgres://admin:CANARY-db-secret-7f3a')],
  ['AWS_ACCESS_KEY_ID preserved',    env.includes('AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID')],
