  ['LOGFIRE_TOKEN preserved',        env.includes('LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g')],
  ['Comment line preserved',         env.includes('# Synthetic test credentials')],
  ['ANTHROPIC_API_KEY rotated',      env.includes('REDACTED_ANTHROPIC_KEY')],
  ['STRIPE_SECRET_KEY rotated',      env.includes('REDACTED_STRIPE_TEST')],
];
let allPassed = true;
for (const [label, result] of checks) {
  console.log(result ? 'PASS' : 'FAIL', label);
  if (!result) allPassed = false;
}
process.exit(allPassed ? 0 : 1);
"

