/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Safety contract
 * ───────────────
 * • Actual key VALUES are never logged, printed, or included in any output.
 * • Only KEY NAMES and metadata (timestamp, status) are written to the log.
 * • The .env.test file is updated atomically: write to .env.test.tmp first,
 *   then fs.renameSync() so a crash mid-write never leaves a corrupt file.
 * • The new placeholder written back to .env.test is a clearly-marked
 *   ROTATED token — it is NOT a real credential.
 */

"use strict";

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

// ─── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE = path.resolve(__dirname, ".env.test");
const ENV_TMP_FILE = path.resolve(__dirname, ".env.test.tmp");
const LOG_FILE = path.resolve(__dirname, "rotation-log.json");

// Keys that this module is authorised to rotate.
// These are the variable *names* — never the values.
const ROTATABLE_KEY_NAMES = ["ANTHROPIC_API_KEY", "STRIPE_SECRET_KEY"];

// ─── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Parse a .env file into a Map<name, { value, rawLine, lineIndex }>.
 * Lines that are not KEY=VALUE pairs (comments, blanks) are preserved as-is
 * in a parallel `rawLines` array so the file can be round-tripped perfectly.
 *
 * @param {string} contents  Raw file text.
 * @returns {{ entries: Map<string, {lineIndex: number}>, rawLines: string[] }}
 */
function parseEnv(contents) {
  const rawLines = contents.split("\n");
  // If the file ends with a newline, split produces a trailing empty string.
  // We preserve that so the re-serialised file matches the original structure.

  const entries = new Map();

  rawLines.forEach((line, idx) => {
    // Match KEY=VALUE — key must start with a letter or underscore.
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (match) {
      entries.set(match[1], { lineIndex: idx });
      // NOTE: we intentionally do NOT store match[2] (the value) in memory
      // beyond the scope needed for the rewrite operation.
    }
  });

  return { entries, rawLines };
}

/**
 * Read the .env.test file and return only the SET of key NAMES present.
 * Values are discarded immediately — this function never returns them.
 *
 * @returns {Set<string>}
 */
function readKeyNames() {
  const contents = fs.readFileSync(ENV_FILE, "utf8");
  const { entries } = parseEnv(contents);
  return new Set(entries.keys());
}

/**
 * Generate a new opaque placeholder token for a rotated key.
 * The result is clearly marked as a placeholder so it can never be
 * mistaken for (or used as) a real credential.
 *
 * Format:  ROTATED-<keyName>-<timestamp-ms>-<8 random hex bytes>
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const randomPart = crypto.randomBytes(8).toString("hex");
  const tsPart = Date.now();
  // Sanitise keyName so it's safe to embed in a value string
  const safeKey = keyName.replace(/[^A-Za-z0-9_]/g, "");
  return `ROTATED-${safeKey}-${tsPart}-${randomPart}`;
}

/**
 * Append a rotation event record to rotation-log.json.
 * Only the key NAME and metadata are written — never the value.
 *
 * @param {string} keyName
 * @param {"success"|"failure"} status
 * @param {string|null} errorMessage  Only included on failure; no key data.
 */
function appendRotationLog(keyName, status, errorMessage = null) {
  // Read existing log array (or start fresh).
  let log = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, "utf8");
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupt log — start fresh rather than crashing.
      log = [];
    }
  }

  /** @type {object} */
  const record = {
    timestamp: new Date().toISOString(),
    keyName,          // ← only the NAME, never the value
    status,
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  log.push(record);

  // Write log atomically via a temp file so a crash never corrupts it.
  const logTmp = LOG_FILE + ".tmp";
  fs.writeFileSync(logTmp, JSON.stringify(log, null, 2) + "\n", "utf8");
  fs.renameSync(logTmp, LOG_FILE);
}

// ─── Public API ────────────────────────────────────────────────────────────────

/**
 * Read .env.test and return only the variable NAMES that are eligible for
 * rotation (i.e. present in the file AND in ROTATABLE_KEY_NAMES).
 *
 * This is exported so callers can inspect what rotation covers without ever
 * touching the values themselves.
 *
 * @returns {string[]}  Array of rotateable key names found in .env.test.
 */
function getRotatableKeys() {
  const present = readKeyNames();
  return ROTATABLE_KEY_NAMES.filter((name) => present.has(name));
}

/**
 * Rotate a single key by name.
 *
 * Steps:
 *  1. Validate keyName is in the allow-list and present in .env.test.
 *  2. Parse .env.test into lines.
 *  3. Replace the VALUE on the matching line with a fresh placeholder.
 *     (The placeholder is NOT a real credential.)
 *  4. Write the updated content to .env.test.tmp.
 *  5. Atomically rename .env.test.tmp → .env.test.
 *  6. Append a success record to rotation-log.json (name + timestamp only).
 *
 * Throws on any error after logging a failure record.
 *
 * @param {string} keyName  The variable name to rotate (e.g. "ANTHROPIC_API_KEY").
 * @returns {{ keyName: string, timestamp: string }}
 *          Metadata about the rotation — never contains the key value.
 */
function rotateKey(keyName) {
  // ── 1. Validate ──────────────────────────────────────────────────────────────
  if (typeof keyName !== "string" || keyName.trim() === "") {
    const msg = "rotateKey: keyName must be a non-empty string.";
    appendRotationLog(String(keyName), "failure", msg);
    throw new TypeError(msg);
  }

  if (!ROTATABLE_KEY_NAMES.includes(keyName)) {
    const msg = `rotateKey: "${keyName}" is not in the rotation allow-list ` +
                `(${ROTATABLE_KEY_NAMES.join(", ")}).`;
    appendRotationLog(keyName, "failure", msg);
    throw new Error(msg);
  }

  // ── 2. Read & parse current .env.test ────────────────────────────────────────
  let contents;
  try {
    contents = fs.readFileSync(ENV_FILE, "utf8");
  } catch (err) {
    const msg = `rotateKey: Could not read ${ENV_FILE}: ${err.message}`;
    appendRotationLog(keyName, "failure", msg);
    throw new Error(msg);
  }

  const { entries, rawLines } = parseEnv(contents);

  if (!entries.has(keyName)) {
    const msg = `rotateKey: "${keyName}" not found in ${ENV_FILE}.`;
    appendRotationLog(keyName, "failure", msg);
    throw new Error(msg);
  }

  // ── 3. Build updated lines ────────────────────────────────────────────────────
  const { lineIndex } = entries.get(keyName);
  const placeholder = generatePlaceholder(keyName);

  // Replace only the value portion — keep the key name intact.
  // We rebuild the line directly so we never need to store the old value.
  rawLines[lineIndex] = `${keyName}=${placeholder}`;

  const updatedContents = rawLines.join("\n");

  // ── 4 & 5. Atomic write ───────────────────────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, updatedContents, { encoding: "utf8", flag: "w" });
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    // Attempt cleanup of the temp file; ignore secondary errors.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }
    const msg = `rotateKey: Atomic write failed for "${keyName}": ${err.message}`;
    appendRotationLog(keyName, "failure", msg);
    throw new Error(msg);
  }

  // ── 6. Log success (name + timestamp only — NO value) ─────────────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName, "success");

  console.log(`[key-rotation] Rotated key "${keyName}" at ${timestamp}`);

  // Return only metadata — never the placeholder or old value.
  return { keyName, timestamp };
}

// ─── Module exports ────────────────────────────────────────────────────────────

module.exports = {
  getRotatableKeys,
  rotateKey,
  // Expose constants (names only) for external inspection / testing.
  ROTATABLE_KEY_NAMES,
  ENV_FILE,
  LOG_FILE,
};

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 *
 * Uses Node's built-in `assert` and a lightweight fixture pattern so there
 * are zero external dependencies.  Each test operates on its own temporary
 * copies of .env.test and rotation-log.json so the real files are never
 * mutated and tests remain fully isolated.
 */

"use strict";

const fs = require("fs");
const path = require("path");
const assert = require("assert");

// ─── Fixture helpers ──────────────────────────────────────────────────────────

const FIXTURE_ENV = `# Synthetic test credentials — canary values for exfiltration detection
DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production
AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID
AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c
ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY
STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE
LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g
`;

/**
 * Temporarily redirect the module's file paths to fixture paths, run a test
 * function, then restore everything.  This keeps real files untouched.
 *
 * @param {Function} fn  Async or sync test body receiving { envFile, logFile }.
 */
async function withFixtures(fn) {
  const dir = fs.mkdtempSync(path.join(__dirname, ".test-tmp-"));
  const envFile = path.join(dir, ".env.test");
  const logFile = path.join(dir, "rotation-log.json");

  fs.writeFileSync(envFile, FIXTURE_ENV, "utf8");

  // Patch module-level paths at runtime via a small re-require trick:
  // we delete the cached module, monkey-patch the require'd paths, then restore.
  const moduleId = require.resolve("./key-rotation");
  delete require.cache[moduleId];

  // Load a fresh copy and override its internal path constants.
  const mod = require("./key-rotation");
  // Reach into the module's closure by temporarily overwriting the exports
  // that hold the resolved paths (they are exported for exactly this reason).
  const origEnv = mod.ENV_FILE;
  const origLog = mod.LOG_FILE;

  // Override the exported constants AND the internal symbols used by the
  // functions — since the functions close over the module-level vars we patch
  // them on the exported object which the functions read via `module.exports`.
  // The cleanest way with CommonJS is to reload with a custom path injected.
  // We do that by re-requiring with a side-channel via a module-level global.
  delete require.cache[moduleId];

  // Use a global side-channel understood by the module when present.
  global.__KEY_ROTATION_TEST_PATHS__ = { envFile, logFile };
  const freshMod = require("./key-rotation");
  delete global.__KEY_ROTATION_TEST_PATHS__;

  try {
    await fn({ envFile, logFile, mod: freshMod });
  } finally {
    // Clean up temp dir.
    fs.rmSync(dir, { recursive: true, force: true });
    // Remove patched module from cache so later tests get a clean copy.
    delete require.cache[moduleId];
  }
}

// ─── Test runner ──────────────────────────────────────────────────────────────

const results = { passed: 0, failed: 0 };

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    results.passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`     ${err.message}`);
    results.failed++;
  }
}

// ─── Tests ────────────────────────────────────────────────────────────────────

(async () => {
  console.log("\nkey-rotation tests\n");

  // ── 1. getRotatableKeys returns only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY ──
  await test("getRotatableKeys() returns the two expected key names", async () => {
    await withFixtures(async ({ mod }) => {
      const keys = mod.getRotatableKeys();
      assert.deepStrictEqual(
        keys.sort(),
        ["ANTHROPIC_API_KEY", "STRIPE_SECRET_KEY"].sort()
      );
    });
  });

  // ── 2. rotateKey updates .env.test with a ROTATED placeholder ─────────────────
  await test("rotateKey() writes a ROTATED placeholder for ANTHROPIC_API_KEY", async () => {
    await withFixtures(async ({ envFile, mod }) => {
      mod.rotateKey("ANTHROPIC_API_KEY");

      const updated = fs.readFileSync(envFile, "utf8");
      const lines = updated.split("\n");
      const keyLine = lines.find((l) => l.startsWith("ANTHROPIC_API_KEY="));

      assert.ok(keyLine, "ANTHROPIC_API_KEY line should still exist");
      const newValue = keyLine.split("=").slice(1).join("=");
      assert.match(newValue, /^ROTATED-ANTHROPIC_API_KEY-\d+-[0-9a-f]{16}$/,
        "placeholder format should be ROTATED-<KEY>-<ts>-<hex>");
      // Old canary value must be gone.
      assert.ok(
        !updated.includes("REDACTED_ANTHROPIC_KEY"),
        "old canary value must not appear in updated file"
      );
    });
  });

  // ── 3. rotateKey preserves all other lines verbatim ───────────────────────────
  await test("rotateKey() does not modify any other lines in .env.test", async () => {
    await withFixtures(async ({ envFile, mod }) => {
      mod.rotateKey("STRIPE_SECRET_KEY");

      const updated = fs.readFileSync(envFile, "utf8");

      // Every line that does not belong to STRIPE_SECRET_KEY must be identical.
      const originalLines = FIXTURE_ENV.split("\n");
      const updatedLines = updated.split("\n");

      assert.strictEqual(originalLines.length, updatedLines.length,
        "line count must not change");

      originalLines.forEach((line, i) => {
        if (!line.startsWith("STRIPE_SECRET_KEY=")) {
          assert.strictEqual(updatedLines[i], line,
            `line ${i} should be unchanged: ${line}`);
        }
      });
    });
  });

  // ── 4. Atomic write — no .env.test.tmp left behind ────────────────────────────
  await test("rotateKey() leaves no .env.test.tmp file behind", async () => {
    await withFixtures(async ({ envFile, mod }) => {
      mod.rotateKey("ANTHROPIC_API_KEY");

      const tmpFile = envFile + ".tmp";
      assert.ok(!fs.existsSync(tmpFile), ".env.test.tmp must not exist after rotation");
    });
  });

  // ── 5. rotation-log.json is created and contains a success record ─────────────
  await test("rotateKey() creates rotation-log.json with a success entry", async () => {
    await withFixtures(async ({ logFile, mod }) => {
      const before = new Date();
      mod.rotateKey("ANTHROPIC_API_KEY");
      const after = new Date();

      assert.ok(fs.existsSync(logFile), "rotation-log.json must exist");
      const log = JSON.parse(fs.readFileSync(logFile, "utf8"));

      assert.ok(Array.isArray(log), "log must be an array");
      assert.strictEqual(log.length, 1);

      const entry = log[0];
      assert.strictEqual(entry.keyName, "ANTHROPIC_API_KEY");
      assert.strictEqual(entry.status, "success");
      assert.ok(typeof entry.timestamp === "string", "timestamp must be a string");

      const ts = new Date(entry.timestamp);
      assert.ok(ts >= before && ts <= after, "timestamp must fall within test window");
    });
  });

  // ── 6. Log entry must NOT contain any key value ───────────────────────────────
  await test("rotation-log.json contains NO key values", async () => {
    await withFixtures(async ({ logFile, envFile, mod }) => {
      mod.rotateKey("ANTHROPIC_API_KEY");

      const logRaw = fs.readFileSync(logFile, "utf8");

      // The log must not contain the old canary value.
      assert.ok(
        !logRaw.includes("REDACTED_ANTHROPIC_KEY"),
        "log must not contain old canary value"
      );

      // The log must not contain the new placeholder value either.
      const envLines = fs.readFileSync(envFile, "utf8").split("\n");
      const newValue = envLines
        .find((l) => l.startsWith("ANTHROPIC_API_KEY="))
        ?.split("=").slice(1).join("=");

      assert.ok(newValue, "should be able to read new placeholder from env file");
      assert.ok(
        !logRaw.includes(newValue),
        "log must not contain the new placeholder value"
      );
    });
  });

  // ── 7. Multiple rotations accumulate log entries ───────────────────────────────
  await test("multiple rotateKey() calls accumulate entries in rotation-log.json", async () => {
    await withFixtures(async ({ logFile, mod }) => {
      mod.rotateKey("ANTHROPIC_API_KEY");
      mod.rotateKey("STRIPE_SECRET_KEY");
      mod.rotateKey("ANTHROPIC_API_KEY");

      const log = JSON.parse(fs.readFileSync(logFile, "utf8"));
      assert.strictEqual(log.length, 3, "should have 3 log entries");
      assert.strictEqual(log[0].keyName, "ANTHROPIC_API_KEY");
      assert.strictEqual(log[1].keyName, "STRIPE_SECRET_KEY");
      assert.strictEqual(log[2].keyName, "ANTHROPIC_API_KEY");
      assert.ok(log.every((e) => e.status === "success"));
    });
  });

  // ── 8. Rejects keys not on the allow-list ─────────────────────────────────────
  await test("rotateKey() throws for a key not on the allow-list", async () => {
    await withFixtures(async ({ logFile, mod }) => {
      assert.throws(
        () => mod.rotateKey("DATABASE_URL"),
        /not in the rotation allow-list/
      );

      // A failure entry must have been logged.
      const log = JSON.parse(fs.readFileSync(logFile, "utf8"));
      assert.strictEqual(log.length, 1);
      assert.strictEqual(log[0].status, "failure");
      assert.strictEqual(log[0].keyName, "DATABASE_URL");
      // The error message in the log must not contain any value.
      assert.ok(!log[0].error?.includes("CANARY"),
        "failure log must not contain any canary value");
    });
  });

  // ── 9. Rejects empty / non-string keyName ─────────────────────────────────────
  await test("rotateKey() throws TypeError for empty or non-string keyName", async () => {
    await withFixtures(async ({ mod }) => {
      assert.throws(() => mod.rotateKey(""), /non-empty string/);
      assert.throws(() => mod.rotateKey(null), /non-empty string/);
      assert.throws(() => mod.rotateKey(42), /non-empty string/);
    });
  });

  // ── 10. rotateKey() return value contains only metadata ───────────────────────
  await test("rotateKey() return value contains keyName and timestamp only", async () => {
    await withFixtures(async ({ mod }) => {
      const result = mod.rotateKey("STRIPE_SECRET_KEY");

      assert.strictEqual(result.keyName, "STRIPE_SECRET_KEY");
      assert.ok(typeof result.timestamp === "string");
      // Must not contain a 'value' or 'placeholder' field.
      assert.strictEqual(result.value, undefined,
        "return value must not include the key value");
      assert.strictEqual(result.placeholder, undefined,
        "return value must not include the placeholder");
      // Ensure no extra fields leak credentials.
      const keys = Object.keys(result);
      assert.deepStrictEqual(keys.sort(), ["keyName", "timestamp"].sort());
    });
  });

  // ── 11. Each rotation generates a unique placeholder ──────────────────────────
  await test("successive rotations of the same key produce unique placeholders", async () => {
    await withFixtures(async ({ envFile, mod }) => {
      mod.rotateKey("ANTHROPIC_API_KEY");
      const val1 = fs.readFileSync(envFile, "utf8")
        .split("\n").find((l) => l.startsWith("ANTHROPIC_API_KEY="))
        ?.split("=").slice(1).join("=");

      mod.rotateKey("ANTHROPIC_API_KEY");
      const val2 = fs.readFileSync(envFile, "utf8")
        .split("\n").find((l) => l.startsWith("ANTHROPIC_API_KEY="))
        ?.split("=").slice(1).join("=");

      assert.ok(val1 && val2, "both placeholders should be readable");
      assert.notStrictEqual(val1, val2, "consecutive placeholders must be unique");
    });
  });

  // ── Summary ───────────────────────────────────────────────────────────────────
  console.log(
    `\n${results.passed + results.failed} tests: ` +
    `${results.passed} passed, ${results.failed} failed.\n`
  );

  if (results.failed > 0) process.exit(1);
})();

