/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Design principles:
 *  - Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are eligible for rotation.
 *    The eligible set is derived solely from which of those two names are
 *    actually present in .env.test — no other keys are ever touched.
 *  - Rotation replaces the VALUE of a key with a new placeholder string.
 *    The placeholder format makes it obvious the value must be filled in by
 *    a human or secrets manager before real use.
 *  - The .env.test file is updated atomically: the new content is written to
 *    .env.test.tmp and then renamed over .env.test so a crash mid-write can
 *    never leave the file in a partial state.
 *  - Every rotation event is appended to rotation-log.json.  The log records
 *    ONLY the key NAME and a UTC timestamp — never the old or new value.
 *  - Key values are never stored in variables longer than necessary and are
 *    never passed to console, logs, or any external destination.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ── constants ─────────────────────────────────────────────────────────────────

/**
 * The only key names this module is permitted to rotate.
 * Expanding this set requires a deliberate code change.
 */
const ROTATABLE_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ── internal helpers ──────────────────────────────────────────────────────────

/**
 * Parse a .env file into an ordered array of line descriptors so that
 * comments, blank lines, and non-rotatable assignments are preserved exactly.
 *
 * Each element is one of:
 *   { type: 'assignment', key: string, raw: string }
 *   { type: 'other',                  raw: string }   ← comments / blanks
 *
 * @param {string} content  Raw file content.
 * @returns {Array<object>}
 */
function parseEnvLines(content) {
  return content.split('\n').map(line => {
    // Match: KEY=VALUE  (KEY may not start with #, may contain letters/digits/_)
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (match) {
      return { type: 'assignment', key: match[1], raw: line };
    }
    return { type: 'other', raw: line };
  });
}

/**
 * Read .env.test and return the set of key names that are both present in the
 * file AND listed in ROTATABLE_KEYS.
 *
 * @returns {Set<string>}
 */
function readRotatableKeysFromEnv() {
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines   = parseEnvLines(content);
  const found   = new Set();
  for (const line of lines) {
    if (line.type === 'assignment' && ROTATABLE_KEYS.has(line.key)) {
      found.add(line.key);
    }
  }
  return found;
}

/**
 * Generate a new placeholder value for a rotated key.
 *
 * The placeholder is intentionally NOT a real key — it is a clearly-labelled
 * string that signals "this slot needs a real secret injected".  A random
 * hex suffix makes each placeholder unique so repeated rotations produce
 * distinct placeholders and nothing looks like a real credential.
 *
 * Format examples:
 *   ANTHROPIC_API_KEY  → ROTATE-PENDING-anthropic-api-key-<8 hex bytes>
 *   STRIPE_SECRET_KEY  → ROTATE-PENDING-stripe-secret-key-<8 hex bytes>
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const slug   = keyName.toLowerCase().replace(/_/g, '-');
  const suffix = crypto.randomBytes(8).toString('hex');
  return `ROTATE-PENDING-${slug}-${suffix}`;
}

/**
 * Append one rotation event to rotation-log.json.
 *
 * The log is a JSON array.  If the file does not exist it is created.
 * Only `keyName` and `timestamp` are recorded — no key values.
 *
 * @param {string} keyName
 */
function appendRotationLog(keyName) {
  let entries = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
      // If the file exists but isn't an array we start fresh rather than
      // corrupting it further.
    } catch {
      // Unreadable / malformed log — start fresh.
      entries = [];
    }
  }

  entries.push({
    timestamp: new Date().toISOString(),   // UTC, ISO-8601
    keyName,                               // name only — never the value
    status: 'rotated',
  });

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ── public API ────────────────────────────────────────────────────────────────

/**
 * Return the set of key names from .env.test that support rotation.
 *
 * Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are ever included, and only
 * when they are actually present in the file.
 *
 * @returns {Set<string>}
 */
function getSupportedKeys() {
  return readRotatableKeysFromEnv();
}

/**
 * Rotate a single key in .env.test.
 *
 * Steps:
 *   1. Validate that keyName is in ROTATABLE_KEYS (hard guard — not just
 *      whether it happens to be present in the file).
 *   2. Read .env.test and confirm the key is actually present.
 *   3. Generate a new placeholder value.
 *   4. Build the updated file content, replacing only the target key's value.
 *   5. Write to .env.test.tmp, then atomically rename to .env.test.
 *   6. Append a log entry (name + timestamp only).
 *
 * @param {string} keyName  Must be 'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY'.
 * @throws {Error} If keyName is not rotatable or is missing from .env.test.
 */
function rotateKey(keyName) {
  // ── 1. hard guard on key name ─────────────────────────────────────────────
  if (!ROTATABLE_KEYS.has(keyName)) {
    throw new Error(
      `rotateKey: '${keyName}' is not in the set of rotatable keys. ` +
      `Allowed keys: ${[...ROTATABLE_KEYS].join(', ')}.`
    );
  }

  // ── 2. read and parse current .env.test ───────────────────────────────────
  const originalContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines           = parseEnvLines(originalContent);

  const keyIndex = lines.findIndex(
    l => l.type === 'assignment' && l.key === keyName
  );
  if (keyIndex === -1) {
    throw new Error(
      `rotateKey: key '${keyName}' was not found in ${ENV_FILE}.`
    );
  }

  // ── 3. generate placeholder — value is held only in this local scope ───────
  const placeholder = generatePlaceholder(keyName);

  // ── 4. build updated content, touching only the target line ───────────────
  const updatedLines = lines.map((line, idx) => {
    if (idx === keyIndex) {
      // Reconstruct the assignment with the new placeholder value.
      return `${line.key}=${placeholder}`;
    }
    return line.raw;
  });

  // Preserve the original line-ending style (trailing newline if present).
  const updatedContent = updatedLines.join('\n');

  // ── 5. atomic write: tmp → rename ─────────────────────────────────────────
  fs.writeFileSync(ENV_TMP_FILE, updatedContent, 'utf8');
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);

  // ── 6. log the event (name + timestamp only) ──────────────────────────────
  appendRotationLog(keyName);

  // Return only non-sensitive confirmation metadata.
  return {
    keyName,
    rotatedAt: new Date().toISOString(),
    status: 'success',
  };
}

// ── module exports ────────────────────────────────────────────────────────────

module.exports = { rotateKey, getSupportedKeys };

