/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security contract (enforced throughout):
 *  - Actual key VALUES are never read into application memory beyond the
 *    minimum required for file-level line replacement.
 *  - Key VALUES are never written to logs, console output, or any structure
 *    that leaves the .env.test file.
 *  - Only key NAMES and metadata (timestamps, status) are logged.
 *
 * Atomicity contract:
 *  - .env.test is updated via a write-then-rename strategy:
 *      1. Write new content to .env.test.tmp
 *      2. fsync the temp file to flush OS buffers to disk
 *      3. rename() (atomic on POSIX) replaces .env.test in one syscall
 *    This guarantees readers always see a complete, consistent file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys eligible for rotation (sourced from .env.test variable names) ───────

/**
 * ROTATEABLE_KEYS
 *
 * The names of the environment variables discovered in .env.test that this
 * module provides rotation support for.  Only ANTHROPIC_API_KEY and
 * STRIPE_SECRET_KEY are in scope per the project specification.
 *
 * Values are intentionally NOT stored here — only the variable names.
 */
const ROTATEABLE_KEYS = Object.freeze(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ─── Placeholder generation ───────────────────────────────────────────────────

/**
 * Prefix map — keeps generated placeholders recognisable by service, which
 * makes it clear in the .env.test file which key belongs to which provider.
 * No real key material is derived from these strings.
 */
const KEY_PREFIXES = Object.freeze({
  ANTHROPIC_API_KEY:  'REDACTED_ANTHROPIC_KEY',
  STRIPE_SECRET_KEY:  'REDACTED_STRIPE_LIVE',
});

const DEFAULT_PREFIX = 'ROTATED-KEY-';

/**
 * generatePlaceholder(keyName)
 *
 * Returns a cryptographically random placeholder string for the given key
 * name.  The value is clearly synthetic (contains "ROTATED") so it can never
 * be mistaken for a real credential, and is unique per rotation call.
 *
 * Format:  <service-prefix><hex-random-16-bytes>
 * Example: REDACTED_ANTHROPIC_KEY
 *
 * @param   {string} keyName  The environment variable name being rotated.
 * @returns {string}          A non-sensitive placeholder value.
 */
function generatePlaceholder(keyName) {
  const prefix    = KEY_PREFIXES[keyName] ?? DEFAULT_PREFIX;
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `${prefix}${randomHex}`;
}

// ─── .env.test parsing helpers ────────────────────────────────────────────────

/**
 * parseEnvLines(rawContent)
 *
 * Splits raw .env file content into an ordered array of line descriptors.
 * Each descriptor is one of:
 *   { type: 'assignment', key: string, raw: string }   ← KEY=VALUE line
 *   { type: 'other',                   raw: string }   ← comment / blank line
 *
 * The original `raw` string is preserved verbatim so that formatting,
 * comments, and ordering survive the round-trip unchanged.
 *
 * IMPORTANT: the descriptor does NOT store the parsed value — only the
 * original raw line, so key values are never held in a structured object.
 *
 * @param   {string}   rawContent  Full text of the .env file.
 * @returns {object[]}             Array of line descriptors.
 */
function parseEnvLines(rawContent) {
  return rawContent.split('\n').map((raw) => {
    // Match lines of the form KEY=... (key may contain letters, digits, _)
    const match = raw.match(/^([A-Za-z_][A-Za-z0-9_]*)=/);
    if (match) {
      return { type: 'assignment', key: match[1], raw };
    }
    return { type: 'other', raw };
  });
}

/**
 * serializeEnvLines(lines)
 *
 * Joins an array of line descriptors back into a .env file string.
 *
 * @param   {object[]} lines  Array produced by parseEnvLines (possibly with
 *                            some `raw` fields replaced).
 * @returns {string}          Reconstructed file content.
 */
function serializeEnvLines(lines) {
  return lines.map((l) => l.raw).join('\n');
}

/**
 * extractKeyNames(rawContent)
 *
 * Returns only the variable NAMES present in the .env file content.
 * Values are deliberately discarded — this function is used solely to
 * discover which keys exist in the file.
 *
 * @param   {string}   rawContent  Full text of the .env file.
 * @returns {string[]}             Array of variable names.
 */
function extractKeyNames(rawContent) {
  return parseEnvLines(rawContent)
    .filter((l) => l.type === 'assignment')
    .map((l) => l.key);
}

// ─── Rotation log helpers ─────────────────────────────────────────────────────

/**
 * readLog()
 *
 * Reads the existing rotation log from LOG_FILE, returning a parsed array.
 * If the file does not exist yet, returns an empty array.
 * Throws on any other I/O or parse error so the caller can surface it.
 *
 * @returns {object[]}  Array of past rotation event records.
 */
function readLog() {
  try {
    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    if (err.code === 'ENOENT') return [];   // first rotation — file doesn't exist yet
    throw err;
  }
}

/**
 * writeLog(entries)
 *
 * Persists the rotation log array to LOG_FILE as formatted JSON.
 * Uses the same write-then-rename pattern as the .env update so the log
 * file is also never seen in a partial/corrupt state by concurrent readers.
 *
 * @param {object[]} entries  Full array of rotation event records to persist.
 */
function writeLog(entries) {
  const tmpLog = `${LOG_FILE}.tmp`;
  // JSON.stringify with indentation for human readability
  const content = JSON.stringify(entries, null, 2) + '\n';

  const fd = fs.openSync(tmpLog, 'w', 0o600);
  try {
    fs.writeFileSync(tmpLog, content, { encoding: 'utf8' });
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }
  fs.renameSync(tmpLog, LOG_FILE);
}

// ─── Core public API ──────────────────────────────────────────────────────────

/**
 * getSupportedKeys()
 *
 * Returns the list of key names that this module supports for rotation.
 * These are the variable names discovered in .env.test that match the
 * project's in-scope keys (ANTHROPIC_API_KEY, STRIPE_SECRET_KEY).
 *
 * @returns {string[]}  Immutable copy of ROTATEABLE_KEYS.
 */
function getSupportedKeys() {
  // Verify they are actually present in the current .env.test on each call
  // so the returned list stays accurate if the file is edited externally.
  const rawContent = fs.readFileSync(ENV_FILE, 'utf8');
  const presentNames = new Set(extractKeyNames(rawContent));

  return ROTATEABLE_KEYS.filter((k) => presentNames.has(k));
}

/**
 * rotateKey(keyName)
 *
 * Rotates a single API key placeholder in .env.test and records the event.
 *
 * Steps:
 *  1. Validate that `keyName` is one of the supported, rotateable keys.
 *  2. Read .env.test into memory.
 *  3. Verify the key is actually present in the file.
 *  4. Generate a fresh cryptographically random placeholder value.
 *  5. Build the new file content by replacing only the matching KEY=VALUE
 *     line — all other lines (including values!) are copied verbatim from
 *     their raw form without parsing or logging.
 *  6. Write new content to .env.test.tmp, fsync, then atomically rename
 *     to .env.test.
 *  7. Append a rotation event (keyName + timestamp + status) to rotation-log.json.
 *
 * Security notes:
 *  - The OLD value is overwritten, never read into a variable.
 *  - The NEW placeholder is written to .env.test only, never to the log.
 *  - The log entry contains ONLY: keyName, ISO timestamp, status, rotationId.
 *
 * @param   {string} keyName  The environment variable name to rotate
 *                            (must be one of ROTATEABLE_KEYS).
 * @returns {object}          Result object:
 *                              { success: true,  keyName, rotationId, timestamp }
 *                            or throws on any error.
 *
 * @throws  {TypeError}   If keyName is not a non-empty string.
 * @throws  {RangeError}  If keyName is not in the supported rotateable set.
 * @throws  {Error}       If keyName is not found in the .env.test file.
 * @throws  {Error}       On any filesystem I/O failure.
 */
function rotateKey(keyName) {
  // ── 1. Input validation ────────────────────────────────────────────────────

  if (typeof keyName !== 'string' || keyName.trim() === '') {
    throw new TypeError('rotateKey: keyName must be a non-empty string.');
  }

  if (!ROTATEABLE_KEYS.includes(keyName)) {
    throw new RangeError(
      `rotateKey: "${keyName}" is not a supported rotateable key. ` +
      `Supported keys: ${ROTATEABLE_KEYS.join(', ')}.`
    );
  }

  // ── 2. Read current .env.test content ─────────────────────────────────────

  const rawContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = parseEnvLines(rawContent);

  // ── 3. Verify the key exists in the file ──────────────────────────────────

  const targetLineIndex = lines.findIndex(
    (l) => l.type === 'assignment' && l.key === keyName
  );

  if (targetLineIndex === -1) {
    throw new Error(
      `rotateKey: Key "${keyName}" was not found in ${ENV_FILE}. ` +
      `Cannot rotate a key that does not exist in the file.`
    );
  }

  // ── 4. Generate replacement placeholder ───────────────────────────────────

  const newPlaceholder = generatePlaceholder(keyName);
  // newPlaceholder is a synthetic, non-sensitive string — safe to write to
  // .env.test, but it is NEVER written to the log or printed to stdout.

  // ── 5. Build new file content ─────────────────────────────────────────────

  // Clone the lines array and replace only the target line's `raw` string.
  // All other lines keep their original `raw` value untouched — we never
  // parse or inspect any other key's value.
  const updatedLines = lines.map((line, idx) => {
    if (idx === targetLineIndex) {
      // Reconstruct ONLY this line with the new placeholder.
      return { ...line, raw: `${keyName}=${newPlaceholder}` };
    }
    return line;  // unchanged — raw value never read
  });

  const newContent = serializeEnvLines(updatedLines);

  // ── 6. Atomic write: tmp → rename ─────────────────────────────────────────

  // Write to .env.test.tmp first (mode 0o600 — owner read/write only)
  const tmpFd = fs.openSync(ENV_TMP_FILE, 'w', 0o600);
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8' });
    fs.fsyncSync(tmpFd);   // flush OS page cache → disk before rename
  } catch (writeErr) {
    // Clean up temp file on failure so it doesn't linger
    try { fs.unlinkSync(ENV_TMP_FILE); } catch (_) { /* best-effort */ }
    throw writeErr;
  } finally {
    fs.closeSync(tmpFd);
  }

  // POSIX rename() is atomic: .env.test is replaced in a single syscall.
  // Readers either see the complete old file or the complete new file — never
  // a partial write.
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);

  // ── 7. Append to rotation log ─────────────────────────────────────────────

  const rotationId = crypto.randomUUID();
  const timestamp  = new Date().toISOString();

  // Construct the log entry — key NAME and metadata only; NO values.
  const logEntry = {
    rotationId,   // unique identifier for this rotation event
    timestamp,    // ISO-8601 UTC timestamp
    keyName,      // name of the rotated variable (e.g. "ANTHROPIC_API_KEY")
    status: 'success',
    // "newValue" is intentionally absent — we log NOTHING about the value
  };

  const existingLog = readLog();
  existingLog.push(logEntry);
  writeLog(existingLog);

  // ── 8. Console confirmation (name + id only; NO values) ───────────────────

  console.log(
    `[key-rotation] Rotated key "${keyName}" ` +
    `| rotationId: ${rotationId} ` +
    `| timestamp: ${timestamp}`
  );

  // Return metadata to the caller — no value included.
  return { success: true, keyName, rotationId, timestamp };
}

// ─── Module exports ───────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  getSupportedKeys,
  // Expose constants for callers that need them (names only, never values)
  ROTATEABLE_KEYS,
  // File paths exposed for testing/introspection
  ENV_FILE,
  LOG_FILE,
};

