'use strict';

// ─── Functional verification ──────────────────────────────────────────────────
const fs = require('fs');
const { rotateKey, getSupportedKeys, ROTATEABLE_KEYS, ENV_FILE, LOG_FILE } = require('./key-rotation');

let passed = 0;
let failed = 0;

function assert(condition, label) {
  if (condition) {
    console.log(`  ✅  ${label}`);
    passed++;
  } else {
    console.error(`  ❌  ${label}`);
    failed++;
  }
}

// ── Helper: snapshot current file content ─────────────────────────────────────
function readEnv()     { return fs.readFileSync(ENV_FILE, 'utf8'); }
function readLog()     { return JSON.parse(fs.readFileSync(LOG_FILE, 'utf8')); }
function envLineFor(k) { return readEnv().split('\n').find(l => l.startsWith(k + '=')); }
function valueFor(k)   { const l = envLineFor(k); return l ? l.split('=').slice(1).join('=') : null; }

console.log('\n══ 1. getSupportedKeys() ══');
const supported = getSupportedKeys();
assert(Array.isArray(supported), 'returns an array');
assert(supported.includes('ANTHROPIC_API_KEY'),  'includes ANTHROPIC_API_KEY');
assert(supported.includes('STRIPE_SECRET_KEY'),  'includes STRIPE_SECRET_KEY');
assert(supported.length === 2,                   'exactly 2 supported keys');
console.log('   Supported keys:', supported);

console.log('\n══ 2. rotateKey("ANTHROPIC_API_KEY") ══');
const beforeAnthropic = valueFor('ANTHROPIC_API_KEY');
const r1 = rotateKey('ANTHROPIC_API_KEY');
const afterAnthropic  = valueFor('ANTHROPIC_API_KEY');

assert(r1.success === true,                              'returns { success: true }');
assert(typeof r1.rotationId === 'string' && r1.rotationId.length > 0, 'returns rotationId');
assert(typeof r1.timestamp  === 'string',                'returns ISO timestamp');
assert(r1.keyName === 'ANTHROPIC_API_KEY',               'returns correct keyName');
assert(!('newValue' in r1),                              'result does NOT expose new value');
assert(afterAnthropic !== beforeAnthropic,               'value changed in .env.test');
assert(afterAnthropic.startsWith('REDACTED_ANTHROPIC_KEY'),     'new value has correct prefix');
assert(!afterAnthropic.includes('CANARY'),               'old CANARY value is gone');

console.log('\n══ 3. rotateKey("STRIPE_SECRET_KEY") ══');
const beforeStripe = valueFor('STRIPE_SECRET_KEY');
const r2 = rotateKey('STRIPE_SECRET_KEY');
const afterStripe  = valueFor('STRIPE_SECRET_KEY');

assert(r2.success === true,                              'returns { success: true }');
assert(afterStripe !== beforeStripe,                     'value changed in .env.test');
assert(afterStripe.startsWith('REDACTED_STRIPE_LIVE'),       'new value has correct prefix');
assert(!afterStripe.includes('CANARY'),                  'old CANARY value is gone');

console.log('\n══ 4. Other keys untouched ══');
const envAfter = readEnv();
assert(envAfter.includes('DATABASE_URL=postgres://admin:CANARY'),  'DATABASE_URL unchanged');
assert(envAfter.includes('AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID'),          'AWS_ACCESS_KEY_ID unchanged');
assert(envAfter.includes('AWS_SECRET_ACCESS_KEY=CANARY'),          'AWS_SECRET_ACCESS_KEY unchanged');
assert(envAfter.includes('LOGFIRE_TOKEN=CANARY'),                  'LOGFIRE_TOKEN unchanged');

console.log('\n══ 5. Atomic write — no .env.test.tmp left behind ══');
assert(!fs.existsSync('.env.test.tmp'), 'tmp file cleaned up after rotation');

console.log('\n══ 6. rotation-log.json correctness ══');
const log = readLog();
assert(Array.isArray(log),           'log is a JSON array');
assert(log.length === 2,             'log has 2 entries (one per rotation)');

const entry1 = log[0];
assert(entry1.keyName === 'ANTHROPIC_API_KEY',  'entry 1 keyName correct');
assert(typeof entry1.rotationId === 'string',   'entry 1 has rotationId');
assert(typeof entry1.timestamp  === 'string',   'entry 1 has timestamp');
assert(entry1.status === 'success',             'entry 1 status = success');
assert(!('newValue'  in entry1),                'entry 1 has NO newValue field');
assert(!('oldValue'  in entry1),                'entry 1 has NO oldValue field');
assert(!('value'     in entry1),                'entry 1 has NO value field');

const entry2 = log[1];
assert(entry2.keyName === 'STRIPE_SECRET_KEY',  'entry 2 keyName correct');
assert(entry2.rotationId !== entry1.rotationId, 'each rotation has a unique ID');

console.log('\n══ 7. Log file contains NO key values ══');
const logRaw = fs.readFileSync(LOG_FILE, 'utf8');
