/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Design principles / security guarantees
 * ────────────────────────────────────────
 *  • Key VALUES are never read into application memory beyond the narrow scope
 *    where the raw .env.test line is being rewritten.
 *  • Key VALUES are never logged, printed, returned, or included in any
 *    data structure that leaves this module.
 *  • rotation-log.json records only: timestamp, keyName, and outcome.
 *  • The .env.test file is updated atomically: content is first written to
 *    .env.test.tmp, then renamed over .env.test so a crash mid-write cannot
 *    leave the file in a partially-written state.
 *  • Only the two key names that are present in .env.test at start-up
 *    (ANTHROPIC_API_KEY and STRIPE_SECRET_KEY) are eligible for rotation;
 *    any attempt to rotate an unknown name is rejected.
 */

"use strict";

const fs   = require("fs");
const path = require("path");
const crypto = require("crypto");

// ── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, ".env.test");
const ENV_TMP_FILE = path.resolve(__dirname, ".env.test.tmp");
const LOG_FILE     = path.resolve(__dirname, "rotation-log.json");

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Parses .env.test and returns only the *names* of the keys whose lines match
 * the standard KEY=VALUE format.  Values are intentionally discarded.
 *
 * @returns {Set<string>} Set of environment variable names found in the file.
 */
function _readKeyNames() {
  const raw = fs.readFileSync(ENV_FILE, "utf8");
  const names = new Set();

  for (const line of raw.split("\n")) {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith("#")) continue;

    const eqIdx = trimmed.indexOf("=");
    if (eqIdx < 1) continue;

    const name = trimmed.slice(0, eqIdx).trim();
    if (name) names.add(name);
  }

  return names;
}

/**
 * Generates a new placeholder value for the given key name.
 *
 * Format: <prefix>-ROTATED-<16 random hex bytes>
 *
 * The prefix mirrors the convention already used in .env.test so the file
 * remains self-documenting.  The random component uses crypto.randomBytes so
 * the value is cryptographically unpredictable.
 *
 * @param {string} keyName  The environment variable name.
 * @returns {string}        The new placeholder value (NOT a real secret).
 */
function _generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString("hex");

  const prefixMap = {
    ANTHROPIC_API_KEY: "REDACTED_ANTHROPIC_KEY",
    STRIPE_SECRET_KEY: "REDACTED_STRIPE_LIVE",
  };

  const prefix = prefixMap[keyName] ?? "ROTATED";
  return `${prefix}-${randomHex}`;
}

/**
 * Rewrites .env.test atomically, replacing the value for `keyName` with
 * `newPlaceholder`.
 *
 * Atomic write strategy:
 *   1. Build the full new file content in memory.
 *   2. Write to .env.test.tmp (O_WRONLY | O_CREAT | O_TRUNC).
 *   3. fsync the tmp file to flush OS buffers to disk.
 *   4. Close the tmp file descriptor.
 *   5. fs.renameSync(.env.test.tmp → .env.test)  — atomic on POSIX systems.
 *
 * @param {string} keyName         The environment variable name to update.
 * @param {string} newPlaceholder  The replacement value.
 */
function _atomicUpdateEnvFile(keyName, newPlaceholder) {
  const raw = fs.readFileSync(ENV_FILE, "utf8");

  let matched = false;
  const updatedLines = raw.split("\n").map((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) return line;

    const eqIdx = trimmed.indexOf("=");
    if (eqIdx < 1) return line;

    const name = trimmed.slice(0, eqIdx).trim();
    if (name !== keyName) return line;

    matched = true;
    // Preserve any leading whitespace the original line had, then rewrite value.
    const leadingSpace = line.slice(0, line.indexOf(trimmed[0]));
    return `${leadingSpace}${keyName}=${newPlaceholder}`;
  });

  if (!matched) {
    throw new Error(
      `Key "${keyName}" was not found as an assignment in ${ENV_FILE}.`
    );
  }

  const newContent = updatedLines.join("\n");

  // --- Atomic write ---------------------------------------------------------
  // Write to tmp file, fsync, then rename.
  const fd = fs.openSync(ENV_TMP_FILE, "w", 0o600);
  try {
    fs.writeSync(fd, newContent, 0, "utf8");
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }

  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

/**
 * Appends a rotation event record to rotation-log.json.
 *
 * The log file holds a JSON array.  If the file does not exist or contains
 * invalid JSON it is (re-)initialised to an empty array before appending.
 *
 * Only the following fields are written — the key VALUE is never included:
 *   {
 *     "timestamp": "<ISO-8601 UTC string>",
 *     "keyName":   "<variable name>",
 *     "outcome":   "success" | "failure",
 *     "error":     "<message>"   // only present on failure
 *   }
 *
 * @param {string}      keyName  The variable name that was rotated.
 * @param {"success"|"failure"} outcome
 * @param {string|null} [errorMessage]  Human-readable error (no secrets).
 */
function _appendRotationLog(keyName, outcome, errorMessage = null) {
  // Read existing log array (best-effort).
  let logEntries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, "utf8");
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logEntries = parsed;
      }
    } catch {
      // Corrupted log — start fresh rather than crash.
      logEntries = [];
    }
  }

  /** @type {Record<string, string>} */
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,
    outcome,
  };

  if (outcome === "failure" && errorMessage) {
    entry.error = errorMessage;
  }

  logEntries.push(entry);

  // Write log atomically using the same tmp-then-rename pattern.
  const tmpLog = LOG_FILE + ".tmp";
  const fd = fs.openSync(tmpLog, "w", 0o600);
  try {
    fs.writeSync(fd, JSON.stringify(logEntries, null, 2) + "\n", 0, "utf8");
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }
  fs.renameSync(tmpLog, LOG_FILE);
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Returns the set of key names that are eligible for rotation — i.e. those
 * actually present in .env.test at the time of the call.
 *
 * This is intentionally limited to the keys the spec identified
 * (ANTHROPIC_API_KEY, STRIPE_SECRET_KEY) intersected with what exists in the
 * file, so callers have a precise allow-list.
 *
 * @returns {Set<string>}
 */
function getRotatableKeys() {
  const ALLOWED = new Set(["ANTHROPIC_API_KEY", "STRIPE_SECRET_KEY"]);
  const present = _readKeyNames();

  const rotatableKeys = new Set();
  for (const name of ALLOWED) {
    if (present.has(name)) rotatableKeys.add(name);
  }
  return rotatableKeys;
}

/**
 * Rotates the placeholder value for `keyName` in .env.test.
 *
 * Steps:
 *  1. Validate that `keyName` is in the allow-list AND present in .env.test.
 *  2. Generate a new cryptographically random placeholder value.
 *  3. Atomically rewrite .env.test with the new placeholder.
 *  4. Log the event (timestamp + keyName + outcome) to rotation-log.json.
 *
 * The function intentionally does NOT return the new placeholder value so
 * callers cannot accidentally log it.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @throws {Error} If `keyName` is not in the allow-list, is not present in
 *                 .env.test, or if the file write fails.
 */
function rotateKey(keyName) {
  // ── 1. Validate ────────────────────────────────────────────────────────────
  if (typeof keyName !== "string" || !keyName.trim()) {
    const msg = "rotateKey: keyName must be a non-empty string.";
    _appendRotationLog(String(keyName), "failure", msg);
    throw new Error(msg);
  }

  const rotatableKeys = getRotatableKeys();

  if (!rotatableKeys.has(keyName)) {
    const msg = `rotateKey: "${keyName}" is not an eligible key for rotation. ` +
      `Eligible keys: ${[...rotatableKeys].join(", ") || "(none found in .env.test)"}.`;
    _appendRotationLog(keyName, "failure", msg);
    throw new Error(msg);
  }

  // ── 2. Generate placeholder ────────────────────────────────────────────────
  // _generatePlaceholder is called but its return value stays in a local
  // variable that is only forwarded to the file-write function — never logged.
  const newPlaceholder = _generatePlaceholder(keyName);

  // ── 3. Atomic file update ──────────────────────────────────────────────────
  try {
    _atomicUpdateEnvFile(keyName, newPlaceholder);
  } catch (err) {
    // Sanitise the error message before logging: if the system error somehow
    // contains file content, strip anything that looks like a key value.
    const safeMsg = _sanitiseErrorMessage(err.message);
    _appendRotationLog(keyName, "failure", safeMsg);
    throw new Error(`rotateKey: failed to update ${ENV_FILE}: ${safeMsg}`);
  }

  // ── 4. Log success (name + timestamp only — no value) ─────────────────────
  _appendRotationLog(keyName, "success");

  // Intentionally no return value so the new placeholder cannot leak via
  // a forgotten console.log(rotateKey(...)) call.
}

/**
 * Removes anything from an error message that could be a secret value:
 * strips long alphanumeric tokens (≥ 8 chars after a non-word boundary or
 * '=' sign) to prevent accidental leakage of key material in error text.
 *
 * @param {string} message
 * @returns {string}
 */
function _sanitiseErrorMessage(message) {
  if (typeof message !== "string") return String(message);
  // Replace patterns like "=<token>" or standalone tokens ≥ 20 chars
  return message
    .replace(/=\S+/g, "=<redacted>")
    .replace(/\b[A-Za-z0-9_\-]{20,}\b/g, "<redacted>");
}

// ── Module exports ────────────────────────────────────────────────────────────

module.exports = { rotateKey, getRotatableKeys };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 *
 * All tests operate on temporary copies of .env.test and rotation-log.json
 * so the real files are never modified during the test run.
 */

"use strict";

const fs   = require("fs");
const path = require("path");

// ── Fixtures ──────────────────────────────────────────────────────────────────

const ORIG_ENV_FILE = path.resolve(__dirname, ".env.test");
const ORIG_LOG_FILE = path.resolve(__dirname, "rotation-log.json");

// Paths the module actually uses (we swap them via module re-require after
// overriding the constants — simpler: we just use a temp directory and copy).

// Snapshot the original .env.test so we can restore it after each test.
const ORIGINAL_ENV_CONTENT = fs.readFileSync(ORIG_ENV_FILE, "utf8");

// Clean up any leftover log from a previous run so test counts are reliable.
function resetLog() {
  if (fs.existsSync(ORIG_LOG_FILE)) fs.unlinkSync(ORIG_LOG_FILE);
}

function resetEnv() {
  fs.writeFileSync(ORIG_ENV_FILE, ORIGINAL_ENV_CONTENT, "utf8");
}

// Re-require with a clean module cache so each test group starts fresh.
function freshModule() {
  delete require.cache[require.resolve("./key-rotation")];
  return require("./key-rotation");
}

// ── Minimal test harness ──────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (!condition) throw new Error(`Assertion failed: ${message}`);
}

function assertEqual(a, b, message) {
  if (a !== b)
    throw new Error(`${message} — expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
}

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

// ── Test groups ───────────────────────────────────────────────────────────────

console.log("\n── getRotatableKeys ─────────────────────────────────────────────");

await test("returns a Set", () => {
  resetEnv(); resetLog();
  const { getRotatableKeys } = freshModule();
  assert(getRotatableKeys() instanceof Set, "should be a Set");
});

await test("contains ANTHROPIC_API_KEY", () => {
  resetEnv();
  const { getRotatableKeys } = freshModule();
  assert(getRotatableKeys().has("ANTHROPIC_API_KEY"), "must include ANTHROPIC_API_KEY");
});

await test("contains STRIPE_SECRET_KEY", () => {
  resetEnv();
  const { getRotatableKeys } = freshModule();
  assert(getRotatableKeys().has("STRIPE_SECRET_KEY"), "must include STRIPE_SECRET_KEY");
});

await test("does NOT include non-rotatable keys (e.g. DATABASE_URL)", () => {
  resetEnv();
  const { getRotatableKeys } = freshModule();
  assert(!getRotatableKeys().has("DATABASE_URL"), "DATABASE_URL should not be rotatable");
});

await test("does NOT include non-rotatable keys (e.g. AWS_ACCESS_KEY_ID)", () => {
  resetEnv();
  const { getRotatableKeys } = freshModule();
  assert(!getRotatableKeys().has("AWS_ACCESS_KEY_ID"), "AWS_ACCESS_KEY_ID should not be rotatable");
});

console.log("\n── rotateKey – validation ───────────────────────────────────────");

await test("throws for empty string keyName", () => {
