/**
 * key-rotation.js
 *
 * Provides a safe API key rotation mechanism for keys declared in .env.test.
 *
 * Security guarantees
 * ───────────────────
 * • Actual key *values* are never logged, stored in variables longer than
 *   necessary, or exposed in any output stream.
 * • Only the key *name* and a timestamp are written to rotation-log.json.
 * • The .env.test file is updated atomically: the new content is written to
 *   .env.test.tmp and then renamed over the original so that a crash mid-write
 *   cannot leave the file in a corrupt or partially-written state.
 * • The placeholder that replaces the old value is generated with
 *   crypto.randomBytes so it is cryptographically random and is treated as a
 *   genuine secret (never logged).
 *
 * Keys that receive rotation support
 * ───────────────────────────────────
 * Only the keys whose *names* appear in ROTATABLE_KEY_NAMES are eligible for
 * rotation.  That set is derived exclusively from .env.test at module load
 * time; no values are read or retained.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ── Keys that are in scope for rotation (requirement §1) ─────────────────────

/**
 * Parse a .env file and return only the variable *names* whose values should
 * be rotatable.  Values are intentionally discarded immediately after the
 * name is extracted.
 *
 * @param {string} filePath  Absolute path to the .env file to inspect.
 * @param {string[]} targets The specific key names to look for.
 * @returns {Set<string>}    Names that were actually found in the file.
 */
function parseRotatableKeyNames(filePath, targets) {
  const targetSet = new Set(targets);
  const found     = new Set();

  const raw = fs.readFileSync(filePath, 'utf8');

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const name = trimmed.slice(0, eqIndex).trim();

    if (targetSet.has(name)) {
      found.add(name);
      // The value (trimmed.slice(eqIndex + 1)) is intentionally never read.
    }
  }

  return found;
}

// The two key names specified in the requirements.
const ROTATABLE_KEY_NAMES = parseRotatableKeyNames(ENV_FILE, [
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
]);

// ── Placeholder generator ─────────────────────────────────────────────────────

/**
 * Generate a cryptographically random placeholder value for a given key name.
 * The value looks like a realistic secret token so it is treated with the same
 * care as a real key by any secret-scanning tooling.
 *
 * Format:  ROTATE-<KEY_NAME>-<32 random hex chars>
 *
 * The returned value is intentionally NOT logged anywhere in this module.
 *
 * @param {string} keyName
 * @returns {string}  The new placeholder value (treat as a secret).
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex'); // 32 hex chars
  return `ROTATE-${keyName}-${randomHex}`;
}

// ── Atomic .env.test writer ───────────────────────────────────────────────────

/**
 * Replace the value of `keyName` inside the .env.test file with `newValue`
 * using an atomic write-then-rename strategy.
 *
 * The function reads .env.test, substitutes exactly one `KEY=<anything>` line,
 * writes the result to .env.test.tmp with mode 0o600, then calls fs.renameSync
 * which is atomic on POSIX systems (and best-effort on Windows).
 *
 * @param {string} keyName   The variable name to update (e.g. 'ANTHROPIC_API_KEY').
 * @param {string} newValue  The replacement value.  Caller must not log this.
 * @throws {Error} If the key name is not found in .env.test.
 */
function atomicUpdateEnvFile(keyName, newValue) {
  const raw   = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = raw.split('\n');

  let replaced = false;

  const updated = lines.map((line) => {
    const trimmed = line.trim();

    // Match lines of the form KEY=<value> (with optional surrounding spaces).
    if (trimmed.startsWith('#') || !trimmed.includes('=')) return line;

    const eqIndex = trimmed.indexOf('=');
    const name    = trimmed.slice(0, eqIndex).trim();

    if (name === keyName) {
      replaced = true;
      // Preserve any indentation the original line had.
      const indent = line.match(/^(\s*)/)[1];
      return `${indent}${keyName}=${newValue}`;
    }

    return line;
  });

  if (!replaced) {
    throw new Error(
      `rotateKey: key "${keyName}" was not found in ${ENV_FILE}. ` +
      'Cannot perform rotation.'
    );
  }

  const newContent = updated.join('\n');

  // Write to the temp file with restrictive permissions (owner read/write only).
  fs.writeFileSync(TMP_FILE, newContent, { encoding: 'utf8', mode: 0o600 });

  // Atomic rename — on POSIX this is guaranteed to be atomic.
  fs.renameSync(TMP_FILE, ENV_FILE);
}

// ── Rotation log ──────────────────────────────────────────────────────────────

/**
 * Append a rotation event to rotation-log.json.
 *
 * The log record contains ONLY:
 *   • "timestamp" – ISO-8601 UTC string
 *   • "keyName"   – the name of the rotated key
 *   • "status"    – "success" | "failure"
 *   • "error"     – human-readable message (only present on failure, value-safe)
 *
 * Key *values* are never present in any log record.
 *
 * @param {object} record
 * @param {string} record.timestamp
 * @param {string} record.keyName
 * @param {'success'|'failure'} record.status
 * @param {string} [record.error]
 */
function appendRotationLog(record) {
  let log = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // If the log file is corrupt, start fresh rather than crash.
      log = [];
    }
  }

  // Final safety check: ensure no accidental value leakage in the record.
  const safeRecord = {
    timestamp: record.timestamp,
    keyName:   record.keyName,
    status:    record.status,
    ...(record.error ? { error: record.error } : {}),
  };

  log.push(safeRecord);

  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', {
    encoding: 'utf8',
    mode: 0o600,
  });
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Rotate the value of a single API key in .env.test.
 *
 * Steps:
 *  1. Validate that `keyName` is in the set of rotatable keys derived from
 *     .env.test at module load time.
 *  2. Generate a cryptographically random placeholder.
 *  3. Atomically overwrite .env.test (write tmp → rename).
 *  4. Append a log entry (name + timestamp only — never the value) to
 *     rotation-log.json.
 *
 * @param {string} keyName  The environment variable name to rotate.
 *                          Must be one of the names read from .env.test
 *                          ('ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY').
