    throw new Error(
      `rotateKey: "${keyName}" is not a rotatable key. ` +
      `Eligible keys are: ${[...ROTATABLE_KEY_NAMES].join(', ')}.`
    );
  }

  const timestamp = new Date().toISOString();

  // ── 2. Generate placeholder (never logged) ───────────────────────────────
  const newPlaceholder = generatePlaceholder(keyName);

  // ── 3. Atomic file update ────────────────────────────────────────────────
  try {
    atomicUpdateEnvFile(keyName, newPlaceholder);
  } catch (err) {
    // Log the failure (without the value) and re-throw.
    appendRotationLog({
      timestamp,
      keyName,
      status: 'failure',
      error:  err.message,
    });
    throw err;
  } finally {
    // Overwrite the local variable so the placeholder does not linger in
    // memory any longer than absolutely necessary.
    // (In V8 strings are immutable, but this signals intent clearly.)
    // newPlaceholder = undefined;  // 'const' — handled by scope exit instead.
  }

  // ── 4. Log the rotation event (name + timestamp only) ───────────────────
  appendRotationLog({ timestamp, keyName, status: 'success' });

  // Console output: key name and timestamp only — never the value.
  console.log(
    `[key-rotation] Rotated "${keyName}" at ${timestamp}. ` +
    'New value written to .env.test. See rotation-log.json for audit trail.'
  );

  // Return confirmation without the new value.
  return { keyName, timestamp };
}

/**
 * Return a *copy* of the set of key names that are eligible for rotation.
 * Useful for callers that need to enumerate supported keys without reading
 * .env.test directly.
 *
 * @returns {string[]}
 */
function rotatableKeys() {
  return [...ROTATABLE_KEY_NAMES];
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = { rotateKey, rotatableKeys };

