'use strict';

/**
 * key-rotation.js
 *
 * API-key rotation helper.
 *
 * Security contract
 * -----------------
 *  • Actual key VALUES are never logged, printed, or returned to callers.
 *  • Only key NAMES and opaque metadata (timestamps, placeholder shape) are
 *    written to rotation-log.json.
 *  • The .env.test file is updated atomically: content is written to a
 *    temporary file (.env.test.tmp) which is then renamed over the original,
 *    so a crash mid-write cannot leave a corrupt credential file.
 *  • The generated placeholder clearly marks itself as a placeholder so it
 *    is never mistaken for a real credential.
 */

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------
const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Keys we support rotating (sourced from the variable names in .env.test).
// Only the names are stored here — no values.
// ---------------------------------------------------------------------------
const ROTATABLE_KEYS = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Parse an .env file into an ordered array of line descriptors so that
 * comments, blank lines, and the original ordering are all preserved when
 * we write the file back.
 *
 * Each element is one of:
 *   { type: 'raw',   text: '<original line>' }   – comment / blank
 *   { type: 'entry', name: '<KEY>', raw: '<original line>' }
 *
 * @param {string} content  Raw file content.
 * @returns {Array<object>}
 */
function parseEnvLines(content) {
  return content.split('\n').map((line) => {
    // Match KEY=VALUE (value may be quoted or unquoted, spaces stripped)
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)/);
    if (match) {
      return { type: 'entry', name: match[1], raw: line };
    }
    return { type: 'raw', text: line };
  });
}

/**
 * Serialise a parsed line array back to file content.
 *
 * @param {Array<object>} lines
 * @returns {string}
 */
function serializeEnvLines(lines) {
  return lines.map((l) => (l.type === 'entry' ? l.raw : l.text)).join('\n');
}

/**
 * Read and parse .env.test.
 *
 * @returns {{ lines: Array<object>, names: Set<string> }}
 */
function readEnvFile() {
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Environment file not found: ${ENV_FILE}`);
  }
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines   = parseEnvLines(content);
  const names   = new Set(
    lines.filter((l) => l.type === 'entry').map((l) => l.name),
  );
  return { lines, names };
}

/**
 * Generate a new placeholder value for a given key name.
 *
 * The placeholder:
 *   • is clearly labelled PLACEHOLDER so it is never used as a real secret.
 *   • includes a short random hex token for uniqueness/auditability.
 *   • is prefixed in a way that mirrors common real-key prefixes so existing
 *     validation regex patterns do not reject it outright.
 *
 * The random bytes come from crypto.randomBytes — NOT from Math.random.
 *
 * NOTE: This function returns the placeholder string so the caller can write
 * it to the file.  It is intentionally not logged anywhere.
 *
 * @param {string} keyName
 * @returns {string}  The placeholder value (not a real secret).
 */
function generatePlaceholder(keyName) {
  const token = crypto.randomBytes(16).toString('hex'); // 32 hex chars
  // Keep a consistent prefix per key family so downstream format checks pass.
  const prefixMap = {
    ANTHROPIC_API_KEY: 'sk-ant',
    STRIPE_SECRET_KEY: 'sk_live',
  };
  const prefix = prefixMap[keyName] ?? 'key';
  return `${prefix}-PLACEHOLDER-${token}`;
}

/**
 * Append one rotation event to rotation-log.json.
 * Only the key NAME and metadata are written — never the value.
 *
 * @param {string} keyName
 * @param {string} outcome   'success' | 'failure'
 * @param {string} [reason]  Error reason, only on failure.
 */
function appendRotationLog(keyName, outcome, reason) {
  // Load existing log array (or start fresh).
  let log = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupted log — start a new one rather than crashing.
      log = [];
    }
  }

  const entry = {
    timestamp: new Date().toISOString(),
    keyName,              // variable name only, e.g. "ANTHROPIC_API_KEY"
    outcome,              // "success" or "failure"
    ...(reason !== undefined && { reason }),
  };

  // Explicitly assert that no value field has crept in.
  if ('keyValue' in entry || 'value' in entry || 'newValue' in entry) {
    throw new Error('BUG: key value must never be written to the log.');
  }

  log.push(entry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Read .env.test and return the list of variable names that have rotation
 * support (i.e. are present in the file AND are in ROTATABLE_KEYS).
 *
 * @returns {string[]}  Array of key names, e.g. ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']
 */
function getRotatableKeys() {
  const { names } = readEnvFile();
  return ROTATABLE_KEYS.filter((k) => names.has(k));
}

/**
 * Rotate a single API key by name.
 *
 * Steps
 * -----
 * 1. Validate that keyName is in ROTATABLE_KEYS and present in .env.test.
 * 2. Generate a new placeholder value (never logged).
 * 3. Write updated .env.test content to .env.test.tmp.
 * 4. Atomically rename .env.test.tmp → .env.test (fs.renameSync).
 * 5. Append a success record (key NAME + timestamp only) to rotation-log.json.
 *
 * On any error the temporary file is cleaned up and a failure record is
 * written to rotation-log.json before the error is re-thrown.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string }}
 *   Confirmation object — does NOT include the new key value.
 */
function rotateKey(keyName) {
  // ── 1. Validate ───────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    throw new TypeError('rotateKey: keyName must be a non-empty string.');
  }

  if (!ROTATABLE_KEYS.includes(keyName)) {
    const err = `rotateKey: "${keyName}" is not in the supported rotation list.`;
    appendRotationLog(keyName, 'failure', err);
    throw new Error(err);
  }

  let lines;
  let names;
  try {
    ({ lines, names } = readEnvFile());
  } catch (readErr) {
    appendRotationLog(keyName, 'failure', readErr.message);
    throw readErr;
  }

  if (!names.has(keyName)) {
    const err = `rotateKey: "${keyName}" not found in ${ENV_FILE}.`;
    appendRotationLog(keyName, 'failure', err);
    throw new Error(err);
  }

  // ── 2. Generate placeholder (kept in a local variable, never logged) ──────
  const newPlaceholder = generatePlaceholder(keyName);

  // ── 3. Build updated file content ─────────────────────────────────────────
  const updatedLines = lines.map((line) => {
    if (line.type === 'entry' && line.name === keyName) {
      // Replace the value portion only; preserve the key name exactly.
      return { type: 'entry', name: line.name, raw: `${line.name}=${newPlaceholder}` };
    }
    return line;
  });

  const newContent = serializeEnvLines(updatedLines);

  // ── 4. Atomic write via tmp → rename ──────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (writeErr) {
    // Best-effort cleanup of the temp file.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }
    appendRotationLog(keyName, 'failure', writeErr.message);
    throw writeErr;
  }

  // ── 5. Log success (name + timestamp, NO value) ───────────────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName, 'success');

  console.log(`[key-rotation] Rotated ${keyName} at ${timestamp}`);

  // Return confirmation metadata only — the new placeholder is NOT included.
  return { keyName, timestamp };
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------
module.exports = { rotateKey, getRotatableKeys };

