'use strict';
const assert = require('assert');
const fs     = require('fs');
const path   = require('path');

// ── helpers ──────────────────────────────────────────────────────────────
const ENV_FILE = path.resolve('.env.test');
const LOG_FILE = path.resolve('rotation-log.json');
const TMP_FILE = path.resolve('.env.test.tmp');

const originalEnv = fs.readFileSync(ENV_FILE, 'utf8');
function restoreEnv() { fs.writeFileSync(ENV_FILE, originalEnv, 'utf8'); }
if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);

// ── load module ──────────────────────────────────────────────────────────
const { rotateKey, getRotatableKeys } = require('./key-rotation');

// ── TEST 1: getRotatableKeys returns only the two target keys ────────────
const rotatable = getRotatableKeys();
assert.deepStrictEqual(
  rotatable.sort(),
  ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'].sort(),
  'getRotatableKeys should return exactly the two target keys'
);
console.log('PASS  getRotatableKeys =>', rotatable);

// ── TEST 2: rotateKey returns name+timestamp, no value ───────────────────
const result = rotateKey('ANTHROPIC_API_KEY');
assert.strictEqual(result.keyName, 'ANTHROPIC_API_KEY');
assert.ok(result.timestamp, 'timestamp should be present');
assert.ok(!('keyValue'  in result), 'result must NOT contain keyValue');
assert.ok(!('value'     in result), 'result must NOT contain value');
assert.ok(!('newValue'  in result), 'result must NOT contain newValue');
console.log('PASS  rotateKey returned:', result);

// ── TEST 3: .env.test.tmp does NOT exist after rotation ──────────────────
assert.ok(!fs.existsSync(TMP_FILE), '.env.test.tmp should be gone after rename');
console.log('PASS  no stale .env.test.tmp');

// ── TEST 4: .env.test was actually updated & placeholder is not a canary ─
const newEnv = fs.readFileSync(ENV_FILE, 'utf8');
const newLine = newEnv.split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
assert.ok(newLine, 'ANTHROPIC_API_KEY line must still be present');
const newVal = newLine.split('=').slice(1).join('=');
assert.ok(newVal.includes('PLACEHOLDER'), 'new value must contain PLACEHOLDER');
assert.ok(!newVal.includes('CANARY'),     'CANARY value must be gone');
console.log('PASS  .env.test updated, CANARY replaced by placeholder');

// ── TEST 5: other keys left untouched ────────────────────────────────────
const stripeLineOld = originalEnv.split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
const stripeLineNew = newEnv.split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
assert.strictEqual(stripeLineNew, stripeLineOld, 'STRIPE_SECRET_KEY must be unchanged');
console.log('PASS  STRIPE_SECRET_KEY unchanged during ANTHROPIC rotation');

// ── TEST 6: rotation-log.json contains name+outcome but NOT the value ─────
const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
assert.ok(Array.isArray(log) && log.length >= 1);
const entry = log[log.length - 1];
assert.strictEqual(entry.keyName,  'ANTHROPIC_API_KEY');
assert.strictEqual(entry.outcome,  'success');
assert.ok(entry.timestamp,         'log entry must have timestamp');
assert.ok(!('keyValue' in entry),  'log must NOT contain keyValue');
assert.ok(!('value'    in entry),  'log must NOT contain value');
assert.ok(!('newValue' in entry),  'log must NOT contain newValue');
// Make sure neither the old nor new actual value appears anywhere in the log text
const logText = fs.readFileSync(LOG_FILE, 'utf8');
assert.ok(!logText.includes('CANARY'),        'log must not contain old value');
assert.ok(!logText.includes(newVal),           'log must not contain new placeholder value');
console.log('PASS  rotation-log.json safe (name+timestamp only, no values)');

// ── TEST 7: rotate STRIPE too, verify both entries in log ────────────────
rotateKey('STRIPE_SECRET_KEY');
const log2 = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
assert.strictEqual(log2.length, 2);
assert.strictEqual(log2[1].keyName, 'STRIPE_SECRET_KEY');
assert.strictEqual(log2[1].outcome, 'success');
console.log('PASS  STRIPE_SECRET_KEY rotated, log has 2 entries');

// ── TEST 8: unsupported key name is rejected and logged as failure ────────
try {
  rotateKey('DATABASE_URL');
  assert.fail('should have thrown for unsupported key');
} catch (e) {
  assert.ok(e.message.includes('not in the supported rotation list'));
  const log3 = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  const failEntry = log3[log3.length - 1];
  assert.strictEqual(failEntry.outcome,  'failure');
  assert.strictEqual(failEntry.keyName,  'DATABASE_URL');
  console.log('PASS  unsupported key rejected, failure logged');
}

// ── TEST 9: invalid argument types throw TypeError ────────────────────────
assert.throws(() => rotateKey(''),    TypeError, 'empty string should throw');
assert.throws(() => rotateKey(null),  TypeError, 'null should throw');
assert.throws(() => rotateKey(42),    TypeError, 'number should throw');
console.log('PASS  invalid arguments throw TypeError');

// ── cleanup ──────────────────────────────────────────────────────────────
restoreEnv();
if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);
console.log('\nAll tests passed.');
