  let names;
  try {
    ({ lines, names } = readEnvFile());
  } catch (readErr) {
    appendRotationLog(keyName, 'failure', readErr.message);
    throw readErr;
  }

  if (!names.has(keyName)) {
    const err = `rotateKey: "${keyName}" not found in ${ENV_FILE}.`;
    appendRotationLog(keyName, 'failure', err);
    throw new Error(err);
  }

  // ── 2. Generate placeholder (kept in a local variable, never logged) ──────
  const newPlaceholder = generatePlaceholder(keyName);

  // ── 3. Build updated file content ─────────────────────────────────────────
  const updatedLines = lines.map((line) => {
    if (line.type === 'entry' && line.name === keyName) {
      // Replace the value portion only; preserve the key name exactly.
      return { type: 'entry', name: line.name, raw: `${line.name}=${newPlaceholder}` };
    }
    return line;
  });

  const newContent = serializeEnvLines(updatedLines);

  // ── 4. Atomic write via tmp → rename ──────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (writeErr) {
