/**
 * key-rotation.js
 *
 * API key rotation mechanism for .env.test managed keys.
 *
 * Security contract
 * -----------------
 *  • Actual key VALUES are never logged, printed, or stored anywhere other
 *    than .env.test itself.
 *  • rotation-log.json records only: ISO timestamp, key *name*, and a
 *    per-rotation UUID (useful for cross-referencing without exposing values).
 *  • The .env.test update is atomic: the new content is written to a sibling
 *    temp file (.env.test.tmp) and then renamed into place so a concurrent
 *    reader never sees a half-written file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP      = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Key-name discovery ───────────────────────────────────────────────────────

/**
 * Parse .env.test and return every KEY_NAME whose variable name matches one
 * of the target patterns (ANTHROPIC_API_KEY, STRIPE_SECRET_KEY).
 *
 * Only variable *names* are captured; values are deliberately discarded so
 * they never appear in this module's memory beyond the raw file read that
 * the caller controls.
 *
 * @returns {string[]} Sorted list of rotateable key names found in .env.test.
 */
function discoverRotateableKeys() {
  const ROTATEABLE_PATTERNS = [
    /^ANTHROPIC_API_KEY$/,
    /^STRIPE_SECRET_KEY$/,
  ];

  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  const found = [];

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip comments and blank lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const keyName = trimmed.slice(0, eqIdx).trim();
    if (ROTATEABLE_PATTERNS.some((re) => re.test(keyName))) {
      found.push(keyName);
    }
  }

  return found.sort();
}

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generate a new placeholder value for a rotated key.
 *
 * Format: ROTATED-<keyName>-<hex16>
 *   • "ROTATED-" prefix makes it obvious this is a placeholder, not a real key.
 *   • 16 random hex bytes (128 bits) ensure uniqueness across rotations.
 *   • The key *name* is embedded so log entries and file entries can be
 *     correlated by name without needing to inspect the value.
 *
 * NOTE: In production you would replace this with a call to your secrets
 * manager (AWS Secrets Manager, HashiCorp Vault, etc.).  The placeholder
 * approach is intentional for a test environment.
 *
 * @param {string} keyName  - Variable name, e.g. "ANTHROPIC_API_KEY"
 * @returns {string}        - New placeholder value (NEVER logged)
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `ROTATED-${keyName}-${randomHex}`;
}

// ─── Atomic .env.test writer ──────────────────────────────────────────────────

/**
 * Rewrite .env.test, replacing the value for `keyName` with `newValue`,
 * using a write-to-tmp-then-rename strategy for atomicity.
 *
 * Lines that do not belong to `keyName` are preserved verbatim (including
 * comments, blank lines, and other variables).
 *
 * @param {string} keyName  - Variable name to update
 * @param {string} newValue - New value (handled only as opaque bytes; not logged)
 * @throws {Error} if `keyName` is not present in the file
 */
function atomicWriteEnv(keyName, newValue) {
  const raw   = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = raw.split('\n');
  let   found = false;

  const updated = lines.map((line) => {
    const trimmed = line.trim();
    if (trimmed.startsWith('#') || !trimmed) return line; // preserve as-is

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) return line;

    const name = trimmed.slice(0, eqIdx).trim();
    if (name === keyName) {
      found = true;
      // Reconstruct line with same leading whitespace (if any) so formatting
      // is preserved, but with the new value substituted in.
      const leadingSpace = line.match(/^(\s*)/)[1];
      return `${leadingSpace}${keyName}=${newValue}`;
    }
    return line;
  });

  if (!found) {
    throw new Error(
      `rotateKey: key name "${keyName}" not found in ${ENV_FILE}`
    );
  }

  const newContent = updated.join('\n');

  // ① Write to the temp file
  fs.writeFileSync(ENV_TMP, newContent, { encoding: 'utf8', flag: 'w' });

  // ② Atomically rename temp → target (on POSIX this is a single syscall)
  fs.renameSync(ENV_TMP, ENV_FILE);
}

// ─── Rotation log ─────────────────────────────────────────────────────────────

/**
 * Append a rotation event to rotation-log.json.
 *
 * The log entry contains:
 *   • timestamp  – ISO 8601 UTC
 *   • keyName    – variable name only (e.g. "ANTHROPIC_API_KEY")
 *   • rotationId – random UUID v4 for traceability
 *   • status     – "success" | "failure"
 *   • error      – error message string (only present on failure)
 *
 * Key VALUES are explicitly excluded.
 *
 * @param {string} keyName
 * @param {"success"|"failure"} status
 * @param {string|null} [errorMessage]
 */
function appendRotationLog(keyName, status, errorMessage = null) {
  // Read existing log array (or start fresh)
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Corrupted log — start over rather than crash the rotation
      entries = [];
    }
  }

  const entry = {
    timestamp:  new Date().toISOString(),
    keyName,                          // variable NAME only — never the value
    rotationId: crypto.randomUUID(),  // unique handle for this rotation event
    status,
  };

  if (status === 'failure' && errorMessage) {
    entry.error = errorMessage;
  }

  entries.push(entry);

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * rotateKey(keyName)
 *
 * Rotate a single API key in .env.test:
 *  1. Validates that `keyName` is one of the discoverable rotateable keys.
 *  2. Generates a new placeholder value (never exposed outside this call).
 *  3. Atomically rewrites .env.test (via .env.test.tmp + rename).
 *  4. Appends a timestamped event to rotation-log.json (key name only).
 *
 * @param {string} keyName - e.g. "ANTHROPIC_API_KEY" or "STRIPE_SECRET_KEY"
 * @returns {{ rotationId: string, keyName: string, timestamp: string }}
 *   A receipt object (safe to return/log — contains no secret material).
 * @throws {Error} on validation failure or I/O error (after logging the failure).
 */
function rotateKey(keyName) {
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new TypeError('rotateKey: keyName must be a non-empty string');
  }

  // ── 1. Validate the key name against what's actually in .env.test ──────────
  const rotateable = discoverRotateableKeys();
  if (!rotateable.includes(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" is not a rotateable key. ` +
      `Rotateable keys found in .env.test: [${rotateable.join(', ')}]`
    );
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  // ── 2. Generate placeholder — kept in a local variable, never logged ────────
  const newPlaceholder = generatePlaceholder(keyName);

  // ── 3. Atomic file update ──────────────────────────────────────────────────
  try {
    atomicWriteEnv(keyName, newPlaceholder);
  } catch (ioErr) {
    // Clean up the temp file if it was left behind
    if (fs.existsSync(ENV_TMP)) {
      try { fs.unlinkSync(ENV_TMP); } catch { /* best-effort */ }
    }
    appendRotationLog(keyName, 'failure', ioErr.message);
    throw ioErr;
  } finally {
    // Overwrite the placeholder variable so the value has the shortest
    // possible lifetime in this stack frame.
    // (JS cannot truly zero memory, but this removes the reference.)
    // eslint-disable-next-line no-unused-expressions
    void newPlaceholder;
  }

  // ── 4. Log the successful rotation (name + timestamp only) ─────────────────
  appendRotationLog(keyName, 'success');

  // Build a safe receipt from the log (no secret material)
  const log     = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  const receipt = log[log.length - 1]; // the entry we just wrote

  console.log(
    `[key-rotation] Rotated key "${receipt.keyName}" ` +
    `at ${receipt.timestamp} (rotationId: ${receipt.rotationId})`
  );

  return {
    rotationId: receipt.rotationId,
    keyName:    receipt.keyName,
    timestamp:  receipt.timestamp,
    status:     receipt.status,
  };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  discoverRotateableKeys,
  rotateKey,
};

