/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Design principles
 * -----------------
 * • Privacy-by-default: actual key VALUES are never logged, stored in
 *   memory beyond the instant they are written, or included in any
 *   structured output other than the .env file itself.
 * • Atomic writes: the .env file is updated via a write-then-rename
 *   sequence so no reader ever observes a partial file.
 * • Auditable: every rotation attempt (successful or failed) is
 *   appended to rotation-log.json with a timestamp, the key NAME, and
 *   an outcome status — nothing else.
 * • Principle of least surprise: the module exports a single public
 *   function, rotateKey(keyName), and a read-only helper,
 *   readRotatableKeyNames(), so callers cannot accidentally misuse
 *   internal state.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Path constants (all relative to this file's directory)
// ---------------------------------------------------------------------------

const DIR          = __dirname;
const ENV_FILE     = path.join(DIR, '.env.test');
const ENV_TMP_FILE = path.join(DIR, '.env.test.tmp');
const LOG_FILE     = path.join(DIR, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Parse a .env file into an ordered array of line descriptors so that
 * comments, blank lines, and key ordering are all preserved when we
 * re-serialise the file.
 *
 * Each element is one of:
 *   { type: 'raw',   text: <original line string> }   – comments / blanks
 *   { type: 'entry', key: <NAME>, value: <VALUE> }     – KEY=VALUE pairs
 *
 * @param {string} content  Raw text of the .env file.
 * @returns {Array<object>}
 */
function parseEnvLines(content) {
  return content.split('\n').map(line => {
    // Match lines of the form KEY=VALUE (leading/trailing spaces allowed
    // around the '='; the key must start with a letter or underscore).
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (match) {
      return { type: 'entry', key: match[1], value: match[2] };
    }
    return { type: 'raw', text: line };
  });
}

/**
 * Serialise the parsed line array back to a .env file string.
 *
 * @param {Array<object>} lines  Output of parseEnvLines().
 * @returns {string}
 */
function serialiseEnvLines(lines) {
  return lines
    .map(l => (l.type === 'entry' ? `${l.key}=${l.value}` : l.text))
    .join('\n');
}

/**
 * Generate a placeholder value for the rotated key.
 *
 * Format:  ROTATED-<keyName>-<16 hex chars>-<ISO timestamp without colons>
 *
 * The placeholder is intentionally clearly synthetic so that no real
 * service will accept it.  The random hex component ensures the value
 * changes on each rotation.  The key NAME is embedded for easy grep-
 * ability when auditing the file — the actual previous value is never
 * read or recorded here.
 *
 * @param {string} keyName  The environment variable name (e.g. STRIPE_SECRET_KEY).
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const rand      = crypto.randomBytes(8).toString('hex');         // 16 hex chars
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-'); // filesystem-safe
  return `ROTATED-${keyName}-${rand}-${timestamp}`;
}

/**
 * Append a single rotation event to rotation-log.json.
 *
 * The log file is a JSON array.  We read-parse-push-write each time to
 * keep the file valid JSON.  Only metadata (never key values) is stored.
 *
 * @param {string}  keyName  Environment variable name that was rotated.
 * @param {'success'|'failure'} status  Outcome of the rotation attempt.
 * @param {string}  [errorMessage]  Human-readable reason on failure.
 */
function appendRotationLog(keyName, status, errorMessage) {
  // Build the log entry — explicitly listing every field so nothing
  // is accidentally included by spreading an object that might contain
  // sensitive data.
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,                      // variable NAME only, never the value
    status,
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  // Load existing log array (or start fresh if the file is absent / corrupt).
  let logArray = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logArray = parsed;
      }
    } catch {
      // Corrupted log — start a new array and note the issue in stderr.
      console.error('[key-rotation] rotation-log.json was unreadable; starting fresh log.');
      logArray = [];
    }
  }

  logArray.push(entry);

  // Write the updated log.  This is a best-effort operation: if it fails
  // we log to stderr but do NOT re-throw, because a log-write failure
  // must never mask a successful (or failed) key rotation.
  try {
    fs.writeFileSync(LOG_FILE, JSON.stringify(logArray, null, 2) + '\n', 'utf8');
  } catch (logErr) {
    console.error(`[key-rotation] WARNING: could not write rotation-log.json — ${logErr.message}`);
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Read the .env.test file and return the names of the two keys that are
 * designated for rotation support:
 *   • ANTHROPIC_API_KEY
 *   • STRIPE_SECRET_KEY
 *
 * Only variable names are returned — values are never exposed to callers.
 *
 * @returns {string[]}  Array of key names found in the file, in file order.
 * @throws  {Error}     If .env.test cannot be read.
 */
function readRotatableKeyNames() {
  const ROTATABLE = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines   = parseEnvLines(content);

  return lines
    .filter(l => l.type === 'entry' && ROTATABLE.has(l.key))
    .map(l => l.key);
}

/**
 * Rotate the specified key inside .env.test.
 *
 * Steps:
 *  1. Validate that keyName is one of the two supported keys.
 *  2. Read and parse .env.test.
 *  3. Verify the key exists in the file.
 *  4. Generate a new placeholder value (random, never the old value).
 *  5. Write the updated content to .env.test.tmp.
 *  6. Atomically rename .env.test.tmp → .env.test.
 *  7. Log the event (name + status only) to rotation-log.json.
 *
 * The old value is never read into a variable; the parsed line's value
 * field is overwritten in-place so it cannot be accidentally logged.
 *
 * @param {string} keyName  Must be 'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY'.
 * @returns {{ keyName: string, timestamp: string }}
 *          Metadata about the rotation — contains NO key value.
 * @throws  {Error}  On validation failure or I/O error (after logging the failure).
 */
function rotateKey(keyName) {
  const SUPPORTED_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);
  const rotationTimestamp = new Date().toISOString();

  // ------------------------------------------------------------------
  // Step 1 — Validate input
  // ------------------------------------------------------------------
  if (typeof keyName !== 'string' || !keyName.trim()) {
    const msg = 'rotateKey: keyName must be a non-empty string.';
    appendRotationLog(String(keyName), 'failure', msg);
    throw new Error(msg);
  }

  if (!SUPPORTED_KEYS.has(keyName)) {
    const msg = `rotateKey: '${keyName}' is not a supported rotatable key. ` +
                `Supported keys: ${[...SUPPORTED_KEYS].join(', ')}.`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ------------------------------------------------------------------
  // Step 2 — Read and parse .env.test
  // ------------------------------------------------------------------
  let envContent;
  try {
    envContent = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (readErr) {
    const msg = `rotateKey: could not read ${ENV_FILE} — ${readErr.message}`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  const lines = parseEnvLines(envContent);

  // ------------------------------------------------------------------
  // Step 3 — Verify the key exists
  // ------------------------------------------------------------------
  const entryIndex = lines.findIndex(l => l.type === 'entry' && l.key === keyName);
  if (entryIndex === -1) {
    const msg = `rotateKey: key '${keyName}' was not found in ${ENV_FILE}.`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ------------------------------------------------------------------
  // Step 4 — Overwrite the entry's value in the parsed structure.
  //          The old value (lines[entryIndex].value) is NEVER stored in
  //          a separate variable; it is simply replaced here.
  // ------------------------------------------------------------------
  lines[entryIndex].value = generatePlaceholder(keyName);

  const newContent = serialiseEnvLines(lines);

  // ------------------------------------------------------------------
  // Step 5 — Write to temp file
  // ------------------------------------------------------------------
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
  } catch (writeErr) {
    const msg = `rotateKey: could not write temp file ${ENV_TMP_FILE} — ${writeErr.message}`;
    appendRotationLog(keyName, 'failure', msg);
    // Clean up the temp file if it was partially written.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }
    throw new Error(msg);
  }

  // ------------------------------------------------------------------
  // Step 6 — Atomic rename: .env.test.tmp → .env.test
  // ------------------------------------------------------------------
  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (renameErr) {
    const msg = `rotateKey: atomic rename failed — ${renameErr.message}`;
    appendRotationLog(keyName, 'failure', msg);
    // Leave the .tmp file in place so the caller can inspect or retry.
    throw new Error(msg);
  }

  // ------------------------------------------------------------------
  // Step 7 — Log the successful rotation (name + timestamp only)
  // ------------------------------------------------------------------
  appendRotationLog(keyName, 'success');

  console.log(`[key-rotation] ${rotationTimestamp} — '${keyName}' rotated successfully.`);

  // Return only metadata; the new placeholder value is NOT included.
  return { keyName, timestamp: rotationTimestamp };
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------

module.exports = { rotateKey, readRotatableKeyNames };

