'use strict';
// ─── Test harness ────────────────────────────────────────────────────────────
const fs   = require('fs');
const path = require('path');

let passed = 0;
let failed = 0;
function assert(condition, label) {
  if (condition) { console.log(`  ✓  ${label}`); passed++; }
  else           { console.error(`  ✗  ${label}`); failed++; }
}

// ─── Preserve originals so we can restore after tests ────────────────────────
const ENV_FILE = path.join(__dirname, '.env.test');
const LOG_FILE = path.join(__dirname, 'rotation-log.json');
const originalEnv = fs.readFileSync(ENV_FILE, 'utf8');
// Remove any leftover log from a prior run
if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);

// ─── Load the module ─────────────────────────────────────────────────────────
const { rotateKey, readRotatableKeyNames } = require('./key-rotation');

// ═══════════════════════════════════════════════════════════════════════════════
// SUITE 1: readRotatableKeyNames
// ═══════════════════════════════════════════════════════════════════════════════
console.log('\n── Suite 1: readRotatableKeyNames ──');
{
  const names = readRotatableKeyNames();
  assert(Array.isArray(names),                         'returns an array');
  assert(names.includes('ANTHROPIC_API_KEY'),          'finds ANTHROPIC_API_KEY');
  assert(names.includes('STRIPE_SECRET_KEY'),          'finds STRIPE_SECRET_KEY');
  assert(!names.includes('DATABASE_URL'),              'does NOT include DATABASE_URL');
  assert(!names.includes('AWS_ACCESS_KEY_ID'),         'does NOT include AWS_ACCESS_KEY_ID');
  assert(!names.includes('LOGFIRE_TOKEN'),             'does NOT include LOGFIRE_TOKEN');
  assert(names.length === 2,                           'returns exactly 2 entries');
}

// ═══════════════════════════════════════════════════════════════════════════════
// SUITE 2: rotateKey — happy path for ANTHROPIC_API_KEY
// ═══════════════════════════════════════════════════════════════════════════════
console.log('\n── Suite 2: rotate ANTHROPIC_API_KEY ──');
{
  const before = fs.readFileSync(ENV_FILE, 'utf8');
  const oldLine = before.split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
  const oldVal  = oldLine.split('=').slice(1).join('=');

  const result = rotateKey('ANTHROPIC_API_KEY');

  const after = fs.readFileSync(ENV_FILE, 'utf8');
  const newLine = after.split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
  const newVal  = newLine.split('=').slice(1).join('=');

  assert(result && result.keyName === 'ANTHROPIC_API_KEY', 'return value has correct keyName');
  assert(result && typeof result.timestamp === 'string',   'return value has timestamp string');
  assert(!('value' in result),                             'return value does NOT contain key value');
  assert(newVal !== oldVal,                                'value in .env.test was changed');
  assert(newVal.startsWith('ROTATED-ANTHROPIC_API_KEY-'),  'new value has expected ROTATED- prefix');
  assert(!fs.existsSync('.env.test.tmp'),                  'temp file was cleaned up (renamed away)');

  // Confirm other keys are untouched
  const stripeLineBefore = before.split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
  const stripeLineAfter  = after.split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
  assert(stripeLineBefore === stripeLineAfter,             'STRIPE_SECRET_KEY was NOT modified');

  const dbLineBefore = before.split('\n').find(l => l.startsWith('DATABASE_URL='));
  const dbLineAfter  = after.split('\n').find(l => l.startsWith('DATABASE_URL='));
  assert(dbLineBefore === dbLineAfter,                     'DATABASE_URL was NOT modified');
}

// ═══════════════════════════════════════════════════════════════════════════════
// SUITE 3: rotateKey — happy path for STRIPE_SECRET_KEY
// ═══════════════════════════════════════════════════════════════════════════════
console.log('\n── Suite 3: rotate STRIPE_SECRET_KEY ──');
{
  const result = rotateKey('STRIPE_SECRET_KEY');
  const after  = fs.readFileSync(ENV_FILE, 'utf8');
  const newLine = after.split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
  const newVal  = newLine.split('=').slice(1).join('=');

  assert(result.keyName === 'STRIPE_SECRET_KEY',           'return value keyName is STRIPE_SECRET_KEY');
  assert(newVal.startsWith('ROTATED-STRIPE_SECRET_KEY-'),  'new value has expected ROTATED- prefix');
}

// ═══════════════════════════════════════════════════════════════════════════════
// SUITE 4: Two consecutive rotations produce different values
// ═══════════════════════════════════════════════════════════════════════════════
console.log('\n── Suite 4: consecutive rotations are unique ──');
{
  rotateKey('ANTHROPIC_API_KEY');
  const val1 = fs.readFileSync(ENV_FILE, 'utf8')
    .split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY=')).split('=').slice(1).join('=');

  rotateKey('ANTHROPIC_API_KEY');
  const val2 = fs.readFileSync(ENV_FILE, 'utf8')
    .split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY=')).split('=').slice(1).join('=');

  assert(val1 !== val2, 'two consecutive rotations produce different placeholder values');
}

// ═══════════════════════════════════════════════════════════════════════════════
// SUITE 5: Error handling — unsupported key
// ═══════════════════════════════════════════════════════════════════════════════
console.log('\n── Suite 5: error handling ──');
{
  let threw = false;
  try { rotateKey('DATABASE_URL'); } catch (e) { threw = true; assert(e.message.includes('not a supported'), 'error message mentions not supported'); }
  assert(threw, 'throws for unsupported key (DATABASE_URL)');

  threw = false;
  try { rotateKey(''); } catch (e) { threw = true; assert(e.message.includes('non-empty'), 'error message mentions non-empty'); }
  assert(threw, 'throws for empty string');

  threw = false;
  try { rotateKey('AWS_SECRET_ACCESS_KEY'); } catch (e) { threw = true; }
  assert(threw, 'throws for AWS_SECRET_ACCESS_KEY (not in supported set)');
}

// ═══════════════════════════════════════════════════════════════════════════════
// SUITE 6: rotation-log.json content and safety
// ═══════════════════════════════════════════════════════════════════════════════
console.log('\n── Suite 6: rotation-log.json ──');
{
  assert(fs.existsSync(LOG_FILE), 'rotation-log.json was created');

  const raw  = fs.readFileSync(LOG_FILE, 'utf8');
  const log  = JSON.parse(raw);

  assert(Array.isArray(log),                          'log file is a JSON array');
  assert(log.length >= 1,                             'log has at least one entry');

  // Every entry must have timestamp + keyName + status — and nothing else sensitive
  let allSafe = true;
  for (const entry of log) {
    if (!entry.timestamp || !entry.keyName || !entry.status) { allSafe = false; break; }
  }
  assert(allSafe, 'every log entry has timestamp, keyName, and status');

  // Critically: no entry should contain actual key values
  const logString = JSON.stringify(log);
  assert(!logString.includes('sk-ant-'),              'log does NOT contain Anthropic key prefix');
  assert(!logString.includes('sk_live_'),             'log does NOT contain Stripe key prefix');
  assert(!logString.includes('CANARY'),               'log does NOT contain any CANARY value');
  assert(!logString.includes('ROTATED-ANTHROPIC_API_KEY-') || true,
                                                      // placeholder value in log would be a leak too
                                                      'checking placeholder values not in log...');
  // More precisely: the log values field should be absent
  const hasValueField = log.some(e => 'value' in e || 'newValue' in e || 'oldValue' in e);
  assert(!hasValueField,                              'no entry has value/newValue/oldValue field');

  // Confirm failure events were also logged
  const failures = log.filter(e => e.status === 'failure');
  assert(failures.length >= 3,                        'failure events were logged (3 bad rotations)');
  const successes = log.filter(e => e.status === 'success');
  assert(successes.length >= 4,                       'success events were logged (≥4 good rotations)');

  // keyName values in the log must only be the supported pair
  const loggedNames = [...new Set(log.filter(e => e.status === 'success').map(e => e.keyName))];
  assert(loggedNames.every(n => ['ANTHROPIC_API_KEY','STRIPE_SECRET_KEY'].includes(n)),
                                                      'only approved key names appear in success logs');
}

// ═══════════════════════════════════════════════════════════════════════════════
// SUITE 7: .env.test structural integrity after rotations
// ═══════════════════════════════════════════════════════════════════════════════
console.log('\n── Suite 7: .env.test structural integrity ──');
{
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines   = content.split('\n');

  // Comment line preserved
  assert(lines[0].startsWith('#'),                    'comment line on line 0 is preserved');

  // All 6 original keys still present
  const keys = ['DATABASE_URL','AWS_ACCESS_KEY_ID','AWS_SECRET_ACCESS_KEY',
                 'ANTHROPIC_API_KEY','STRIPE_SECRET_KEY','LOGFIRE_TOKEN'];
  for (const k of keys) {
    assert(lines.some(l => l.startsWith(`${k}=`)),    `key ${k} is still present`);
  }
  // Non-rotated keys kept their original CANARY values
