/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security contract:
 *   - Actual key VALUES are never read into memory beyond what is strictly
 *     required to parse the .env.test line structure.
 *   - Key values are NEVER stored in variables with meaningful names, logged,
 *     returned to callers, or written anywhere except back into .env.test.
 *   - Only the key NAME (the left-hand side of the assignment) is recorded in
 *     the audit log.
 *   - The atomic write (tmp → rename) ensures .env.test is never left in a
 *     partially-written state.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── File paths ────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ── Keys that this module is allowed to rotate ────────────────────────────────
// Derived exclusively from the variable NAMES present in .env.test.
// Values are intentionally discarded during parsing.

/**
 * Parse .env.test and return only the set of variable names whose values
 * should be rotation-eligible.
 *
 * Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are considered rotation
 * targets (as required).  Other keys in the file are left untouched.
 *
 * @returns {Set<string>} Set of rotateable key names found in .env.test.
 */
function readRotateableKeyNames() {
  const ROTATION_TARGETS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  const found = new Set();

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const name = trimmed.slice(0, eqIdx).trim();
    if (ROTATION_TARGETS.has(name)) {
      found.add(name);
    }
    // The value (trimmed.slice(eqIdx + 1)) is intentionally never stored.
  }

  return found;
}

// ── Placeholder generator ─────────────────────────────────────────────────────

/**
 * Generate a new opaque key placeholder string.
 *
 * Format: ROTATED-<keyName>-<16 random hex bytes>
 *
 * In a real system this step would call the upstream provider's key-issuance
 * API and return the newly issued key.  Here we produce a clearly-labelled
 * placeholder so no real credential is ever fabricated or assumed.
 *
 * @param {string} keyName - The variable name being rotated (for prefix only).
 * @returns {string} New placeholder value (not a real credential).
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `ROTATED-${keyName}-${randomHex}`;
}

// ── Atomic .env.test update ───────────────────────────────────────────────────

/**
 * Atomically replace the value of `keyName` in .env.test.
 *
 * Steps:
 *   1. Read the current file.
 *   2. Replace the matching line in-memory (old value is never stored).
 *   3. Write the result to .env.test.tmp.
 *   4. Rename .env.test.tmp → .env.test  (atomic on POSIX systems).
 *
 * @param {string} keyName        - Variable name to update.
 * @param {string} newPlaceholder - Replacement value.
 * @throws {Error} If keyName is not found in .env.test.
 */
function atomicUpdateEnvFile(keyName, newPlaceholder) {
  const raw   = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = raw.split('\n');
  let   found = false;

  const updated = lines.map((line) => {
    const trimmed = line.trim();
    if (trimmed.startsWith('#') || !trimmed.includes('=')) return line;

    const eqIdx = trimmed.indexOf('=');
    const name  = trimmed.slice(0, eqIdx).trim();

    if (name === keyName) {
      found = true;
      // Preserve leading whitespace (if any) from the original line.
      const leading = line.slice(0, line.indexOf(trimmed[0]));
      return `${leading}${keyName}=${newPlaceholder}`;
    }
    return line;
  });

  if (!found) {
    throw new Error(
      `rotateKey: key name "${keyName}" was not found in ${ENV_FILE}`
    );
  }

  // Write to tmp, then rename — never touches ENV_FILE directly until the
  // rename, so the file is never in a partial state.
  fs.writeFileSync(ENV_TMP_FILE, updated.join('\n'), { encoding: 'utf8', mode: 0o600 });
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ── Audit log ─────────────────────────────────────────────────────────────────

/**
 * Append one rotation event to rotation-log.json.
 *
 * Only the key NAME and a UTC timestamp are recorded — never the value.
 *
 * @param {string} keyName - The variable name that was rotated.
 * @param {'success'|'failure'} status - Outcome of the rotation attempt.
 * @param {string} [errorMessage] - Human-readable error detail (failure only).
 */
function appendRotationLog(keyName, status, errorMessage) {
  // Load existing log array, or start fresh.
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Corrupted log: start a new array rather than crashing.
      entries = [];
    }
  }

  /** @type {Object} */
  const entry = {
    timestamp: new Date().toISOString(), // UTC, ISO-8601
    keyName,                             // variable NAME only — no value
    status,
  };

  if (status === 'failure' && errorMessage) {
    entry.errorMessage = errorMessage;
  }

  entries.push(entry);

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', {
    encoding: 'utf8',
    mode: 0o600,
  });
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Rotate the placeholder value for `keyName` in .env.test.
 *
 * Workflow:
 *   1. Verify that `keyName` is one of the rotation-eligible names found in
 *      .env.test (ANTHROPIC_API_KEY or STRIPE_SECRET_KEY).
 *   2. Generate a new opaque placeholder.
 *   3. Atomically update .env.test (write tmp, rename).
 *   4. Append a success entry to rotation-log.json with timestamp + key name.
 *
 * On any error the failure is logged (key name + error message only) and the
 * error is re-thrown so the caller can react.
 *
 * @param {string} keyName - The variable name to rotate (e.g. 'ANTHROPIC_API_KEY').
 * @returns {{ keyName: string, timestamp: string }} Rotation receipt (no value).
 * @throws {TypeError}  If keyName is not a non-empty string.
 * @throws {RangeError} If keyName is not in the rotation-eligible set.
 * @throws {Error}      On I/O failures.
 */
function rotateKey(keyName) {
  // ── Input validation ──────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    const msg = 'rotateKey: keyName must be a non-empty string.';
    appendRotationLog(String(keyName), 'failure', msg);
    throw new TypeError(msg);
  }

  // ── Eligibility check ─────────────────────────────────────────────────────
  const eligible = readRotateableKeyNames();

  if (!eligible.has(keyName)) {
    const msg =
      `rotateKey: "${keyName}" is not a rotation-eligible key. ` +
      `Eligible keys found in .env.test: [${[...eligible].join(', ')}].`;
    appendRotationLog(keyName, 'failure', msg);
    throw new RangeError(msg);
  }

  // ── Generate placeholder & update file ───────────────────────────────────
  try {
    const newPlaceholder = generatePlaceholder(keyName);
    atomicUpdateEnvFile(keyName, newPlaceholder);
    // newPlaceholder goes out of scope here; it is never returned or logged.
  } catch (err) {
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  // ── Audit log ─────────────────────────────────────────────────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName, 'success');

  console.log(
    `[key-rotation] ${timestamp} | ROTATED | key: ${keyName} | status: success`
  );

  // Return only metadata — never the new placeholder value.
  return { keyName, timestamp };
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  readRotateableKeyNames, // exported for introspection / testing
};

