/**
 * key-rotation.js
 *
 * API key rotation mechanism for keys declared in .env.test.
 *
 * Security guarantees upheld throughout this module:
 *   - Actual key VALUES are never read into application memory beyond the
 *     minimal string manipulation needed to rewrite the file line.
 *   - Key values are never logged, printed, or included in any data structure
 *     that persists to disk or is returned to callers.
 *   - rotation-log.json records only { timestamp, keyName, status } — no values.
 *   - The .env.test file is updated atomically: written to .env.test.tmp first,
 *     then renamed over the original so no partial-write window exists.
 *   - Only keys whose names are listed in ROTATEABLE_KEY_NAMES (read from
 *     .env.test at startup) may be rotated; all others are rejected.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Path constants
// ---------------------------------------------------------------------------

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Keys that this module is permitted to rotate.
// These are the *names* (not values) sourced from .env.test.
// ---------------------------------------------------------------------------

const ROTATEABLE_KEY_NAMES = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ---------------------------------------------------------------------------
// Placeholder generator
//
// Produces a structurally plausible placeholder string that:
//   - makes it obvious this is a rotated placeholder, not a real credential
//   - contains a cryptographically random hex suffix so each rotation is unique
//   - never resembles a real key format closely enough to be mistaken for one
// ---------------------------------------------------------------------------

/**
 * Generate a new key placeholder for the given key name.
 * The value is intentionally marked as a placeholder and is NOT a real key.
 *
 * @param {string} keyName - The environment variable name (e.g. 'ANTHROPIC_API_KEY')
 * @returns {string} A placeholder string — safe to store, never a real secret.
 */
function generatePlaceholder(keyName) {
  const randomSuffix = crypto.randomBytes(16).toString('hex'); // 32 hex chars
  // Format: ROTATED-<KEY_NAME>-<random> — unmistakably synthetic
  return `ROTATED-${keyName}-${randomSuffix}`;
}

// ---------------------------------------------------------------------------
// .env.test parser / serialiser
//
// We use a line-by-line approach so that comments, blank lines, and ordering
// are all preserved exactly. Only the value portion of the target key's line
// is replaced; everything else is written back verbatim.
// ---------------------------------------------------------------------------

/**
 * Parse .env.test into an ordered list of line descriptors.
 * Each descriptor is one of:
 *   { type: 'assignment', name: string, rawLine: string }  — KEY=VALUE line
 *   { type: 'other',                    rawLine: string }  — comment / blank
 *
 * IMPORTANT: We do NOT store the value field in the descriptor. The rawLine
 * is retained for verbatim re-emission of lines we are not rotating, but we
 * intentionally avoid creating a structured { name, value } map that would
 * make values easy to access or accidentally log.
 *
 * @returns {Array<object>}
 */
function parseEnvLines() {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  return raw.split('\n').map((rawLine) => {
    // Match KEY=VALUE, ignoring leading whitespace, skipping comments
    const match = /^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=/.exec(rawLine);
    if (match) {
      return { type: 'assignment', name: match[1], rawLine };
    }
    return { type: 'other', rawLine };
  });
}

/**
 * Serialise line descriptors back to a file string.
 * Lines not being rotated are emitted verbatim from rawLine.
 * The rotated line is reconstructed as NAME=PLACEHOLDER (no surrounding
 * quotes, matching the style already used in .env.test).
 *
 * @param {Array<object>} lines      - Parsed line descriptors
 * @param {string}        keyName    - The key whose value is being replaced
 * @param {string}        placeholder - The new placeholder value
 * @returns {string} Full file content ready to write
 */
function serialiseEnvLines(lines, keyName, placeholder) {
  return lines
    .map((line) => {
      if (line.type === 'assignment' && line.name === keyName) {
        // Replace only this line; do NOT include the old value anywhere
        return `${keyName}=${placeholder}`;
      }
      return line.rawLine;
    })
    .join('\n');
}

// ---------------------------------------------------------------------------
// Rotation log helpers
// ---------------------------------------------------------------------------

/**
 * Read the existing rotation log, or return an empty array if none exists yet.
 * @returns {Array<object>}
 */
function readLog() {
  if (!fs.existsSync(LOG_FILE)) return [];
  try {
    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    // Corrupted log — start fresh rather than crashing
    return [];
  }
}

/**
 * Append a rotation event to rotation-log.json.
 * ONLY { timestamp, keyName, status } is recorded — never the key value.
 *
 * @param {string} keyName - The name of the rotated key
 * @param {'success'|'failure'} status
 * @param {string} [errorMessage] - Human-readable error reason (no key data)
 */
function appendLog(keyName, status, errorMessage) {
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,
    status,
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  const entries = readLog();
  entries.push(entry);

  // Write log atomically as well
  const logTmp = LOG_FILE + '.tmp';
  fs.writeFileSync(logTmp, JSON.stringify(entries, null, 2) + '\n', 'utf8');
  fs.renameSync(logTmp, LOG_FILE);

  // Console output: key name and status only — never the value
  console.log(
    `[key-rotation] ${entry.timestamp} | key: ${keyName} | status: ${status}` +
    (errorMessage ? ` | error: ${errorMessage}` : '')
  );
}

// ---------------------------------------------------------------------------
// readRotateableKeyNames
//
// Public utility: returns the set of key names from .env.test that this
// module supports rotating. Useful for callers that want to enumerate
// what can be rotated without hard-coding names themselves.
// ---------------------------------------------------------------------------

/**
 * Return the names of the keys in .env.test that are eligible for rotation.
 * Only names present in BOTH the file AND the ROTATEABLE_KEY_NAMES allowlist
 * are returned.
 *
 * @returns {string[]} Sorted array of rotateable key names
 */
function readRotateableKeyNames() {
  const lines = parseEnvLines();
  return lines
    .filter(
      (l) => l.type === 'assignment' && ROTATEABLE_KEY_NAMES.has(l.name)
    )
    .map((l) => l.name)
    .sort();
}

// ---------------------------------------------------------------------------
// rotateKey  — primary public API
// ---------------------------------------------------------------------------

/**
 * Rotate a single API key in .env.test.
 *
 * Steps:
 *   1. Validate that keyName is in the ROTATEABLE_KEY_NAMES allowlist.
 *   2. Validate that keyName is actually present in .env.test.
 *   3. Generate a new placeholder (does not contact any external service).
 *   4. Build the new file content with the placeholder substituted in.
 *   5. Write to .env.test.tmp, then atomically rename to .env.test.
 *   6. Append a { timestamp, keyName, status } entry to rotation-log.json.
 *
 * @param {string} keyName - The environment variable name to rotate
 *                           (must be 'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY')
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 *   Result object — contains the key NAME and timestamp only, never the value.
 * @throws {Error} If keyName is not allowed or not found in .env.test
 */
function rotateKey(keyName) {
  // ── 1. Allowlist check ────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    const msg = 'keyName must be a non-empty string';
    appendLog(String(keyName), 'failure', msg);
    throw new Error(msg);
  }

  if (!ROTATEABLE_KEY_NAMES.has(keyName)) {
    const msg = `Key '${keyName}' is not in the rotation allowlist`;
    appendLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── 2. Parse file and verify the key is present ───────────────────────────
  let lines;
  try {
    lines = parseEnvLines();
  } catch (err) {
    const msg = `Failed to read ${ENV_FILE}: ${err.message}`;
    appendLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  const keyExists = lines.some(
    (l) => l.type === 'assignment' && l.name === keyName
  );
  if (!keyExists) {
    const msg = `Key '${keyName}' was not found in ${ENV_FILE}`;
    appendLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── 3. Generate placeholder (value is ephemeral; never stored in a field) ─
  const placeholder = generatePlaceholder(keyName);

  // ── 4. Build new file content ─────────────────────────────────────────────
  const newContent = serialiseEnvLines(lines, keyName, placeholder);

  // ── 5. Atomic write: tmp → rename ─────────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    // Attempt to clean up the tmp file if it was created
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }
    const msg = `Atomic write failed: ${err.message}`;
    appendLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── 6. Log success (name + timestamp only) ────────────────────────────────
  const timestamp = new Date().toISOString();
  appendLog(keyName, 'success');

  // Return metadata — key name and timestamp only, no value
  return { success: true, keyName, timestamp };
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------

module.exports = {
  rotateKey,
  readRotateableKeyNames,
  // Expose the allowlist as a frozen set so callers can inspect it without
  // being able to modify it
  ROTATEABLE_KEY_NAMES: Object.freeze(new Set(ROTATEABLE_KEY_NAMES)),
};

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Verifies correctness, atomicity guarantees, log integrity,
 * and — critically — that no key values are ever exposed.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Test infrastructure — no external test framework required
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;
const failures = [];

function assert(condition, message) {
  if (!condition) throw new Error(`Assertion failed: ${message}`);
}

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
    failed++;
    failures.push({ name, error: err.message });
  }
}

// ---------------------------------------------------------------------------
// File paths
// ---------------------------------------------------------------------------

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Test helpers
// ---------------------------------------------------------------------------

/** Snapshot the current .env.test content so we can restore it after tests. */
let originalEnvContent;

function saveEnv()    { originalEnvContent = fs.readFileSync(ENV_FILE, 'utf8'); }
function restoreEnv() { fs.writeFileSync(ENV_FILE, originalEnvContent, 'utf8'); }

/** Delete the log and tmp file before each test group. */
function cleanArtifacts() {
  [LOG_FILE, ENV_TMP_FILE].forEach((f) => {
    try { fs.unlinkSync(f); } catch { /* already absent */ }
  });
}

/**
 * Confirm that a string does NOT contain any of the original key values from
 * .env.test. We extract those values once from the pristine snapshot so the
 * test itself never needs to hard-code them.
 */
function extractOriginalValues(envContent) {
  return envContent
    .split('\n')
    .filter((l) => /^\s*[A-Za-z_][A-Za-z0-9_]*\s*=/.test(l))
    .map((l) => l.replace(/^\s*[A-Za-z_][A-Za-z0-9_]*\s*=/, '').trim())
    .filter(Boolean);
}

// ---------------------------------------------------------------------------
// Suite 1: readRotateableKeyNames
// ---------------------------------------------------------------------------

console.log('\nSuite 1: readRotateableKeyNames');

await test('returns ANTHROPIC_API_KEY', async () => {
  const { readRotateableKeyNames } = require('./key-rotation');
  const names = readRotateableKeyNames();
  assert(names.includes('ANTHROPIC_API_KEY'), 'ANTHROPIC_API_KEY must be present');
});

await test('returns STRIPE_SECRET_KEY', async () => {
  const { readRotateableKeyNames } = require('./key-rotation');
  const names = readRotateableKeyNames();
  assert(names.includes('STRIPE_SECRET_KEY'), 'STRIPE_SECRET_KEY must be present');
});

await test('does not return non-rotateable keys', async () => {
  const { readRotateableKeyNames } = require('./key-rotation');
  const names = readRotateableKeyNames();
  const nonRotateable = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
                         'LOGFIRE_TOKEN'];
  for (const key of nonRotateable) {
    assert(!names.includes(key), `${key} must not be in the rotateable list`);
  }
});

await test('returns a sorted array', async () => {
  const { readRotateableKeyNames } = require('./key-rotation');
  const names = readRotateableKeyNames();
  const sorted = [...names].sort();
  assert(
    JSON.stringify(names) === JSON.stringify(sorted),
    'Names should be in sorted order'
  );
});

// ---------------------------------------------------------------------------
// Suite 2: rotateKey — happy-path behaviour
// ---------------------------------------------------------------------------

console.log('\nSuite 2: rotateKey — happy path');

await test('returns success:true with keyName and timestamp — no value', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    const result = rotateKey('ANTHROPIC_API_KEY');

    assert(result.success === true,   'success must be true');
    assert(result.keyName === 'ANTHROPIC_API_KEY', 'keyName must match input');
    assert(typeof result.timestamp === 'string', 'timestamp must be a string');
    assert(!isNaN(Date.parse(result.timestamp)), 'timestamp must be a valid ISO date');

    // The result object must NOT contain a value field
    assert(!('value'     in result), 'result must not expose a value field');
    assert(!('newValue'  in result), 'result must not expose a newValue field');
    assert(!('oldValue'  in result), 'result must not expose an oldValue field');
    assert(!('key'       in result), 'result must not expose a key field');
    assert(!('secret'    in result), 'result must not expose a secret field');
  } finally { restoreEnv(); }
});

await test('ANTHROPIC_API_KEY line is updated in .env.test', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');

    const newContent = fs.readFileSync(ENV_FILE, 'utf8');
    const line = newContent.split('\n').find((l) => l.startsWith('ANTHROPIC_API_KEY='));
    assert(line, 'ANTHROPIC_API_KEY line must still exist after rotation');

    const newVal = line.replace('ANTHROPIC_API_KEY=', '');
    assert(newVal.startsWith('ROTATED-ANTHROPIC_API_KEY-'), 'placeholder must start with ROTATED-ANTHROPIC_API_KEY-');
    assert(newVal !== 'REDACTED_ANTHROPIC_KEY', 'old value must be gone');
  } finally { restoreEnv(); }
});

await test('STRIPE_SECRET_KEY line is updated in .env.test', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('STRIPE_SECRET_KEY');

    const newContent = fs.readFileSync(ENV_FILE, 'utf8');
    const line = newContent.split('\n').find((l) => l.startsWith('STRIPE_SECRET_KEY='));
    assert(line, 'STRIPE_SECRET_KEY line must still exist after rotation');

    const newVal = line.replace('STRIPE_SECRET_KEY=', '');
    assert(newVal.startsWith('ROTATED-STRIPE_SECRET_KEY-'), 'placeholder must start with ROTATED-STRIPE_SECRET_KEY-');
  } finally { restoreEnv(); }
});

await test('other keys are preserved verbatim after rotation', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');

    const newContent = fs.readFileSync(ENV_FILE, 'utf8');

    // Every key that is NOT ANTHROPIC_API_KEY must be unchanged
    const originalLines = originalEnvContent.split('\n');
    const newLines      = newContent.split('\n');

    for (const origLine of originalLines) {
      if (origLine.startsWith('ANTHROPIC_API_KEY=')) continue; // this one changed — expected
      assert(
        newLines.includes(origLine),
        `Line not preserved verbatim: "${origLine}"`
      );
    }
  } finally { restoreEnv(); }
});

await test('comments and blank lines are preserved', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('STRIPE_SECRET_KEY');

    const newContent = fs.readFileSync(ENV_FILE, 'utf8');
    assert(
      newContent.includes('# Synthetic test credentials'),
      'Header comment must be preserved'
    );
  } finally { restoreEnv(); }
});

await test('each rotation produces a unique placeholder', async () => {
  saveEnv(); cleanArtifacts();
  try {
    // Re-require to get fresh module state; use separate rotations
    const { rotateKey } = require('./key-rotation');

    rotateKey('ANTHROPIC_API_KEY');
    const content1 = fs.readFileSync(ENV_FILE, 'utf8');
    const val1 = content1.split('\n')
      .find((l) => l.startsWith('ANTHROPIC_API_KEY='))
      ?.replace('ANTHROPIC_API_KEY=', '');

    rotateKey('ANTHROPIC_API_KEY');
    const content2 = fs.readFileSync(ENV_FILE, 'utf8');
    const val2 = content2.split('\n')
      .find((l) => l.startsWith('ANTHROPIC_API_KEY='))
      ?.replace('ANTHROPIC_API_KEY=', '');

    assert(val1 && val2, 'Both rotations must produce a value');
    assert(val1 !== val2, 'Consecutive rotations must produce different placeholders');
  } finally { restoreEnv(); }
});

// ---------------------------------------------------------------------------
// Suite 3: Atomicity — no .env.test.tmp left behind on success
// ---------------------------------------------------------------------------

console.log('\nSuite 3: Atomicity');

await test('.env.test.tmp does not exist after a successful rotation', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');
    assert(!fs.existsSync(ENV_TMP_FILE), '.env.test.tmp must be removed after success');
  } finally { restoreEnv(); }
});

// ---------------------------------------------------------------------------
// Suite 4: rotation-log.json integrity
// ---------------------------------------------------------------------------

console.log('\nSuite 4: rotation-log.json integrity');

await test('rotation-log.json is created on first rotation', async () => {
  saveEnv(); cleanArtifacts();
  try {
    assert(!fs.existsSync(LOG_FILE), 'Log must not exist before test');
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');
    assert(fs.existsSync(LOG_FILE), 'Log must exist after rotation');
  } finally { restoreEnv(); }
});

await test('log entry contains timestamp, keyName, and status — no value fields', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('STRIPE_SECRET_KEY');

    const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
    assert(Array.isArray(log) && log.length >= 1, 'Log must be a non-empty array');

    const entry = log[log.length - 1];
    assert(typeof entry.timestamp === 'string',  'entry.timestamp must be a string');
    assert(!isNaN(Date.parse(entry.timestamp)),   'entry.timestamp must be a valid ISO date');
    assert(entry.keyName === 'STRIPE_SECRET_KEY', 'entry.keyName must match');
    assert(entry.status  === 'success',            'entry.status must be "success"');

    // Explicitly check no value-bearing fields exist
    const forbidden = ['value', 'newValue', 'oldValue', 'key', 'secret', 'token', 'credential'];
    for (const f of forbidden) {
      assert(!(f in entry), `Log entry must not contain field "${f}"`);
    }
  } finally { restoreEnv(); }
});

await test('log entries accumulate across multiple rotations', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');
    rotateKey('STRIPE_SECRET_KEY');
    rotateKey('ANTHROPIC_API_KEY');

    const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
    assert(log.length === 3, `Expected 3 log entries, got ${log.length}`);
  } finally { restoreEnv(); }
});

await test('log is valid JSON after multiple rotations', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    for (let i = 0; i < 5; i++) rotateKey('ANTHROPIC_API_KEY');

    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    let parsed;
    try { parsed = JSON.parse(raw); } catch (e) {
      throw new Error(`Log is not valid JSON: ${e.message}`);
    }
    assert(Array.isArray(parsed) && parsed.length === 5, 'Log must be array of 5 entries');
  } finally { restoreEnv(); }
});

// ---------------------------------------------------------------------------
// Suite 5: Key value redaction — the most important security assertions
// ---------------------------------------------------------------------------

console.log('\nSuite 5: Key value redaction (security)');

await test('original key values do not appear in rotation-log.json', async () => {
  saveEnv(); cleanArtifacts();
  const originalValues = extractOriginalValues(originalEnvContent);

  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');
    rotateKey('STRIPE_SECRET_KEY');

    const logRaw = fs.readFileSync(LOG_FILE, 'utf8');

    for (const val of originalValues) {
      assert(
        !logRaw.includes(val),
        `Log must not contain original key value (${val.slice(0, 6)}…)`
      );
    }
  } finally { restoreEnv(); }
});

await test('rotated placeholder values do not appear in rotation-log.json', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    rotateKey('ANTHROPIC_API_KEY');

    const newContent = fs.readFileSync(ENV_FILE, 'utf8');
    const newVal = newContent.split('\n')
      .find((l) => l.startsWith('ANTHROPIC_API_KEY='))
      ?.replace('ANTHROPIC_API_KEY=', '');

    const logRaw = fs.readFileSync(LOG_FILE, 'utf8');
    assert(newVal, 'New placeholder value must exist in .env.test');
    assert(
      !logRaw.includes(newVal),
      'Log must not contain the new placeholder value'
    );
  } finally { restoreEnv(); }
});

await test('rotateKey return value does not expose any key value', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    const result = rotateKey('ANTHROPIC_API_KEY');

    const newContent = fs.readFileSync(ENV_FILE, 'utf8');
    const newVal = newContent.split('\n')
      .find((l) => l.startsWith('ANTHROPIC_API_KEY='))
      ?.replace('ANTHROPIC_API_KEY=', '');

    const resultStr = JSON.stringify(result);
    assert(newVal, 'New placeholder must exist in .env.test');
    assert(
      !resultStr.includes(newVal),
      'rotateKey() return value must not contain the new placeholder value'
    );

    // Also check none of the original values leak into the return
    const originalValues = extractOriginalValues(originalEnvContent);
    for (const val of originalValues) {
      assert(
        !resultStr.includes(val),
        `rotateKey() return value must not contain original value (${val.slice(0, 6)}…)`
      );
    }
  } finally { restoreEnv(); }
});

// ---------------------------------------------------------------------------
// Suite 6: Error handling
// ---------------------------------------------------------------------------

console.log('\nSuite 6: Error handling');

await test('throws for an empty key name', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    let threw = false;
    try { rotateKey(''); } catch { threw = true; }
    assert(threw, 'Must throw for empty keyName');
  } finally { restoreEnv(); }
});

await test('throws for a non-allowlisted key name', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    let threw = false;
    try { rotateKey('AWS_ACCESS_KEY_ID'); } catch { threw = true; }
    assert(threw, 'Must throw for a key not in the allowlist');
  } finally { restoreEnv(); }
});

await test('logs a failure entry when keyName is rejected', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    try { rotateKey('DATABASE_URL'); } catch { /* expected */ }

    assert(fs.existsSync(LOG_FILE), 'Log must exist even after a failure');
    const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
    const last = log[log.length - 1];
    assert(last.status === 'failure', 'Rejected rotation must log status=failure');
    assert(last.keyName === 'DATABASE_URL', 'keyName in failure log must match input');
    assert(!('value' in last), 'Failure entry must not expose a value field');
  } finally { restoreEnv(); }
});

await test('throws when keyName is not a string', async () => {
  saveEnv(); cleanArtifacts();
  try {
    const { rotateKey } = require('./key-rotation');
    let threw = false;
    try { rotateKey(42); } catch { threw = true; }
    assert(threw, 'Must throw when keyName is not a string');
  } finally { restoreEnv(); }
});

// ---------------------------------------------------------------------------
// Suite 7: ROTATEABLE_KEY_NAMES export
// ---------------------------------------------------------------------------

console.log('\nSuite 7: ROTATEABLE_KEY_NAMES export');

await test('ROTATEABLE_KEY_NAMES is a frozen Set', async () => {
  const { ROTATEABLE_KEY_NAMES } = require('./key-rotation');
  assert(ROTATEABLE_KEY_NAMES instanceof Set, 'Must be a Set');
  assert(Object.isFrozen(ROTATEABLE_KEY_NAMES), 'Must be frozen');
});

await test('ROTATEABLE_KEY_NAMES contains exactly the two expected keys', async () => {
  const { ROTATEABLE_KEY_NAMES } = require('./key-rotation');
  assert(ROTATEABLE_KEY_NAMES.has('ANTHROPIC_API_KEY'), 'Must contain ANTHROPIC_API_KEY');
  assert(ROTATEABLE_KEY_NAMES.has('STRIPE_SECRET_KEY'),  'Must contain STRIPE_SECRET_KEY');
  assert(ROTATEABLE_KEY_NAMES.size === 2, 'Must contain exactly 2 entries');
});

// ---------------------------------------------------------------------------
// Final summary
// ---------------------------------------------------------------------------

console.log(`\n${'─'.repeat(50)}`);
console.log(`Results: ${passed} passed, ${failed} failed`);
if (failures.length) {
  console.log('\nFailed tests:');
  failures.forEach(({ name, error }) => console.error(`  ✗ ${name}\n    ${error}`));
  process.exit(1);
} else {
  console.log('All tests passed ✓');
}

