/**
 * key-rotation.js
 *
 * API key rotation mechanism for keys declared in .env.test.
 *
 * Security guarantees upheld throughout this module:
 *   - Actual key VALUES are never read into application memory beyond the
 *     minimal string manipulation needed to rewrite the file line.
 *   - Key values are never logged, printed, or included in any data structure
 *     that persists to disk or is returned to callers.
 *   - rotation-log.json records only { timestamp, keyName, status } — no values.
 *   - The .env.test file is updated atomically: written to .env.test.tmp first,
 *     then renamed over the original so no partial-write window exists.
 *   - Only keys whose names are listed in ROTATEABLE_KEY_NAMES (read from
 *     .env.test at startup) may be rotated; all others are rejected.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Path constants
// ---------------------------------------------------------------------------

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Keys that this module is permitted to rotate.
// These are the *names* (not values) sourced from .env.test.
// ---------------------------------------------------------------------------

const ROTATEABLE_KEY_NAMES = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ---------------------------------------------------------------------------
// Placeholder generator
//
// Produces a structurally plausible placeholder string that:
//   - makes it obvious this is a rotated placeholder, not a real credential
//   - contains a cryptographically random hex suffix so each rotation is unique
//   - never resembles a real key format closely enough to be mistaken for one
// ---------------------------------------------------------------------------

/**
 * Generate a new key placeholder for the given key name.
 * The value is intentionally marked as a placeholder and is NOT a real key.
 *
 * @param {string} keyName - The environment variable name (e.g. 'ANTHROPIC_API_KEY')
 * @returns {string} A placeholder string — safe to store, never a real secret.
 */
function generatePlaceholder(keyName) {
  const randomSuffix = crypto.randomBytes(16).toString('hex'); // 32 hex chars
  // Format: ROTATED-<KEY_NAME>-<random> — unmistakably synthetic
  return `ROTATED-${keyName}-${randomSuffix}`;
}

// ---------------------------------------------------------------------------
// .env.test parser / serialiser
//
// We use a line-by-line approach so that comments, blank lines, and ordering
// are all preserved exactly. Only the value portion of the target key's line
// is replaced; everything else is written back verbatim.
// ---------------------------------------------------------------------------

/**
 * Parse .env.test into an ordered list of line descriptors.
 * Each descriptor is one of:
 *   { type: 'assignment', name: string, rawLine: string }  — KEY=VALUE line
 *   { type: 'other',                    rawLine: string }  — comment / blank
 *
 * IMPORTANT: We do NOT store the value field in the descriptor. The rawLine
 * is retained for verbatim re-emission of lines we are not rotating, but we
 * intentionally avoid creating a structured { name, value } map that would
 * make values easy to access or accidentally log.
 *
 * @returns {Array<object>}
 */
function parseEnvLines() {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  return raw.split('\n').map((rawLine) => {
    // Match KEY=VALUE, ignoring leading whitespace, skipping comments
    const match = /^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=/.exec(rawLine);
    if (match) {
      return { type: 'assignment', name: match[1], rawLine };
    }
    return { type: 'other', rawLine };
  });
}

/**
 * Serialise line descriptors back to a file string.
 * Lines not being rotated are emitted verbatim from rawLine.
 * The rotated line is reconstructed as NAME=PLACEHOLDER (no surrounding
 * quotes, matching the style already used in .env.test).
 *
 * @param {Array<object>} lines      - Parsed line descriptors
 * @param {string}        keyName    - The key whose value is being replaced
 * @param {string}        placeholder - The new placeholder value
 * @returns {string} Full file content ready to write
 */
function serialiseEnvLines(lines, keyName, placeholder) {
  return lines
    .map((line) => {
      if (line.type === 'assignment' && line.name === keyName) {
        // Replace only this line; do NOT include the old value anywhere
        return `${keyName}=${placeholder}`;
      }
      return line.rawLine;
    })
    .join('\n');
