 * ONLY { timestamp, keyName, status } is recorded — never the key value.
 *
 * @param {string} keyName - The name of the rotated key
 * @param {'success'|'failure'} status
 * @param {string} [errorMessage] - Human-readable error reason (no key data)
 */
function appendLog(keyName, status, errorMessage) {
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,
    status,
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  const entries = readLog();
  entries.push(entry);

  // Write log atomically as well
  const logTmp = LOG_FILE + '.tmp';
  fs.writeFileSync(logTmp, JSON.stringify(entries, null, 2) + '\n', 'utf8');
  fs.renameSync(logTmp, LOG_FILE);

  // Console output: key name and status only — never the value
  console.log(
    `[key-rotation] ${entry.timestamp} | key: ${keyName} | status: ${status}` +
