/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security guarantees:
 *  - Actual key *values* are NEVER logged, stored in the rotation log, or
 *    written to any variable that outlives the atomic file-update operation.
 *  - Only key *names* (e.g. "ANTHROPIC_API_KEY") appear in log entries.
 *  - The new placeholder value is written directly into the temp file buffer
 *    and the buffer is discarded immediately after the rename; it is never
 *    assigned to a module-level variable.
 *  - The atomic write pattern (write → fsync → rename) prevents a partial
 *    write from corrupting .env.test if the process is interrupted mid-flight.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys eligible for rotation (read once at module load) ───────────────────

/**
 * Parses .env.test and returns the Set of variable *names* whose values look
 * like API keys.  The two names the spec requires are ANTHROPIC_API_KEY and
 * STRIPE_SECRET_KEY; this function discovers them dynamically so the module
 * stays correct if the file gains or loses entries.
 *
 * Only the variable names are kept in memory — the values are discarded
 * immediately after the line is parsed.
 */
function readRotatableKeyNames() {
  const raw  = fs.readFileSync(ENV_FILE, 'utf8');
  const names = new Set();

  for (const line of raw.split('\n')) {
