    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const name = trimmed.slice(0, eqIdx).trim();

    // Keep only the two key names the spec asks us to support.
    if (name === 'ANTHROPIC_API_KEY' || name === 'STRIPE_SECRET_KEY') {
      names.add(name);
      // Value (trimmed.slice(eqIdx + 1)) is intentionally never stored.
    }
  }

  return names;
