// Eagerly validate that the expected keys exist in .env.test so callers get a
// clear error at require-time rather than a silent no-op later.
const ROTATABLE_KEYS = readRotatableKeyNames();

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Builds a new key placeholder.
 *
 * Format examples:
 *   ANTHROPIC_API_KEY  →  REDACTED_ANTHROPIC_KEY<16 hex bytes>
 *   STRIPE_SECRET_KEY  →  REDACTED_STRIPE_LIVE<16 hex bytes>
 *
 * Using crypto.randomBytes ensures the token is unpredictable even if the
 * system clock is skewed or reused across VMs.
 *
 * NOTE: This is a *placeholder* value for local / test environments.
 * Real production rotation must call the upstream provider's API.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex'); // 32 char hex string
