 * Returns the Set of key names that this module will accept for rotation.
 * Useful for callers that want to enumerate supported keys without guessing.
 *
 * @returns {Set<string>}
 */
function getRotatableKeyNames() {
  return new Set(ROTATABLE_KEYS); // defensive copy
}

module.exports = { rotateKey, getRotatableKeyNames };

