/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security invariants enforced throughout this module:
 *   - Actual key values are NEVER read into variables beyond what is strictly
 *     needed to rewrite the .env.test file line-by-line.
 *   - Actual key values are NEVER logged, returned, or written anywhere except
 *     back into .env.test itself.
 *   - rotation-log.json records only the timestamp, key name, and a status
 *     string — never a key value.
 *   - The .env.test file is updated atomically: content is written to
 *     .env.test.tmp first, then fs.renameSync() replaces the original so that
 *     no reader ever sees a partially-written file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Key names that this module is allowed to rotate ─────────────────────────
// Derived by reading only the left-hand side of each assignment in .env.test.

/**
 * Parses .env.test and returns the Set of key *names* (left-hand side of '=')
 * that are present in the file.  Values are intentionally discarded.
 *
 * @returns {Set<string>}
 */
function readKeyNames() {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  const names = new Set();

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const keyName = trimmed.slice(0, eqIndex).trim();
    if (keyName) names.add(keyName);
  }

  return names;
}

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generates a cryptographically random placeholder value for a rotated key.
 * The placeholder is a hex string prefixed with "ROTATED-" so it is clearly
 * identifiable as a non-production placeholder.
 *
 * No real secret is ever generated here; this is purely a stand-in value that
 * a real rotation workflow would replace with an actual credential fetched from
 * the upstream provider.
 *
 * @returns {string}  e.g. "ROTATED-a3f1c9e2b04d7f58…"
 */
function generatePlaceholder() {
  return 'ROTATED-' + crypto.randomBytes(24).toString('hex');
}

// ─── Atomic .env.test rewriter ────────────────────────────────────────────────

/**
 * Rewrites .env.test atomically, replacing the value for `keyName` with
 * `newPlaceholder`.  All other lines (including other keys and comments) are
 * preserved exactly as-is.
 *
 * Write order:
 *   1. Write complete new content to .env.test.tmp
 *   2. fs.renameSync(.env.test.tmp  →  .env.test)   ← atomic on POSIX
 *
 * @param {string} keyName        The variable name whose value will be replaced.
 * @param {string} newPlaceholder The replacement value (a placeholder string).
 */
function atomicUpdateEnvFile(keyName, newPlaceholder) {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');

  let keyFound = false;
  const updatedLines = raw.split('\n').map((line) => {
    const trimmed = line.trim();

    // Preserve blank lines and comments verbatim
    if (!trimmed || trimmed.startsWith('#')) return line;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) return line;

    const currentKeyName = trimmed.slice(0, eqIndex).trim();
    if (currentKeyName !== keyName) return line;

    // Replace only the value portion — key name and '=' are kept intact.
    keyFound = true;
    return `${keyName}=${newPlaceholder}`;
  });

  if (!keyFound) {
    throw new Error(`Key "${keyName}" not found in ${ENV_FILE}`);
  }

  const newContent = updatedLines.join('\n');

  // Step 1 — write to temp file
  fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });

  // Step 2 — atomic rename (POSIX guarantee: readers see old or new, never partial)
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── Rotation logger ──────────────────────────────────────────────────────────

/**
 * Appends a rotation event to rotation-log.json.
 *
 * The log entry contains ONLY:
 *   - timestamp  (ISO-8601 string)
 *   - keyName    (the variable name, e.g. "ANTHROPIC_API_KEY")
 *   - status     ("rotated")
 *
 * Key values are NEVER written to the log.
 *
 * @param {string} keyName
 */
function appendRotationLog(keyName) {
  // Read existing log array, or start fresh
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Corrupted log — start a clean log rather than crashing
      entries = [];
    }
  }

  // Build a log entry that is safe to persist: timestamp + name + status only
  const entry = {
    timestamp : new Date().toISOString(),
    keyName   : keyName,       // variable name only — never the value
    status    : 'rotated',
  };

  entries.push(entry);

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2), {
    encoding : 'utf8',
    flag     : 'w',
  });
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotates the key identified by `keyName` inside .env.test.
 *
 * Steps:
 *   1. Read the set of rotateable key names from .env.test (values ignored).
 *   2. Validate that `keyName` is present in the file.
 *   3. Generate a random placeholder that will stand in for the new value.
 *   4. Atomically rewrite .env.test with the placeholder in place of the old value.
 *   5. Append a rotation event (timestamp + keyName + status) to rotation-log.json.
 *
