    throw new TypeError('rotateKey: keyName must be a non-empty string');
  }

  // Step 1 — discover which keys exist (names only; values are not retained)
  const knownKeys = readKeyNames();

  // Step 2 — validate
  if (!knownKeys.has(keyName)) {
    throw new Error(
