const before = fs.readFileSync('.env.test', 'utf8');
console.log('\n=== .env.test BEFORE rotation ===');
console.log(before);

// ── 4. Rotate ANTHROPIC_API_KEY ──────────────────────────────────────────────
console.log('=== Rotating ANTHROPIC_API_KEY ===');
const r1 = rotateKey('ANTHROPIC_API_KEY');
console.log('Result:', r1);

