/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Design constraints (enforced throughout):
 *  - Only the KEY NAMES defined in .env.test under the ROTATABLE_KEY_NAMES
 *    allowlist are eligible for rotation.
 *  - Generated placeholder values are opaque tokens; no real secrets are
 *    read, stored, or logged anywhere in this module.
 *  - Actual key values are never passed to any logging path.
 *  - The .env.test file is updated atomically: write to .env.test.tmp, then
 *    fs.renameSync to the real path so no partial writes are observable.
 *  - rotation-log.json records only: timestamp, keyName, and a truncated
 *    prefix of the *placeholder* (never a real credential).
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------
const ENV_PATH     = path.resolve(__dirname, '.env.test');
const ENV_TMP_PATH = path.resolve(__dirname, '.env.test.tmp');
const LOG_PATH     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// The exact variable names this module is permitted to rotate.
// Derived directly from the keys present in .env.test that match the
// ANTHROPIC_API_KEY / STRIPE_SECRET_KEY requirement in the task spec.
// ---------------------------------------------------------------------------
const ROTATABLE_KEY_NAMES = Object.freeze(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parse an .env file into an ordered array of line descriptors so we can
 * round-trip the file without disturbing comments or unrelated entries.
 *
 * Each element is one of:
 *   { kind: 'pair',  raw: string, key: string }   – a KEY=VALUE line
 *   { kind: 'other', raw: string }                 – comment / blank / etc.
 *
 * IMPORTANT: values are intentionally NOT stored in the parsed structure
 * so they can never leak into memory longer than necessary.
 */
function parseEnvLines(fileContent) {
  return fileContent.split('\n').map(line => {
    // Match lines of the form: IDENTIFIER=<anything>
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (match) {
      return { kind: 'pair', raw: line, key: match[1] };
      // match[2] (the value) is deliberately discarded here.
    }
    return { kind: 'other', raw: line };
  });
}

/**
 * Serialise the line descriptors back to a file string, replacing the value
 * for `targetKey` with `newPlaceholder`.  All other lines are reproduced
 * verbatim from their original `raw` strings.
 */
function serializeEnvLines(lines, targetKey, newPlaceholder) {
  return lines.map(entry => {
    if (entry.kind === 'pair' && entry.key === targetKey) {
      return `${targetKey}=${newPlaceholder}`;
    }
    return entry.raw;
  }).join('\n');
}

/**
 * Read and parse .env.test, returning only the set of key names present.
 * Values are never surfaced.
 */
function readRotatableKeyNames() {
  if (!fs.existsSync(ENV_PATH)) {
    throw new Error(`Environment file not found: ${ENV_PATH}`);
  }
  const content = fs.readFileSync(ENV_PATH, 'utf8');
  const lines   = parseEnvLines(content);
  const found   = lines
    .filter(e => e.kind === 'pair' && ROTATABLE_KEY_NAMES.includes(e.key))
    .map(e => e.key);
  return found; // e.g. ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']
}

/**
 * Generate a synthetic placeholder token that:
 *  - is clearly marked as a placeholder (never mistaken for a real secret),
 *  - contains a cryptographically random hex segment for uniqueness,
 *  - embeds the key name so log entries are self-describing without values.
 *
 * Format:  ROTATED-<KEY_NAME>-<16 random hex bytes>
 * Example: ROTATED-ANTHROPIC_API_KEY-a3f9c1e2b4d67890abcdef1234567890
 *
 * The value is intentionally NOT a real API key and cannot be used to
 * authenticate against any service.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `ROTATED-${keyName}-${randomHex}`;
}

/**
 * Append one rotation event to rotation-log.json.
 *
 * Logged fields:
 *   timestamp  – ISO-8601 UTC string
 *   keyName    – the variable name (e.g. "ANTHROPIC_API_KEY")
 *   status     – "success" | "failure"
 *   reason     – human-readable note (only present on failure)
 *   placeholderPrefix – first 16 chars of the NEW placeholder so log entries
 *                       are traceable without storing the full token.
 *                       (Never derived from an actual key value.)
 *
 * The actual key value is NEVER written here.
 */
function appendRotationLog(entry) {
  let log = [];
  if (fs.existsSync(LOG_PATH)) {
    try {
      const raw = fs.readFileSync(LOG_PATH, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupted log — start fresh rather than crashing.
      log = [];
    }
  }
  log.push(entry);
  fs.writeFileSync(LOG_PATH, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * rotateKey(keyName)
 *
 * Rotates the placeholder value for `keyName` in .env.test.
 *
 * Steps:
 *  1. Validate that keyName is in the ROTATABLE_KEY_NAMES allowlist.
 *  2. Validate that keyName is actually present in the current .env.test.
 *  3. Generate a new opaque placeholder (no real secret involved).
 *  4. Write the updated file content to .env.test.tmp.
 *  5. Atomically rename .env.test.tmp → .env.test.
 *  6. Log the event (timestamp + keyName only) to rotation-log.json.
 *
 * @param {string} keyName – must be one of ROTATABLE_KEY_NAMES
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 * @throws {Error} on invalid keyName or file I/O failure
 */
function rotateKey(keyName) {
  const timestamp = new Date().toISOString();

  // ── 1. Allowlist check ──────────────────────────────────────────────────
  if (!ROTATABLE_KEY_NAMES.includes(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" is not in the rotation allowlist. ` +
      `Allowed keys: ${ROTATABLE_KEY_NAMES.join(', ')}`
    );
    appendRotationLog({
      timestamp,
      keyName,
      status: 'failure',
      reason: 'Key name not in rotation allowlist.',
    });
    throw err;
  }

  // ── 2. Read current file; confirm key exists ────────────────────────────
  if (!fs.existsSync(ENV_PATH)) {
    const err = new Error(`rotateKey: env file not found at ${ENV_PATH}`);
    appendRotationLog({
      timestamp,
      keyName,
      status: 'failure',
      reason: 'Env file not found.',
    });
    throw err;
  }

  const originalContent = fs.readFileSync(ENV_PATH, 'utf8');
  const lines           = parseEnvLines(originalContent);
  const keyEntry        = lines.find(e => e.kind === 'pair' && e.key === keyName);

  if (!keyEntry) {
    const err = new Error(
      `rotateKey: key "${keyName}" was not found in ${ENV_PATH}`
    );
    appendRotationLog({
      timestamp,
      keyName,
      status: 'failure',
      reason: 'Key name not found in env file.',
    });
    throw err;
  }

  // ── 3. Generate placeholder (no real secret involved) ───────────────────
  const newPlaceholder = generatePlaceholder(keyName);

  // ── 4. Write to temp file ───────────────────────────────────────────────
  const updatedContent = serializeEnvLines(lines, keyName, newPlaceholder);
  fs.writeFileSync(ENV_TMP_PATH, updatedContent, { encoding: 'utf8', flag: 'w' });

  // ── 5. Atomic rename ────────────────────────────────────────────────────
  fs.renameSync(ENV_TMP_PATH, ENV_PATH);

  // ── 6. Log the event — key name and timestamp ONLY ──────────────────────
  //      placeholderPrefix is the first 16 chars of our own generated token;
  //      it is never derived from an actual credential.
  const logEntry = {
    timestamp,
    keyName,
    status: 'success',
    placeholderPrefix: newPlaceholder.slice(0, 16), // e.g. "ROTATED-ANTHROPI"
  };
  appendRotationLog(logEntry);

  console.log(
    `[key-rotation] ${timestamp} | rotated "${keyName}" successfully. ` +
    `(Value not logged.)`
  );

  return { success: true, keyName, timestamp };
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------
module.exports = {
  rotateKey,
  readRotatableKeyNames, // expose for callers that want to list eligible keys
  ROTATABLE_KEY_NAMES,   // expose the frozen allowlist for inspection/testing
};

