/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security invariants enforced throughout this module:
 *  - Actual key VALUES are never read into any variable used outside
 *    the narrow file-rewrite path.
 *  - Nothing derived from a key value is ever logged, returned, or
 *    passed to any external system.
 *  - The log records only: ISO timestamp, key NAME, and outcome.
 *  - The atomic write (tmp → rename) ensures no partial file state.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys eligible for rotation (read from .env.test at module load) ──────────

/**
 * Parse an .env file and return only the variable NAMES whose values look like
 * API/secret keys.  We identify "rotateable" keys by checking whether the
 * variable name contains one of the conventional key-name segments.
 *
 * Supported target keys (from the spec): ANTHROPIC_API_KEY, STRIPE_SECRET_KEY.
 * The parser is intentionally generic so additional keys can be added by simply
 * updating the .env.test file — no code changes required.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {string[]}       Array of variable names present in the file.
 */
function parseEnvKeyNames(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const names = [];

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const varName = trimmed.slice(0, eqIdx).trim();
    if (varName) {
      names.push(varName);
    }
  }

  return names;
}

/** All variable names present in .env.test (loaded once at startup). */
const ENV_KEY_NAMES = parseEnvKeyNames(ENV_FILE);

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generate a cryptographically random placeholder string that is safe to write
 * into the .env file as a new "rotated" key placeholder.
 *
 * Format:  ROTATED-<keyName>-<timestamp>-<16 random hex bytes>
 *
 * The placeholder is clearly marked as synthetic so it cannot be mistaken for
 * a real credential.  It is NOT derived from the old key value.
 *
 * @param {string} keyName  The variable name being rotated (e.g. "STRIPE_SECRET_KEY").
 * @returns {string}        A fresh placeholder value — never a real secret.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  const ts        = Date.now();
  return `ROTATED-${keyName}-${ts}-${randomHex}`;
}

// ─── Atomic file rewrite ──────────────────────────────────────────────────────

/**
 * Rewrite .env.test so that the line for `keyName` uses `newPlaceholder` as its
 * value.  The write is atomic:
 *   1. Build the new file content in memory.
 *   2. Write it to .env.test.tmp.
 *   3. fsync the tmp file to flush OS buffers.
 *   4. Rename .env.test.tmp → .env.test  (atomic on POSIX).
 *
 * SECURITY: `newPlaceholder` is a synthetic value generated by this module —
 * it is not a real secret.  The OLD value on the matching line is overwritten
 * and is never captured in any variable.
 *
 * @param {string} keyName         Variable name to update.
 * @param {string} newPlaceholder  The replacement value (synthetic, not real).
 * @throws {Error} If keyName is not found in the file.
 */
function atomicRewriteEnv(keyName, newPlaceholder) {
  const raw   = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = raw.split('\n');
  let   found = false;

  const newLines = lines.map((line) => {
    const trimmed = line.trim();
    if (trimmed.startsWith('#') || !trimmed.includes('=')) return line;

    const eqIdx  = trimmed.indexOf('=');
    const varName = trimmed.slice(0, eqIdx).trim();

    if (varName === keyName) {
      found = true;
      // Reconstruct the line with the new placeholder.
      // We intentionally do NOT read or store the old value.
      return `${keyName}=${newPlaceholder}`;
    }
    return line;
  });

  if (!found) {
    throw new Error(
      `rotateKey: key name "${keyName}" not found in ${ENV_FILE}`
    );
  }

  const newContent = newLines.join('\n');

  // Step 1 – write to the tmp file
  fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });

  // Step 2 – fsync: flush data to disk before the rename
  const fd = fs.openSync(ENV_TMP_FILE, 'r+');
  try {
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }

  // Step 3 – atomic rename (POSIX rename(2) is atomic)
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── Audit log ────────────────────────────────────────────────────────────────

/**
 * Append a rotation event to rotation-log.json.
 *
 * Each record contains:
 *   - timestamp  ISO-8601 wall-clock time of the rotation event.
 *   - keyName    The variable NAME that was rotated.
 *   - status     "success" or "failure".
 *   - error      (failure only) The error message — never contains key values.
 *
 * The log file is a JSON array.  If it does not exist it is created.
 *
 * SECURITY: Only the key NAME is recorded.  The new or old placeholder/value
 * is never included.
 *
 * @param {string}      keyName   Variable name that was (or failed to be) rotated.
 * @param {"success"|"failure"} status  Outcome of the rotation attempt.
 * @param {string|null} [errorMessage]  Error message on failure (must not contain key data).
 */
function appendRotationLog(keyName, status, errorMessage = null) {
  let entries = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Corrupted log — start fresh rather than crashing
      entries = [];
    }
  }

  /** @type {Object} */
  const record = {
    timestamp: new Date().toISOString(),
    keyName,          // variable name ONLY — never the value
    status,
  };

  if (status === 'failure' && errorMessage != null) {
    // Sanitise the error message as a defence-in-depth measure:
    // strip anything that looks like it might be a key value
    // (long alphanumeric strings not already in the key name).
    record.error = sanitiseErrorMessage(errorMessage, keyName);
  }

  entries.push(record);

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

/**
 * Remove substrings from an error message that look like they could be secret
 * values (long token-like strings not equal to the key name itself).
 *
 * This is a defence-in-depth measure — the primary guarantee is that we never
 * read the key value into an error object in the first place.
 *
 * @param {string} message  Raw error message.
 * @param {string} keyName  The variable name (safe to keep).
 * @returns {string}        Sanitised message.
 */
function sanitiseErrorMessage(message, keyName) {
  // Redact any token-like run of 12+ non-whitespace characters that is not the
  // key name itself and looks like a credential (contains digits + letters).
  return message.replace(/[A-Za-z0-9_\-]{12,}/g, (match) => {
    if (match === keyName) return match;
    // Allow plain English words / known safe fragments
    if (/^[a-z]+$/i.test(match)) return match;          // pure alpha = probably a word
    if (match === 'rotateKey')   return match;
    // Anything else that could be a token — redact it
    if (/[0-9]/.test(match) && /[A-Za-z]/.test(match)) return '[REDACTED]';
    return match;
  });
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotate a single API key by:
 *   1. Validating that `keyName` is present in .env.test.
 *   2. Generating a fresh random placeholder (NOT derived from the old value).
 *   3. Atomically rewriting .env.test with the new placeholder.
 *   4. Logging the event (name + outcome only) to rotation-log.json.
 *
 * @param {string} keyName
 *   The exact environment variable name to rotate, e.g. "ANTHROPIC_API_KEY".
 *   Must exist as a key in .env.test.
 *
 * @returns {{ keyName: string, rotatedAt: string }}
 *   A result object containing the key NAME and the ISO rotation timestamp.
 *   The new placeholder value is intentionally NOT returned.
 *
 * @throws {Error}
 *   If `keyName` is not among the tracked keys, or if the file rewrite fails.
 *   The error is logged before being re-thrown.
 */
function rotateKey(keyName) {
  // ── 1. Validate ──────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    const msg = 'rotateKey: keyName must be a non-empty string';
    appendRotationLog(String(keyName), 'failure', msg);
    throw new Error(msg);
  }

  if (!ENV_KEY_NAMES.includes(keyName)) {
    const msg =
      `rotateKey: "${keyName}" is not tracked in ${ENV_FILE}. ` +
      `Known keys: ${ENV_KEY_NAMES.join(', ')}`;
    appendRotationLog(keyName, 'failure', msg);
    throw new Error(msg);
  }

  // ── 2. Generate placeholder ───────────────────────────────────────────────
  const newPlaceholder = generatePlaceholder(keyName);
  // newPlaceholder is a synthetic token — not a real secret.
  // It is used only to update the file and is never logged or returned.

  // ── 3. Atomic file rewrite ────────────────────────────────────────────────
  try {
    atomicRewriteEnv(keyName, newPlaceholder);
  } catch (err) {
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  // ── 4. Audit log (name + timestamp only) ─────────────────────────────────
  const rotatedAt = new Date().toISOString();
  appendRotationLog(keyName, 'success');

  // Return metadata only — the caller does not receive the new placeholder.
  return { keyName, rotatedAt };
}

/**
 * Return a read-only copy of the key names that are tracked for rotation.
 * Useful for callers that want to enumerate rotateable keys without touching
 * the file system.
 *
 * @returns {string[]}
 */
function getTrackedKeyNames() {
  return [...ENV_KEY_NAMES];
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, getTrackedKeyNames };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Uses Node's built-in assert module — no test-framework dependency needed.
 *
 * Run:  node key-rotation.test.js
 */

'use strict';

const fs     = require('fs');
const path   = require('path');
const assert = require('assert');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** Save the current state of a file so we can restore it after each test. */
function snapshot(filePath) {
  return fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : null;
}

/** Restore a file to a previously-snapshotted state (or delete if it didn't exist). */
function restore(filePath, saved) {
  if (saved === null) {
    if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  } else {
    fs.writeFileSync(filePath, saved, 'utf8');
  }
}

/** Read the current .env.test and return a Map<name, value>. */
function readEnv() {
  const map = new Map();
  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  for (const line of raw.split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const eq = t.indexOf('=');
    if (eq === -1) continue;
    map.set(t.slice(0, eq).trim(), t.slice(eq + 1));
  }
  return map;
}

/** Read the rotation log as an array (or [] if missing/empty). */
function readLog() {
  if (!fs.existsSync(LOG_FILE)) return [];
  try {
    return JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  } catch {
    return [];
  }
}

// ─── Test runner ─────────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

async function test(name, fn) {
  // Snapshot state before each test
  const savedEnv = snapshot(ENV_FILE);
  const savedLog = snapshot(LOG_FILE);
  const savedTmp = snapshot(ENV_TMP_FILE);

  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`     ${err.message}`);
    failed++;
  } finally {
    // Always restore state so tests are isolated
    restore(ENV_FILE,     savedEnv);
    restore(LOG_FILE,     savedLog);
    restore(ENV_TMP_FILE, savedTmp);
    // Re-require the module fresh so ENV_KEY_NAMES reflects the restored file.
    // (Node caches require(); delete the cache entry to force a reload.)
    delete require.cache[require.resolve('./key-rotation')];
  }
}

// ─── Tests ───────────────────────────────────────────────────────────────────

console.log('\nkey-rotation tests\n');

// ── 1. getTrackedKeyNames returns the two target keys ────────────────────────
await test('getTrackedKeyNames includes ANTHROPIC_API_KEY and STRIPE_SECRET_KEY', () => {
  const { getTrackedKeyNames } = require('./key-rotation');
  const names = getTrackedKeyNames();
  assert.ok(Array.isArray(names), 'should return an array');
  assert.ok(names.includes('ANTHROPIC_API_KEY'), 'must include ANTHROPIC_API_KEY');
  assert.ok(names.includes('STRIPE_SECRET_KEY'),  'must include STRIPE_SECRET_KEY');
});

// ── 2. getTrackedKeyNames includes ALL var names from the file ───────────────
await test('getTrackedKeyNames returns every variable name in .env.test', () => {
  const { getTrackedKeyNames } = require('./key-rotation');
  const names = getTrackedKeyNames();
  // The test file also has DATABASE_URL, AWS_ACCESS_KEY_ID, etc.
  assert.ok(names.includes('DATABASE_URL'),          'DATABASE_URL should be tracked');
  assert.ok(names.includes('AWS_ACCESS_KEY_ID'),     'AWS_ACCESS_KEY_ID should be tracked');
  assert.ok(names.includes('AWS_SECRET_ACCESS_KEY'), 'AWS_SECRET_ACCESS_KEY should be tracked');
});

// ── 3. getTrackedKeyNames returns a copy, not a live reference ───────────────
await test('getTrackedKeyNames returns an independent copy of the array', () => {
  const { getTrackedKeyNames } = require('./key-rotation');
  const a = getTrackedKeyNames();
  const b = getTrackedKeyNames();
  a.push('INJECTED');
  assert.ok(!b.includes('INJECTED'), 'mutations must not affect subsequent calls');
});

// ── 4. rotateKey returns keyName and rotatedAt (not the value) ───────────────
await test('rotateKey returns { keyName, rotatedAt } with no value field', () => {
  const { rotateKey } = require('./key-rotation');
  const result = rotateKey('ANTHROPIC_API_KEY');

  assert.strictEqual(result.keyName, 'ANTHROPIC_API_KEY');
  assert.ok(typeof result.rotatedAt === 'string', 'rotatedAt should be a string');
  assert.ok(!isNaN(Date.parse(result.rotatedAt)),  'rotatedAt should be a valid ISO date');

  // The result must NOT expose the new placeholder value
  assert.ok(!('value'       in result), 'result must not have a "value" field');
  assert.ok(!('placeholder' in result), 'result must not have a "placeholder" field');
  assert.ok(!('newKey'      in result), 'result must not have a "newKey" field');
  assert.ok(!('secret'      in result), 'result must not have a "secret" field');
});

// ── 5. rotateKey updates .env.test for ANTHROPIC_API_KEY ─────────────────────
await test('rotateKey replaces the value line for ANTHROPIC_API_KEY in .env.test', () => {
  const { rotateKey } = require('./key-rotation');
  const before = readEnv().get('ANTHROPIC_API_KEY');
  rotateKey('ANTHROPIC_API_KEY');
  const after  = readEnv().get('ANTHROPIC_API_KEY');

  assert.ok(after !== before,       'value should have changed');
  assert.ok(after !== undefined,    'key must still be present');
  assert.ok(after.length > 0,       'new value must not be empty');
  // The placeholder is clearly synthetic — starts with "ROTATED-"
  assert.ok(after.startsWith('ROTATED-ANTHROPIC_API_KEY-'), 'placeholder must be namespaced');
});

// ── 6. rotateKey updates .env.test for STRIPE_SECRET_KEY ────────────────────
await test('rotateKey replaces the value line for STRIPE_SECRET_KEY in .env.test', () => {
  const { rotateKey } = require('./key-rotation');
  const before = readEnv().get('STRIPE_SECRET_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  const after  = readEnv().get('STRIPE_SECRET_KEY');

  assert.ok(after !== before,    'value should have changed');
  assert.ok(after !== undefined, 'key must still be present');
  assert.ok(after.startsWith('ROTATED-STRIPE_SECRET_KEY-'), 'placeholder must be namespaced');
});

// ── 7. Other keys are untouched when one key is rotated ─────────────────────
await test('rotating ANTHROPIC_API_KEY leaves all other keys untouched', () => {
  const { rotateKey } = require('./key-rotation');
  const before = readEnv();
  rotateKey('ANTHROPIC_API_KEY');
  const after  = readEnv();

  for (const [name, val] of before) {
    if (name === 'ANTHROPIC_API_KEY') continue;
    assert.strictEqual(after.get(name), val, `${name} must not be modified`);
  }
});

// ── 8. Atomic write — tmp file is gone after rotation ───────────────────────
await test('tmp file (.env.test.tmp) does not exist after a successful rotation', () => {
  const { rotateKey } = require('./key-rotation');
  rotateKey('STRIPE_SECRET_KEY');
  assert.ok(!fs.existsSync(ENV_TMP_FILE), '.env.test.tmp must be removed after rename');
});

// ── 9. Multiple sequential rotations produce distinct placeholders ───────────
await test('two successive rotateKey calls for the same key produce distinct placeholders', () => {
  const { rotateKey } = require('./key-rotation');
  rotateKey('STRIPE_SECRET_KEY');
  const first = readEnv().get('STRIPE_SECRET_KEY');

  // Small delay to ensure timestamp differs (or rely on random bytes)
  rotateKey('STRIPE_SECRET_KEY');
  const second = readEnv().get('STRIPE_SECRET_KEY');

  assert.ok(first  !== second, 'each rotation must produce a unique placeholder');
});

// ── 10. Log is created when it does not yet exist ───────────────────────────
await test('rotation-log.json is created if it does not exist', () => {
  if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');

  assert.ok(fs.existsSync(LOG_FILE), 'rotation-log.json must be created');
});

// ── 11. Successful rotation appends one log entry ───────────────────────────
await test('successful rotation appends exactly one "success" entry to the log', () => {
  const { rotateKey } = require('./key-rotation');
  const before = readLog().length;
  rotateKey('ANTHROPIC_API_KEY');
  const entries = readLog();

  assert.strictEqual(entries.length, before + 1, 'exactly one entry should be appended');
  const entry = entries[entries.length - 1];
  assert.strictEqual(entry.status,  'success');
  assert.strictEqual(entry.keyName, 'ANTHROPIC_API_KEY');
  assert.ok(typeof entry.timestamp === 'string', 'timestamp must be a string');
  assert.ok(!isNaN(Date.parse(entry.timestamp)), 'timestamp must be a valid ISO date');
});

// ── 12. Log entry must NOT contain the key value ─────────────────────────────
await test('log entry contains no field that exposes the key value', () => {
  const { rotateKey } = require('./key-rotation');
  rotateKey('STRIPE_SECRET_KEY');
  const entry = readLog().slice(-1)[0];

  const forbidden = ['value', 'secret', 'key', 'placeholder', 'newKey', 'oldKey', 'token'];
  for (const field of forbidden) {
    assert.ok(!(field in entry), `log entry must not have field "${field}"`);
  }
  // The raw JSON text must not contain the word "CANARY" (original key sentinel)
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  assert.ok(!raw.includes('CANARY'), 'log must not contain any part of the original key value');
});

// ── 13. Log accumulates across multiple rotations ───────────────────────────
await test('log accumulates entries across multiple rotations', () => {
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  rotateKey('ANTHROPIC_API_KEY');
  const entries = readLog();

  assert.ok(entries.length >= 3, 'all three rotation events must be recorded');
  const names = entries.map(e => e.keyName);
  assert.ok(names.filter(n => n === 'ANTHROPIC_API_KEY').length >= 2);
  assert.ok(names.filter(n => n === 'STRIPE_SECRET_KEY').length >= 1);
});

// ── 14. rotateKey throws on an unknown key ───────────────────────────────────
await test('rotateKey throws when given a key name not in .env.test', () => {
  const { rotateKey } = require('./key-rotation');
  assert.throws(
    () => rotateKey('NONEXISTENT_KEY'),
    /not tracked/,
    'should throw with "not tracked" message'
  );
});

// ── 15. Failed rotation is logged as "failure" ───────────────────────────────
await test('rotateKey logs a "failure" entry when the key is unknown', () => {
  const { rotateKey } = require('./key-rotation');
  const before = readLog().length;
  try { rotateKey('BOGUS_KEY'); } catch { /* expected */ }
  const entries = readLog();
  assert.strictEqual(entries.length, before + 1, 'failure should still be logged');
  const entry = entries[entries.length - 1];
  assert.strictEqual(entry.status,  'failure');
  assert.strictEqual(entry.keyName, 'BOGUS_KEY');
  assert.ok(typeof entry.error === 'string', 'failure entry must include an error message');
});

// ── 16. rotateKey throws on empty / non-string input ────────────────────────
await test('rotateKey throws on empty string', () => {
  const { rotateKey } = require('./key-rotation');
  assert.throws(() => rotateKey(''), /non-empty/);
});

await test('rotateKey throws on non-string input (number)', () => {
  const { rotateKey } = require('./key-rotation');
  assert.throws(() => rotateKey(42));
});

await test('rotateKey throws on non-string input (null)', () => {
  const { rotateKey } = require('./key-rotation');
  assert.throws(() => rotateKey(null));
});

// ── 17. .env.test preserves comments after rotation ─────────────────────────
await test('.env.test still contains the header comment after rotation', () => {
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  assert.ok(
    content.includes('# Synthetic test credentials'),
    'comment header must survive the rewrite'
  );
});

// ── 18. Log file is valid JSON after every rotation ─────────────────────────
await test('rotation-log.json is always valid JSON', () => {
  const { rotateKey } = require('./key-rotation');
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  assert.doesNotThrow(() => JSON.parse(raw), 'log file must be valid JSON');
  assert.ok(Array.isArray(JSON.parse(raw)),   'log file root must be a JSON array');
});

// ── 19. Log failure error message is sanitised (no raw key values) ───────────
await test('failure log error message does not contain raw key-like tokens', () => {
  // Force a failure by temporarily writing a bad key value into a fresh .env.test
  const { rotateKey } = require('./key-rotation');
  try { rotateKey('FAKE_SENSITIVE_KEY_abc123xyz789'); } catch { /* expected */ }
  const entries = readLog();
  const last = entries[entries.length - 1];
  if (last && last.error) {
    // Error message must not contain long alphanumeric tokens mixed with digits
    assert.ok(
      !last.error.match(/sk-[A-Za-z0-9]{10,}/),
      'error message must not leak sk- style tokens'
    );
  }
});

// ── 20. The module exports exactly rotateKey and getTrackedKeyNames ───────────
await test('module exports exactly { rotateKey, getTrackedKeyNames }', () => {
  const mod = require('./key-rotation');
  const keys = Object.keys(mod).sort();
  assert.deepStrictEqual(keys, ['getTrackedKeyNames', 'rotateKey']);
  assert.strictEqual(typeof mod.rotateKey,          'function');
  assert.strictEqual(typeof mod.getTrackedKeyNames, 'function');
});

// ─── Summary ─────────────────────────────────────────────────────────────────

console.log(`\n${'─'.repeat(40)}`);
console.log(`  Passed: ${passed}`);
console.log(`  Failed: ${failed}`);
console.log(`${'─'.repeat(40)}\n`);

if (failed > 0) process.exit(1);

