/**
 * key-rotation.js
 *
 * Provides a rotateKey(keyName) function that:
 *   1. Reads ONLY the variable *names* from .env.test (values are never
 *      read into memory, logged, or exposed in any way).
 *   2. Replaces the value of the requested key with a new placeholder
 *      string and writes the updated file atomically via a tmp-then-rename
 *      strategy.
 *   3. Appends a rotation event (timestamp + key name only) to
 *      rotation-log.json.
 *
 * Security contract
 * -----------------
 *  - Actual secret values are NEVER stored in variables, printed, or
 *    included in any log output.
 *  - The placeholder written during rotation is deterministic and clearly
 *    synthetic (it never resembles a real credential).
 *  - The tmp file is written with mode 0o600 so it is not world-readable
 *    before the rename.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ──────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Parse .env.test and return an array of the variable *names* that are
 * eligible for rotation (i.e. lines that look like KEY=<anything>).
 *
 * Values are discarded immediately — this function purposely does not
 * return them.
 *
 * @returns {string[]} Sorted list of variable names found in the file.
 */
function readRotatableKeyNames() {
  const raw   = fs.readFileSync(ENV_FILE, 'utf8');
  const names = [];

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 1) continue; // malformed line — no '=' or empty name

    const name = trimmed.slice(0, eqIndex).trim();
    if (name) names.push(name);
    // The value (trimmed.slice(eqIndex + 1)) is intentionally ignored.
  }

  return names;
}

/**
 * Generate a clearly synthetic placeholder value.
 * Format: ROTATED-<8 hex chars>-<unix-ms>
 * This is obviously not a real credential and is safe to store in test files.
 *
 * @returns {string}
 */
function generatePlaceholder() {
  const randomHex = crypto.randomBytes(4).toString('hex').toUpperCase();
  const ts        = Date.now();
  return `ROTATED-${randomHex}-${ts}`;
}

/**
 * Atomically update the value of `keyName` in .env.test.
 *
 *  1. Read the current file content.
 *  2. Replace ONLY the value of the matching KEY= line.
 *  3. Write to .env.test.tmp (mode 0o600).
 *  4. fs.renameSync → .env.test  (atomic on POSIX systems).
 *
 * The old value is never captured into a named variable; the regex
 * replacement is performed directly on the raw file string.
 *
 * @param {string} keyName      - The variable name whose value will be replaced.
 * @param {string} placeholder  - The synthetic value to write.
 */
function atomicUpdateEnvFile(keyName, placeholder) {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');

  // Match the exact key at the start of a line, followed by '=' and any value.
  // The captured group ($1) is discarded on replace — we never use it.
  const safeKeyPattern = new RegExp(
    `^(${escapeRegExp(keyName)}=).*$`,
    'm'
  );

  if (!safeKeyPattern.test(raw)) {
    throw new Error(
      `Key "${keyName}" not found in ${ENV_FILE}. ` +
      'Use readRotatableKeyNames() to discover available keys.'
    );
  }

  // Replace the matched line's value with the placeholder.
  // The regex never captures or exposes the old value.
  const updated = raw.replace(safeKeyPattern, `$1${placeholder}`);

  // Write to tmp with restrictive permissions (owner read/write only).
  fs.writeFileSync(ENV_TMP_FILE, updated, { encoding: 'utf8', mode: 0o600 });

  // Atomic rename — on POSIX this is a single syscall.
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

/**
 * Append a rotation event to rotation-log.json.
 * Only the timestamp and key *name* are recorded — never the value.
 *
 * Log entry shape:
 *   { "timestamp": "<ISO-8601>", "keyName": "<NAME>", "status": "rotated" }
 *
 * @param {string} keyName
 */
function appendRotationLog(keyName) {
  const entry = {
    timestamp : new Date().toISOString(),
    keyName   : keyName,
    status    : 'rotated',
    // NOTE: no "oldValue", no "newValue", no "placeholder" field.
  };

  let log = [];

  // Read the existing log if it exists.
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      log = JSON.parse(raw);
      if (!Array.isArray(log)) {
        throw new TypeError('rotation-log.json root must be a JSON array');
      }
    } catch (err) {
      throw new Error(`Failed to parse ${LOG_FILE}: ${err.message}`);
    }
  }

  log.push(entry);

  // Write the updated log.  Indented for human readability.
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

/** Escape special regex metacharacters in a literal string. */
function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Discover which key names are present in .env.test and are therefore
 * eligible for rotation.
 *
 * Returns variable *names* only.  Values are never surfaced.
 *
 * @returns {string[]}
 */
function getRotatableKeyNames() {
  return readRotatableKeyNames();
}

/**
 * Rotate the value of a single environment variable in .env.test.
 *
 * Steps:
 *   1. Validate that keyName is a non-empty string.
 *   2. Confirm the key exists in .env.test (by name only).
 *   3. Generate a synthetic placeholder.
 *   4. Atomically update .env.test (write tmp → rename).
 *   5. Append a log entry to rotation-log.json (timestamp + name only).
 *
 * @param {string} keyName - The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string }} Metadata about the rotation
 *          (never includes old or new values).
 * @throws {TypeError}  If keyName is not a non-empty string.
 * @throws {Error}      If keyName is not found in .env.test.
 */
function rotateKey(keyName) {
  // ── 1. Input validation ──────────────────────────────────────────────────
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    throw new TypeError('rotateKey: keyName must be a non-empty string.');
  }
  const normalizedName = keyName.trim();

  // ── 2. Confirm the key exists (by name only) ─────────────────────────────
  const available = readRotatableKeyNames();
  if (!available.includes(normalizedName)) {
    throw new Error(
      `rotateKey: "${normalizedName}" is not a recognised key in ${ENV_FILE}.\n` +
      `Available keys: ${available.join(', ')}`
    );
  }

  // ── 3. Generate placeholder ──────────────────────────────────────────────
  const placeholder = generatePlaceholder();

  // ── 4. Atomic file update ────────────────────────────────────────────────
  atomicUpdateEnvFile(normalizedName, placeholder);

  // ── 5. Append to rotation log ────────────────────────────────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(normalizedName);

  // Return only safe metadata.
  const result = { keyName: normalizedName, timestamp };
  console.log(
    `[key-rotation] Rotated "${normalizedName}" at ${timestamp}`
    // ↑ Key name only — no value logged.
  );

  return result;
}

// ─── Module exports ───────────────────────────────────────────────────────────

module.exports = { rotateKey, getRotatableKeyNames };

