  const realLog = path.resolve(__dirname, 'rotation-log.json');
  savedLogContent = fs.existsSync(realLog)
    ? fs.readFileSync(realLog, 'utf8')
    : null;
  if (fs.existsSync(realLog)) fs.unlinkSync(realLog);

  // Purge the module from require cache so path constants are re-evaluated.
  delete require.cache[require.resolve('./key-rotation')];
}

function teardownSandbox() {
  const realLog = path.resolve(__dirname, 'rotation-log.json');

