    } catch (err) {
      throw new Error(`Failed to parse ${LOG_FILE}: ${err.message}`);
    }
  }

  log.push(entry);

  // Write the updated log.  Indented for human readability.
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
