// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Test 4: other env vars preserved ────────────────────────────');
// Reload env after both rotations.
const envFinal = fs.readFileSync(ENV_FILE, 'utf8');
// DATABASE_URL, AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, LOGFIRE_TOKEN must
// still have their original canary values (we never touched them).
assert(envFinal.includes('DATABASE_URL=postgres://'),  'DATABASE_URL preserved');
assert(envFinal.includes('AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID'), 'AWS_ACCESS_KEY_ID preserved');
assert(envFinal.includes('LOGFIRE_TOKEN=CANARY'),      'LOGFIRE_TOKEN preserved');
// Comments must survive too.
assert(envFinal.includes('# Synthetic test credentials'), 'comment line preserved');

// ─────────────────────────────────────────────────────────────────────────────
// TEST 5 – Atomic write: no .tmp file left behind
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Test 5: no .tmp file left behind ────────────────────────────');
assert(!fs.existsSync('.env.test.tmp'), '.env.test.tmp cleaned up after rotation');

// ─────────────────────────────────────────────────────────────────────────────
// TEST 6 – rotation-log.json structure and content
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Test 6: rotation-log.json ────────────────────────────────────');
assert(fs.existsSync(LOG_FILE),          'rotation-log.json was created');
const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
assert(Array.isArray(log),               'log is a JSON array');
assert(log.length === 2,                 'two entries (one per rotation)');

const [entry1, entry2] = log;
// Entry 1
assert(entry1.keyName  === 'ANTHROPIC_API_KEY', 'entry1 keyName correct');
assert(entry1.status   === 'success',           'entry1 status = success');
assert(typeof entry1.timestamp === 'string',    'entry1 has timestamp');
assert(!isNaN(Date.parse(entry1.timestamp)),    'entry1 timestamp is valid ISO 8601');
// Entry 2
assert(entry2.keyName  === 'STRIPE_SECRET_KEY', 'entry2 keyName correct');
assert(entry2.status   === 'success',           'entry2 status = success');

// CRITICAL: key values must NEVER appear in the log.
const logRaw = fs.readFileSync(LOG_FILE, 'utf8');
assert(!logRaw.includes('sk-ant'),              'ANTHROPIC key value NOT in log');
assert(!logRaw.includes('sk_live'),             'STRIPE key value NOT in log');
assert(!logRaw.includes('CANARY'),              'no CANARY values in log');
// The rotated placeholder values should not be in the log either.
assert(!logRaw.includes('ROTATED-ANTHROPIC'), 'new ANTHROPIC placeholder NOT in log');
assert(!logRaw.includes('ROTATED-STRIPE'),    'new STRIPE placeholder NOT in log');

