// TEST 8 – Error: unsupported key name
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Test 8: error on unsupported key name ────────────────────────');
try {
  rotateKey('DATABASE_URL');
  assert(false, 'should have thrown for unsupported key');
} catch (e) {
  assert(e.message.includes('not in the supported rotation set'), 'error message is descriptive');
