// TEST 9 – Error: empty / non-string key name
// ─────────────────────────────────────────────────────────────────────────────
console.log('\n── Test 9: error on invalid keyName argument ────────────────────');
try {
  rotateKey('');
  assert(false, 'should throw for empty string');
} catch (e) {
  assert(e instanceof TypeError, 'TypeError thrown for empty keyName');
}
try {
  rotateKey(42);
  assert(false, 'should throw for non-string');
} catch (e) {
  assert(e instanceof TypeError, 'TypeError thrown for numeric keyName');
}

