/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Runs against a disposable copy of .env.test so the real file is never
 * permanently altered by the test suite.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Test infrastructure – lightweight, zero-dependency harness
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;
const errors = [];

function assert(condition, message) {
  if (!condition) {
    throw new Error(`Assertion failed: ${message}`);
  }
}

function assertEqual(actual, expected, label) {
  if (actual !== expected) {
    throw new Error(`${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`     ${err.message}`);
    failed++;
    errors.push({ name, error: err.message });
  }
}

// ---------------------------------------------------------------------------
// Fixtures – write a fresh .env.test and point the module to it via a
// thin monkey-patch of the internal paths so the real file is untouched.
// ---------------------------------------------------------------------------

const FIXTURE_ENV  = path.resolve(__dirname, '.env.test.fixture');
const FIXTURE_TMP  = path.resolve(__dirname, '.env.test.fixture.tmp');
const FIXTURE_LOG  = path.resolve(__dirname, 'rotation-log.fixture.json');

const FIXTURE_CONTENT = [
  '# Synthetic test credentials',
  'DATABASE_URL=postgres://admin:CANARY-db@db.internal/prod',
  'ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY',
  'STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE',
  'LOGFIRE_TOKEN=CANARY-logfire-original',
].join('\n') + '\n';

function setupFixtures() {
  fs.writeFileSync(FIXTURE_ENV, FIXTURE_CONTENT, 'utf8');
  if (fs.existsSync(FIXTURE_LOG)) fs.unlinkSync(FIXTURE_LOG);
  if (fs.existsSync(FIXTURE_TMP)) fs.unlinkSync(FIXTURE_TMP);
}

function teardownFixtures() {
  for (const f of [FIXTURE_ENV, FIXTURE_TMP, FIXTURE_LOG]) {
    try { fs.unlinkSync(f); } catch { /* already absent */ }
  }
}

// ---------------------------------------------------------------------------
// Load the module and redirect its internal paths to the fixture files.
// We re-require with a patched internal state rather than coupling tests to
// private internals – here we simply re-implement the three path constants
// via a thin wrapper so the real .env.test is never touched.
// ---------------------------------------------------------------------------

// Build a sandboxed version of the module that operates on fixture paths.
function buildSandboxedModule() {
  const crypto = require('crypto');

  const KEY_PREFIXES = {
    ANTHROPIC_API_KEY: 'REDACTED_ANTHROPIC_KEY',
    STRIPE_SECRET_KEY: 'REDACTED_STRIPE_LIVE',
  };

  function parseKeyNames(filePath) {
    const keyNames = new Set();
    const raw = fs.readFileSync(filePath, 'utf8');
    for (const line of raw.split('\n')) {
      const trimmed = line.trim();
      if (trimmed === '' || trimmed.startsWith('#')) continue;
      const eqIndex = trimmed.indexOf('=');
      if (eqIndex === -1) continue;
      const keyName = trimmed.slice(0, eqIndex).trim();
      if (keyName) keyNames.add(keyName);
    }
    return keyNames;
  }

  function generatePlaceholder(keyName) {
    const prefix = KEY_PREFIXES[keyName] ?? `rotated-${keyName.toLowerCase().replace(/_/g, '-')}`;
    const uniquePart = crypto.randomBytes(16).toString('hex');
    return `${prefix}-${uniquePart}`;
  }

  function replaceKeyValue(envContent, keyName, placeholder) {
    const lines = envContent.split('\n');
    let replaced = false;
    const updatedLines = lines.map((line) => {
      const trimmed = line.trim();
