/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security contract (enforced structurally, not just by convention):
 *   - Secret VALUES are never read into any variable in this module.
 *   - Only KEY NAMES (the left-hand side of KEY=value lines) are parsed.
 *   - rotateKey() generates a brand-new placeholder; it never touches the
 *     old value.
 *   - rotation-log.json records only { timestamp, keyName, status }.
 *   - No network I/O of any kind is performed.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Prefix map – each supported key name maps to the human-readable prefix that
// will be used in the generated placeholder.  Placeholders are NEVER real
// credentials; they are clearly marked stub values safe for test environments.
// ---------------------------------------------------------------------------

const KEY_PREFIXES = {
  ANTHROPIC_API_KEY: 'REDACTED_ANTHROPIC_KEY',
  STRIPE_SECRET_KEY: 'REDACTED_STRIPE_LIVE',
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parse an .env file and return the SET of key names declared in it.
 * Values are deliberately discarded the moment the line is split.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Set<string>}    Key names (no values).
 */
function parseKeyNames(filePath) {
  const keyNames = new Set();

  const raw = fs.readFileSync(filePath, 'utf8');

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments.
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }

    // Split on the FIRST '=' only; immediately discard everything after it.
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) {
      continue;
    }

    const keyName = trimmed.slice(0, eqIndex).trim();
    if (keyName) {
      keyNames.add(keyName);
    }
    // The value substring (trimmed.slice(eqIndex + 1)) is never captured.
  }

  return keyNames;
}

/**
 * Generate a new opaque placeholder string for a key.
 * Format:  <prefix>-<16 random hex bytes>
 *
 * crypto.randomUUID() / randomBytes() is used instead of Math.random() so
 * the placeholder is collision-resistant even in test environments.
 *
 * @param {string} keyName  The name of the key being rotated.
 * @returns {string}        A new placeholder value string.
 */
function generatePlaceholder(keyName) {
  const prefix = KEY_PREFIXES[keyName] ?? `rotated-${keyName.toLowerCase().replace(/_/g, '-')}`;
  const uniquePart = crypto.randomBytes(16).toString('hex');
  return `${prefix}-${uniquePart}`;
}

/**
 * Rewrite a single key's value inside an .env file content string.
 * The function operates purely on text; it never interprets any value.
 *
 * @param {string} envContent   Full text of the .env file.
 * @param {string} keyName      The key whose value should be replaced.
 * @param {string} placeholder  The new placeholder string.
 * @returns {string}            Updated .env file content.
 */
function replaceKeyValue(envContent, keyName, placeholder) {
  const lines = envContent.split('\n');
  let replaced = false;

  const updatedLines = lines.map((line) => {
    const trimmed = line.trim();

    // Skip comments and blank lines without modification.
    if (trimmed === '' || trimmed.startsWith('#')) {
      return line;
    }

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) {
      return line;
    }

    const parsedKey = trimmed.slice(0, eqIndex).trim();

    if (parsedKey === keyName) {
      replaced = true;
      // Reconstruct the line with the new placeholder; old value is discarded.
      return `${keyName}=${placeholder}`;
    }

    return line;
  });

  if (!replaced) {
    throw new Error(`Key "${keyName}" not found in env file – cannot rotate.`);
  }

  return updatedLines.join('\n');
}

/**
 * Append a rotation event to rotation-log.json.
 * Only timestamp, keyName, and status are written – never any key value.
 *
 * @param {string} keyName  The name of the key that was rotated.
 * @param {'success'|'failure'} status
 * @param {string} [errorMessage]  Human-readable error description (no values).
 */
function appendRotationLog(keyName, status, errorMessage) {
  // Build the log entry – value is structurally absent.
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,                            // name only, never the value
    status,
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  // Read existing log array (or start fresh).
  let logEntries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logEntries = parsed;
      }
    } catch {
      // Corrupted log – start fresh rather than crash.
      logEntries = [];
    }
  }

  logEntries.push(entry);

  // Write atomically: tmp file → rename.
  const logTmp = `${LOG_FILE}.tmp`;
  fs.writeFileSync(logTmp, JSON.stringify(logEntries, null, 2) + '\n', 'utf8');
  fs.renameSync(logTmp, LOG_FILE);

  // Console output contains ONLY the key name and status – never any value.
  console.log(`[key-rotation] ${entry.timestamp} | keyName=${keyName} | status=${status}`);
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Read the current .env.test file and return the names of all keys that this
 * module can rotate (i.e. those present in KEY_PREFIXES AND in the file).
 *
 * Return type is an array of key NAME strings – values are never returned.
 *
 * @returns {string[]}  Array of rotatable key names found in .env.test.
 */
function getRotatableKeys() {
  const declared = parseKeyNames(ENV_FILE);
  return Object.keys(KEY_PREFIXES).filter((name) => declared.has(name));
}

/**
 * Rotate a single key in .env.test.
 *
 * Steps:
 *   1. Verify the key name is in the supported set (KEY_PREFIXES).
 *   2. Verify the key name exists in .env.test.
 *   3. Generate a new placeholder (crypto.randomBytes – never touches old value).
 *   4. Write updated content to .env.test.tmp.
 *   5. Atomically rename .env.test.tmp → .env.test.
 *   6. Append a log entry (keyName + status only) to rotation-log.json.
 *
 * @param {string} keyName  The name of the key to rotate (e.g. 'ANTHROPIC_API_KEY').
 * @returns {{ keyName: string, rotatedAt: string }}
 *   A result object confirming rotation. The new placeholder is NOT returned.
 * @throws {Error} If keyName is unsupported or not found in the env file.
 */
function rotateKey(keyName) {
  // ── 1. Validate the key name is supported ──────────────────────────────────
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    const msg = 'rotateKey() requires a non-empty string keyName.';
    appendRotationLog(String(keyName), 'failure', msg);
    throw new Error(msg);
  }

  const normalizedName = keyName.trim();

  if (!Object.prototype.hasOwnProperty.call(KEY_PREFIXES, normalizedName)) {
    const msg = `"${normalizedName}" is not in the supported rotation set. ` +
                `Supported keys: ${Object.keys(KEY_PREFIXES).join(', ')}.`;
    appendRotationLog(normalizedName, 'failure', msg);
    throw new Error(msg);
  }

  // ── 2. Read the env file (key names only) and verify the key is present ────
  const declaredKeys = parseKeyNames(ENV_FILE);

  if (!declaredKeys.has(normalizedName)) {
    const msg = `Key "${normalizedName}" was not found in ${ENV_FILE}.`;
    appendRotationLog(normalizedName, 'failure', msg);
    throw new Error(msg);
  }

  // ── 3. Generate a new placeholder ──────────────────────────────────────────
  //    generatePlaceholder() creates a fresh random value; it never reads the
  //    old value from the file.
  const newPlaceholder = generatePlaceholder(normalizedName);

  // ── 4 & 5. Atomic write: tmp file → rename ─────────────────────────────────
  try {
    // Read the raw file content for line-by-line replacement.
    // We read the whole file here, but replaceKeyValue() discards values
    // immediately upon parsing each line.
    const currentContent = fs.readFileSync(ENV_FILE, 'utf8');
    const updatedContent = replaceKeyValue(currentContent, normalizedName, newPlaceholder);

    // Write to the tmp file first.
    fs.writeFileSync(TMP_FILE, updatedContent, { encoding: 'utf8', flag: 'w' });

    // Atomic rename: on POSIX systems rename(2) is atomic within the same
    // filesystem, so readers will never see a partially-written file.
    fs.renameSync(TMP_FILE, ENV_FILE);
  } catch (err) {
    // Clean up the tmp file if it was created before the failure.
    try { fs.unlinkSync(TMP_FILE); } catch { /* already gone – ignore */ }

    const msg = `Atomic write failed for "${normalizedName}": ${err.message}`;
    appendRotationLog(normalizedName, 'failure', msg);
    throw new Error(msg);
  }

  // ── 6. Log the successful rotation (name + timestamp only) ─────────────────
  const rotatedAt = new Date().toISOString();
  appendRotationLog(normalizedName, 'success');

  // Return a confirmation object.  The new placeholder is intentionally absent.
  return { keyName: normalizedName, rotatedAt };
}

// ---------------------------------------------------------------------------
// Exports
// ----------------------------------------------------------------

