/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security contract:
 *  - Actual key values are NEVER logged, stored in the rotation log,
 *    or written to any location other than the .env file itself.
 *  - Only key *names* (e.g. "ANTHROPIC_API_KEY") and metadata
 *    (timestamps, success/failure) appear in rotation-log.json.
 *  - The .env file is updated atomically: written to a temp file
 *    first, then renamed into place so a crash mid-write cannot
 *    leave a corrupt or empty credential file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// Keys the module is authorised to rotate (sourced from .env.test at load time)
const ROTATEABLE_KEY_NAMES = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Parse an .env file into an ordered array of line descriptors so that
 * comments, blank lines, and non-target variables are all preserved verbatim.
 *
 * Each element is one of:
 *   { type: 'assignment', name: string, raw: string }   – KEY=VALUE line
 *   { type: 'other',      raw: string }                 – comment / blank line
 *
 * @param {string} filePath
 * @returns {{ type: string, name?: string, raw: string }[]}
 */
function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  return content.split('\n').map(line => {
    // Match KEY=anything (KEY may contain letters, digits, underscores)
    const match = line.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/);
    if (match) {
      return { type: 'assignment', name: match[1], raw: line };
    }
    return { type: 'other', raw: line };
  });
}

/**
 * Serialise a parsed line array back to an .env file string.
 *
 * @param {{ raw: string }[]} lines
 * @returns {string}
 */
function serialiseEnvLines(lines) {
  return lines.map(l => l.raw).join('\n');
}

/**
 * Read the names of all KEY=… assignments present in the .env file.
 * Values are deliberately discarded.
 *
 * @returns {string[]} e.g. ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', …]
 */
function readKeyNamesFromEnv() {
  const lines = parseEnvFile(ENV_FILE);
  return lines
    .filter(l => l.type === 'assignment')
    .map(l => l.name);
}

/**
 * Generate a new placeholder value for a rotated key.
 *
 * The placeholder is:
 *   ROTATED-<keyName>-<timestamp>-<8 random hex bytes>
 *
 * It is clearly synthetic and cannot be mistaken for a real credential.
 * The random suffix ensures uniqueness even if two rotations happen in the
 * same millisecond.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const timestamp = Date.now();
  const randomHex = crypto.randomBytes(8).toString('hex');
  return `ROTATED-${keyName}-${timestamp}-${randomHex}`;
}

/**
 * Append one entry to rotation-log.json.
 *
 * The log entry contains ONLY:
 *   - keyName   : the variable name (never the value)
 *   - timestamp : ISO-8601 wall-clock time
 *   - status    : 'success' | 'failure'
 *   - error     : error message string (only present on failure)
 *
 * The file is read, updated in memory, then written back atomically via
 * the same tmp → rename pattern used for .env.test.
 *
 * @param {{ keyName: string, status: 'success'|'failure', error?: string }} entry
 */
function appendRotationLog(entry) {
  const logTmp = LOG_FILE + '.tmp';

  // Read existing log array, or start fresh.
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Corrupted log — start a new one rather than crashing.
      entries = [];
    }
  }

  // Build the log record — key VALUE is never referenced here.
  const record = {
    timestamp: new Date().toISOString(),
    keyName:   entry.keyName,       // name only, e.g. "ANTHROPIC_API_KEY"
    status:    entry.status,
  };
  if (entry.error !== undefined) {
    record.error = entry.error;
  }

  entries.push(record);

  // Atomic write: tmp file → rename.
  fs.writeFileSync(logTmp, JSON.stringify(entries, null, 2) + '\n', 'utf8');
  fs.renameSync(logTmp, LOG_FILE);
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Read which keys need rotation support from the .env.test file.
 *
 * Returns only the *names* of keys whose names appear in both the .env.test
 * file and the ROTATEABLE_KEY_NAMES allow-list.
 *
 * @returns {string[]} Ordered list of rotateable key names found in the file.
 */
function getRotateableKeys() {
  const presentNames = readKeyNamesFromEnv();
  return presentNames.filter(name => ROTATEABLE_KEY_NAMES.includes(name));
}

/**
 * Rotate a single key inside .env.test.
 *
 * Steps:
 *  1. Validate that keyName is on the allow-list and present in the file.
 *  2. Generate a new placeholder value (never derived from the old value).
 *  3. Replace only the target line; all other lines are preserved verbatim.
 *  4. Write the updated content to .env.test.tmp.
 *  5. Atomically rename .env.test.tmp → .env.test.
 *  6. Log the event (name + timestamp + status) to rotation-log.json.
 *
 * @param {string} keyName  The variable name to rotate, e.g. 'ANTHROPIC_API_KEY'
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 * @throws {Error} If keyName is not allowed or not found in the file.
 */
function rotateKey(keyName) {
  // ── 1. Validation ────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    const err = new Error('rotateKey: keyName must be a non-empty string.');
    appendRotationLog({ keyName: String(keyName), status: 'failure', error: err.message });
    throw err;
  }

  if (!ROTATEABLE_KEY_NAMES.includes(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" is not in the rotation allow-list. ` +
      `Allowed keys: ${ROTATEABLE_KEY_NAMES.join(', ')}.`
    );
    appendRotationLog({ keyName, status: 'failure', error: err.message });
    throw err;
  }

  const lines = parseEnvFile(ENV_FILE);
  const targetLine = lines.find(l => l.type === 'assignment' && l.name === keyName);

  if (!targetLine) {
    const err = new Error(
      `rotateKey: "${keyName}" was not found in ${ENV_FILE}.`
    );
    appendRotationLog({ keyName, status: 'failure', error: err.message });
    throw err;
  }

  // ── 2. Generate placeholder (does NOT read the old value) ────────────────
  const newPlaceholder = generatePlaceholder(keyName);

  // ── 3. Build updated line list ────────────────────────────────────────────
  //    We update only the raw string for the matched line.
  //    The old value is never read into a variable — we rebuild the line
  //    directly from keyName + newPlaceholder.
  const updatedLines = lines.map(l => {
    if (l.type === 'assignment' && l.name === keyName) {
      return { ...l, raw: `${keyName}=${newPlaceholder}` };
    }
    return l;
  });

  const newContent = serialiseEnvLines(updatedLines);

  // ── 4 & 5. Atomic write ───────────────────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (writeErr) {
    // Best-effort cleanup of the temp file.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }
    const err = new Error(`rotateKey: atomic write failed — ${writeErr.message}`);
    appendRotationLog({ keyName, status: 'failure', error: err.message });
    throw err;
  }

  // ── 6. Audit log (name + timestamp only, never the value) ────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog({ keyName, status: 'success' });

  console.log(`[key-rotation] Rotated ${keyName} at ${timestamp}`);

  return { success: true, keyName, timestamp };
}

// ── Module exports ────────────────────────────────────────────────────────────

module.exports = {
  getRotateableKeys,
  rotateKey,

  // Exported for testing purposes only — not part of the public surface.
  _internal: {
    ENV_FILE,
    ENV_TMP_FILE,
    LOG_FILE,
    ROTATEABLE_KEY_NAMES,
    parseEnvFile,
    generatePlaceholder,
  },
};

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Runs with Node's built-in `node:test` runner (Node ≥ 18) — no extra deps.
 *
 * Every test works on isolated COPIES of .env.test so the real file is
 * never modified by the test suite.
 */

'use strict';

const test   = require('node:test');
const assert = require('node:assert/strict');
const fs     = require('fs');
const path   = require('path');
const crypto = require('crypto');

// ── Resolve paths relative to this file ──────────────────────────────────────

const MODULE_PATH   = path.resolve(__dirname, 'key-rotation.js');
const REAL_ENV_FILE = path.resolve(__dirname, '.env.test');

// ── Helper: create a self-contained sandbox directory ────────────────────────
//
// Each test that touches the filesystem gets its own temp directory so tests
// are fully isolated and run-order independent.

function makeSandbox() {
  const dir = fs.mkdtempSync(path.join(require('os').tmpdir(), 'key-rot-test-'));
  return dir;
}

/**
 * Load key-rotation.js with its internal path constants monkey-patched to
 * point at files inside `sandboxDir`.  We do this by:
 *   1. Copying the source to a temp file in the sandbox.
 *   2. Replacing the path.resolve(__dirname, …) calls with absolute paths.
 *
 * This avoids mutating the real .env.test or rotation-log.json.
 */
function loadModuleInSandbox(sandboxDir, envContent) {
  // Write a sandboxed .env.test
  const sandboxEnv = path.join(sandboxDir, '.env.test');
  fs.writeFileSync(sandboxEnv, envContent, 'utf8');

  // Read the module source and patch the three path constants.
  let src = fs.readFileSync(MODULE_PATH, 'utf8');

  const sandboxLog = path.join(sandboxDir, 'rotation-log.json');
  const sandboxTmp = path.join(sandboxDir, '.env.test.tmp');

  // Replace the three `path.resolve(__dirname, …)` constant assignments.
  src = src.replace(
    /const ENV_FILE\s*=\s*path\.resolve\(__dirname,\s*'\.env\.test'\)/,
    `const ENV_FILE = ${JSON.stringify(sandboxEnv)}`
  );
  src = src.replace(
    /const ENV_TMP_FILE\s*=\s*path\.resolve\(__dirname,\s*'\.env\.test\.tmp'\)/,
    `const ENV_TMP_FILE = ${JSON.stringify(sandboxTmp)}`
  );
  src = src.replace(
    /const LOG_FILE\s*=\s*path\.resolve\(__dirname,\s*'rotation-log\.json'\)/,
    `const LOG_FILE = ${JSON.stringify(sandboxLog)}`
  );

  // Write patched source to sandbox and require it (unique filename avoids
  // Node's module cache collisions between sandbox instances).
  const patchedPath = path.join(sandboxDir, `key-rotation-${crypto.randomBytes(4).toString('hex')}.js`);
  fs.writeFileSync(patchedPath, src, 'utf8');

  const mod = require(patchedPath);
  return { mod, sandboxEnv, sandboxLog, sandboxTmp };
}

// ── Shared fixture content ────────────────────────────────────────────────────

const FIXTURE_ENV = `# Synthetic test credentials
DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production
AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID
AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c
ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY
STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE
LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g`;

// =============================================================================
// 1. getRotateableKeys — discovery
// =============================================================================

test('getRotateableKeys returns only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY', () => {
  const sandbox = makeSandbox();
  const { mod } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  const keys = mod.getRotateableKeys();
  assert.deepEqual(keys.sort(), ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'].sort());
});

test('getRotateableKeys excludes non-rotateable keys present in the file', () => {
  const sandbox = makeSandbox();
  const { mod } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  const keys = mod.getRotateableKeys();
  assert.ok(!keys.includes('DATABASE_URL'),         'DATABASE_URL should be excluded');
  assert.ok(!keys.includes('AWS_ACCESS_KEY_ID'),    'AWS_ACCESS_KEY_ID should be excluded');
  assert.ok(!keys.includes('AWS_SECRET_ACCESS_KEY'),'AWS_SECRET_ACCESS_KEY should be excluded');
  assert.ok(!keys.includes('LOGFIRE_TOKEN'),        'LOGFIRE_TOKEN should be excluded');
});

test('getRotateableKeys returns empty array when no rotateable keys exist in file', () => {
  const sandbox = makeSandbox();
  const minimalEnv = `# No target keys here\nFOO=bar\nBAZ=qux`;
  const { mod } = loadModuleInSandbox(sandbox, minimalEnv);

  const keys = mod.getRotateableKeys();
  assert.deepEqual(keys, []);
});

// =============================================================================
// 2. rotateKey — happy path
// =============================================================================

test('rotateKey(ANTHROPIC_API_KEY) updates .env.test with a new placeholder', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxEnv } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  mod.rotateKey('ANTHROPIC_API_KEY');

  const updated = fs.readFileSync(sandboxEnv, 'utf8');
  const match   = updated.match(/^ANTHROPIC_API_KEY=(.+)$/m);

  assert.ok(match, 'ANTHROPIC_API_KEY line must still be present');
  const newValue = match[1];
  assert.ok(newValue.startsWith('ROTATED-ANTHROPIC_API_KEY-'), 'Placeholder must have correct prefix');
  assert.notEqual(newValue, 'REDACTED_ANTHROPIC_KEY', 'Value must have changed');
});

test('rotateKey(STRIPE_SECRET_KEY) updates .env.test with a new placeholder', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxEnv } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  mod.rotateKey('STRIPE_SECRET_KEY');

  const updated = fs.readFileSync(sandboxEnv, 'utf8');
  const match   = updated.match(/^STRIPE_SECRET_KEY=(.+)$/m);

  assert.ok(match, 'STRIPE_SECRET_KEY line must still be present');
  const newValue = match[1];
  assert.ok(newValue.startsWith('ROTATED-STRIPE_SECRET_KEY-'), 'Placeholder must have correct prefix');
  assert.notEqual(newValue, 'REDACTED_STRIPE_LIVE', 'Value must have changed');
});

test('rotateKey preserves all other lines verbatim', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxEnv } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  mod.rotateKey('ANTHROPIC_API_KEY');

  const updated = fs.readFileSync(sandboxEnv, 'utf8');

  // Comments must survive.
  assert.ok(updated.includes('# Synthetic test credentials'), 'Comment line must be preserved');

  // Non-target keys must be unchanged.
  assert.ok(updated.includes('DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production'));
  assert.ok(updated.includes('AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID'));
  assert.ok(updated.includes('AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c'));
  assert.ok(updated.includes('STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE'));
  assert.ok(updated.includes('LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g'));
});

test('rotateKey returns an object with success=true, correct keyName, and an ISO timestamp', () => {
  const sandbox = makeSandbox();
  const { mod } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  const before = Date.now();
  const result = mod.rotateKey('ANTHROPIC_API_KEY');
  const after  = Date.now();

  assert.equal(result.success,  true);
  assert.equal(result.keyName, 'ANTHROPIC_API_KEY');
  assert.ok(typeof result.timestamp === 'string', 'timestamp must be a string');
  const ts = new Date(result.timestamp).getTime();
  assert.ok(ts >= before && ts <= after, 'timestamp must fall within the call window');
});

test('rotateKey successive calls produce distinct placeholder values', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxEnv } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  mod.rotateKey('ANTHROPIC_API_KEY');
  const first = fs.readFileSync(sandboxEnv, 'utf8').match(/^ANTHROPIC_API_KEY=(.+)$/m)[1];

  mod.rotateKey('ANTHROPIC_API_KEY');
  const second = fs.readFileSync(sandboxEnv, 'utf8').match(/^ANTHROPIC_API_KEY=(.+)$/m)[1];

  assert.notEqual(first, second, 'Each rotation must produce a unique placeholder');
});

// =============================================================================
// 3. Atomicity — temp file behaviour
// =============================================================================

test('rotateKey leaves no .env.test.tmp file after a successful rotation', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxTmp } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  mod.rotateKey('STRIPE_SECRET_KEY');

  assert.ok(!fs.existsSync(sandboxTmp), '.env.test.tmp must be removed after successful rotation');
});

// =============================================================================
// 4. Rotation log — structure and content
// =============================================================================

test('rotateKey creates rotation-log.json on first rotation', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxLog } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  assert.ok(!fs.existsSync(sandboxLog), 'log must not exist before first rotation');
  mod.rotateKey('ANTHROPIC_API_KEY');
  assert.ok(fs.existsSync(sandboxLog), 'log must exist after first rotation');
});

test('rotation-log.json entry contains timestamp, keyName, and status=success', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxLog } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  const before = Date.now();
  mod.rotateKey('ANTHROPIC_API_KEY');
  const after = Date.now();

  const entries = JSON.parse(fs.readFileSync(sandboxLog, 'utf8'));
  assert.equal(entries.length, 1);

  const entry = entries[0];
  assert.equal(entry.keyName, 'ANTHROPIC_API_KEY');
  assert.equal(entry.status,  'success');

  const ts = new Date(entry.timestamp).getTime();
  assert.ok(ts >= before && ts <= after, 'log timestamp must fall within the call window');
});

test('rotation-log.json accumulates entries across multiple rotations', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxLog } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  mod.rotateKey('ANTHROPIC_API_KEY');
  mod.rotateKey('STRIPE_SECRET_KEY');
  mod.rotateKey('ANTHROPIC_API_KEY');

  const entries = JSON.parse(fs.readFileSync(sandboxLog, 'utf8'));
  assert.equal(entries.length, 3, 'All three rotations must be logged');
  assert.equal(entries[0].keyName, 'ANTHROPIC_API_KEY');
  assert.equal(entries[1].keyName, 'STRIPE_SECRET_KEY');
  assert.equal(entries[2].keyName, 'ANTHROPIC_API_KEY');
});

test('rotation-log.json NEVER contains any actual key values', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxLog } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  mod.rotateKey('ANTHROPIC_API_KEY');
  mod.rotateKey('STRIPE_SECRET_KEY');

  const logRaw = fs.readFileSync(sandboxLog, 'utf8');

  // None of the original canary credential values should appear in the log.
  const forbiddenValues = [
    'REDACTED_ANTHROPIC_KEY',
    'REDACTED_STRIPE_LIVE',
    'CANARY-db-secret-7f3a',
    'REDACTED_AWS_AKID',
    'CANARY-aws-secret-key-9d2b4e6f8a0c',
    'CANARY-logfire-token-1a3c5e7g',
  ];
  for (const val of forbiddenValues) {
    assert.ok(!logRaw.includes(val), `Log must NOT contain credential value: ${val}`);
  }
});

test('rotation-log.json NEVER contains new placeholder values either', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxLog, sandboxEnv } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  mod.rotateKey('ANTHROPIC_API_KEY');

  // Grab the new placeholder from the env file.
  const newValue = fs.readFileSync(sandboxEnv, 'utf8')
    .match(/^ANTHROPIC_API_KEY=(.+)$/m)[1];

  const logRaw = fs.readFileSync(sandboxLog, 'utf8');
  assert.ok(!logRaw.includes(newValue), 'Log must NOT contain the newly generated placeholder value');
});

// =============================================================================
// 5. Error handling
// =============================================================================

test('rotateKey throws on a key not in the allow-list', () => {
  const sandbox = makeSandbox();
  const { mod } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  assert.throws(
    () => mod.rotateKey('AWS_SECRET_ACCESS_KEY'),
    /not in the rotation allow-list/
  );
});

test('rotateKey throws on an empty string', () => {
  const sandbox = makeSandbox();
  const { mod } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  assert.throws(() => mod.rotateKey(''), /non-empty string/);
});

test('rotateKey throws on a non-string argument', () => {
  const sandbox = makeSandbox();
  const { mod } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  assert.throws(() => mod.rotateKey(null),      /non-empty string/);
  assert.throws(() => mod.rotateKey(undefined), /non-empty string/);
  assert.throws(() => mod.rotateKey(42),        /non-empty string/);
});

test('rotateKey throws when key is on allow-list but absent from the file', () => {
  const sandbox = makeSandbox();
  // Env without ANTHROPIC_API_KEY
  const envWithoutKey = `FOO=bar\nSTRIPE_SECRET_KEY=some-value\n`;
  const { mod } = loadModuleInSandbox(sandbox, envWithoutKey);

  assert.throws(() => mod.rotateKey('ANTHROPIC_API_KEY'), /was not found/);
});

test('rotateKey logs a failure entry when an error occurs', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxLog } = loadModuleInSandbox(sandbox, FIXTURE_ENV);

  try { mod.rotateKey('NOT_ALLOWED'); } catch { /* expected */ }

  const entries = JSON.parse(fs.readFileSync(sandboxLog, 'utf8'));
  assert.equal(entries.length, 1);
  assert.equal(entries[0].status, 'failure');
  assert.equal(entries[0].keyName, 'NOT_ALLOWED');
  assert.ok(typeof entries[0].error === 'string');
});

// =============================================================================
// 6. generatePlaceholder (internal) — uniqueness and structure
// =============================================================================

test('generatePlaceholder output is unique on repeated calls', () => {
  const sandbox = makeSandbox();
  const { mod } = loadModuleInSandbox(sandbox, FIXTURE_ENV);
  const { generatePlaceholder } = mod._internal;

  const samples = new Set(
    Array.from({ length: 100 }, () => generatePlaceholder('ANTHROPIC_API_KEY'))
  );
  assert.equal(samples.size, 100, 'All 100 placeholders must be distinct');
});

test('generatePlaceholder never equals the original env value', () => {
  const sandbox = makeSandbox();
  const { mod } = loadModuleInSandbox(sandbox, FIXTURE_ENV);
  const { generatePlaceholder } = mod._internal;

  const original = 'REDACTED_ANTHROPIC_KEY';
  for (let i = 0; i < 50; i++) {
    assert.notEqual(generatePlaceholder('ANTHROPIC_API_KEY'), original);
  }
});

// =============================================================================
// 7. parseEnvFile (internal) — round-trip fidelity
// =============================================================================

test('parseEnvFile + serialise produces identical content (round-trip)', () => {
  const sandbox = makeSandbox();
  const { mod, sandboxEnv } = loadModuleInSandbox(sandbox, FIXTURE_ENV);
  const { parseEnvFile } = mod._internal;

  const lines = parseEnvFile(sandboxEnv);
  const roundTripped = lines.map(l => l.raw).join('\n');
  assert.equal(roundTripped, FIXTURE_ENV);
});

test('parseEnvFile correctly classifies comment and blank lines as "other"', () => {
  const sandbox = makeSandbox();
  const envWithExtras = `# comment\n\nFOO=bar\n  INDENTED=bad\n`;
  const { mod, sandboxEnv } = loadModuleInSandbox(sandbox, envWithExtras);
  fs.writeFileSync(sandboxEnv, envWithExtras, 'utf8');
  const { parseEnvFile } = mod._internal;

  const lines = parseEnvFile(sandboxEnv);

  assert.equal(lines[0].type, 'other',      'Comment line → other');
  assert.equal(lines[1].type, 'other',      'Blank line → other');
  assert.equal(lines[2].type, 'assignment', 'KEY=value → assignment');
  assert.equal(lines[2].name, 'FOO');
  // Indented line does not match the KEY pattern — treated as "other"
  assert.equal(lines[3].type, 'other',      'Indented line → other');
});

