/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Responsibilities:
 *  - Read ANTHROPIC_API_KEY and STRIPE_SECRET_KEY variable *names* from
 *    .env.test to discover which keys need rotation support.
 *  - rotateKey(keyName): generate a new placeholder value, atomically update
 *    .env.test (write → .env.test.tmp, then fs.rename), and append a
 *    rotation event (timestamp + key name ONLY) to rotation-log.json.
 *
 * Security contract:
 *  - Actual key VALUES are NEVER written to the log, printed to stdout/stderr,
 *    or exposed outside the .env.test file itself.
 *  - The log records only: ISO-8601 timestamp, the key *name*, and status.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// The two key names this module explicitly supports (read from .env.test).
// ---------------------------------------------------------------------------

const SUPPORTED_KEY_NAMES = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Parse an .env file into a Map<string, { value: string, rawLine: string }>.
 * Preserves comment lines and blank lines so we can round-trip the file
 * faithfully.
 *
 * @param {string} content - Raw file content.
 * @returns {{ entries: Map<string, string>, lines: string[] }}
 *   `lines`   – every original line (for reconstruction).
 *   `entries` – key → current value (only assignment lines).
 */
function parseEnv(content) {
  const lines   = content.split('\n');
  const entries = new Map();

  for (const line of lines) {
    // Skip blank lines and comment lines.
    if (!line.trim() || line.trimStart().startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key   = line.slice(0, eqIdx).trim();
    const value = line.slice(eqIdx + 1); // preserve everything after '='
    entries.set(key, value);
  }

  return { lines, entries };
}

/**
 * Serialise the (possibly mutated) lines array back to an env-file string.
 * We replace the value on lines that match a key in `updates`.
 *
 * @param {string[]}         lines   - Original lines array from parseEnv.
 * @param {Map<string,string>} updates - key → new value to write.
 * @returns {string}
 */
function serialiseEnv(lines, updates) {
  return lines
    .map((line) => {
      if (!line.trim() || line.trimStart().startsWith('#')) return line;

      const eqIdx = line.indexOf('=');
      if (eqIdx === -1) return line;

      const key = line.slice(0, eqIdx).trim();
      if (updates.has(key)) {
        return `${key}=${updates.get(key)}`;
      }
      return line;
    })
    .join('\n');
}

/**
 * Generate a new placeholder value for a key.
 *
 * Format:   ROTATED-<PREFIX>-<16 random hex bytes>-<Unix timestamp>
 *
 * The prefix is derived from the key *name* (never the old value) so that
 * the placeholder is identifiable without revealing anything secret.
 *
 * @param {string} keyName - e.g. 'ANTHROPIC_API_KEY'
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const randomHex  = crypto.randomBytes(16).toString('hex');
  const unixMs     = Date.now();
  // Sanitise the key name to safe characters for use inside the value.
  const safePrefix = keyName.replace(/[^A-Z0-9_]/gi, '_').toUpperCase();
  return `ROTATED-${safePrefix}-${randomHex}-${unixMs}`;
}

/**
 * Append one rotation event to rotation-log.json.
 * The event contains ONLY: timestamp (ISO-8601), keyName, status.
 * The key value is NEVER included.
 *
 * @param {string} keyName  - Name of the key that was rotated.
 * @param {'success'|'failure'} status
 * @param {string} [errorMessage] - Human-readable error description (no values).
 */
function appendRotationLog(keyName, status, errorMessage) {
  // Build the new log entry — value-free by design.
  const entry = {
    timestamp : new Date().toISOString(),
    keyName,
    status,
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  // Read existing log array (create empty array if the file doesn't exist yet
  // or contains invalid JSON).
  let logArray = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logArray = parsed;
      }
    } catch {
      // Corrupt log — start fresh rather than crashing.
      logArray = [];
    }
  }

  logArray.push(entry);

  // Write the updated log back.  A crash here is non-fatal to the rotation
  // itself, so we let any I/O error surface naturally without swallowing it
  // (the caller already finished writing the env file at this point).
  fs.writeFileSync(LOG_FILE, JSON.stringify(logArray, null, 2) + '\n', 'utf8');
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Read the env file and return only the *names* of keys that this module
 * has rotation support for (ANTHROPIC_API_KEY and STRIPE_SECRET_KEY).
 *
 * @returns {string[]} Array of supported key names present in .env.test.
 */
function getRotatableKeys() {
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Environment file not found: ${ENV_FILE}`);
  }

  const content          = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries }      = parseEnv(content);
  const rotatableKeys    = SUPPORTED_KEY_NAMES.filter((name) => entries.has(name));

  return rotatableKeys;
}

/**
 * Rotate the specified key in .env.test.
 *
 * Steps:
 *  1. Validate keyName is one of the supported, managed keys.
 *  2. Read and parse .env.test.
 *  3. Confirm the key exists in the file.
 *  4. Generate a new placeholder value.
 *  5. Serialise the updated content to .env.test.tmp  (atomic write step 1).
 *  6. Rename .env.test.tmp → .env.test                (atomic write step 2).
 *  7. Append a log entry (timestamp + keyName + status) to rotation-log.json.
 *
 * @param {string} keyName - Must be 'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY'.
 * @returns {{ keyName: string, timestamp: string }}
 *   Confirmation object containing ONLY the key name and rotation timestamp.
 *   The new value is intentionally NOT returned.
 * @throws {Error} if keyName is unsupported, the env file is missing, or
 *                 the key is not present in the file.
 */
function rotateKey(keyName) {
  // --- 1. Validate keyName --------------------------------------------------
  if (!SUPPORTED_KEY_NAMES.includes(keyName)) {
    const err = new Error(
      `Unsupported key name: "${keyName}". ` +
      `rotateKey() only manages: ${SUPPORTED_KEY_NAMES.join(', ')}.`
    );
    // Log the failed attempt (no value involved).
    try { appendRotationLog(keyName, 'failure', err.message); } catch { /* non-fatal */ }
    throw err;
  }

  // --- 2. Read and parse .env.test ------------------------------------------
  if (!fs.existsSync(ENV_FILE)) {
    const err = new Error(`Environment file not found: ${ENV_FILE}`);
    try { appendRotationLog(keyName, 'failure', err.message); } catch { /* non-fatal */ }
    throw err;
  }

  const content        = fs.readFileSync(ENV_FILE, 'utf8');
  const { lines, entries } = parseEnv(content);

  // --- 3. Confirm key exists ------------------------------------------------
  if (!entries.has(keyName)) {
    const err = new Error(
      `Key "${keyName}" was not found in ${ENV_FILE}. ` +
      `Cannot rotate a key that does not exist.`
    );
    try { appendRotationLog(keyName, 'failure', err.message); } catch { /* non-fatal */ }
    throw err;
  }

  // --- 4. Generate new placeholder ------------------------------------------
  const newPlaceholder = generatePlaceholder(keyName);
  const updates        = new Map([[keyName, newPlaceholder]]);

  // --- 5. Write to .env.test.tmp --------------------------------------------
  const updatedContent = serialiseEnv(lines, updates);

  // Clean up any stale tmp file from a previously interrupted rotation.
  if (fs.existsSync(TMP_FILE)) {
    fs.unlinkSync(TMP_FILE);
  }

  fs.writeFileSync(TMP_FILE, updatedContent, { encoding: 'utf8', flag: 'w' });

  // --- 6. Atomic rename: .env.test.tmp → .env.test --------------------------
  fs.renameSync(TMP_FILE, ENV_FILE);

  // --- 7. Log rotation event (name + timestamp only) ------------------------
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName, 'success');

  // Return a confirmation that deliberately omits the new value.
  return { keyName, timestamp };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getRotatableKeys,
  rotateKey,
  // Exported for unit-testing purposes only.
  _internal: {
    parseEnv,
    serialiseEnv,
    generatePlaceholder,
    ENV_FILE,
    TMP_FILE,
    LOG_FILE,
    SUPPORTED_KEY_NAMES,
  },
};

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Runs with Node's built-in `node:test` + `assert` — no extra dependencies.
 *
 * Run: node key-rotation.test.js
 */

'use strict';

const test   = require('node:test');
const assert = require('node:assert/strict');
const fs     = require('fs');
const path   = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Load the module under test
// ---------------------------------------------------------------------------
const {
  getRotatableKeys,
  rotateKey,
  _internal: {
    parseEnv,
    serialiseEnv,
    generatePlaceholder,
    ENV_FILE,
    TMP_FILE,
    LOG_FILE,
    SUPPORTED_KEY_NAMES,
  },
} = require('./key-rotation');

// ---------------------------------------------------------------------------
// Helpers for isolated, non-destructive testing
// ---------------------------------------------------------------------------

/**
 * Save and restore .env.test + rotation-log.json around each test so the
 * real files are not permanently mutated.
 */
function withFileGuard(fn) {
  return async () => {
    // Snapshot originals.
    const origEnv = fs.existsSync(ENV_FILE)
      ? fs.readFileSync(ENV_FILE, 'utf8')
      : null;
    const origLog = fs.existsSync(LOG_FILE)
      ? fs.readFileSync(LOG_FILE, 'utf8')
      : null;

    try {
      await fn();
    } finally {
      // Restore originals unconditionally.
      if (origEnv !== null) {
        fs.writeFileSync(ENV_FILE, origEnv, 'utf8');
      }
      if (origLog !== null) {
        fs.writeFileSync(LOG_FILE, origLog, 'utf8');
      } else if (fs.existsSync(LOG_FILE)) {
        fs.unlinkSync(LOG_FILE);
      }
      // Clean up any leftover tmp file.
      if (fs.existsSync(TMP_FILE)) fs.unlinkSync(TMP_FILE);
    }
  };
}

// ---------------------------------------------------------------------------
// Unit: parseEnv
// ---------------------------------------------------------------------------

test('parseEnv – extracts key=value pairs', () => {
  const content = [
    '# a comment',
    'FOO=bar',
    'BAZ=qux=with=equals',
    '',
    'EMPTY=',
  ].join('\n');

  const { entries } = parseEnv(content);
  assert.equal(entries.get('FOO'),  'bar');
  assert.equal(entries.get('BAZ'),  'qux=with=equals');
  assert.equal(entries.get('EMPTY'), '');
  assert.ok(!entries.has('# a comment'), 'comment lines must not be parsed as keys');
});

test('parseEnv – preserves all original lines', () => {
  const content = '# comment\nKEY=val\n\nOTHER=x';
  const { lines } = parseEnv(content);
  assert.deepEqual(lines, ['# comment', 'KEY=val', '', 'OTHER=x']);
});

test('parseEnv – handles empty file', () => {
  const { entries, lines } = parseEnv('');
  assert.equal(entries.size, 0);
  assert.deepEqual(lines, ['']);
});

// ---------------------------------------------------------------------------
// Unit: serialiseEnv
// ---------------------------------------------------------------------------

test('serialiseEnv – updates only the targeted key', () => {
  const content = 'A=old_a\nB=old_b\n';
  const { lines } = parseEnv(content);
  const updates = new Map([['A', 'new_a']]);
  const result  = serialiseEnv(lines, updates);

  assert.ok(result.includes('A=new_a'), 'should contain updated value for A');
  assert.ok(result.includes('B=old_b'), 'should leave B unchanged');
});

test('serialiseEnv – preserves comment lines verbatim', () => {
  const content = '# header\nKEY=value\n';
  const { lines } = parseEnv(content);
  const result  = serialiseEnv(lines, new Map());
  assert.ok(result.startsWith('# header'), 'comment must survive round-trip');
});

test('serialiseEnv – round-trips without changes when updates map is empty', () => {
  const content = '# c\nFOO=bar\nBAZ=qux\n';
  const { lines } = parseEnv(content);
  assert.equal(serialiseEnv(lines, new Map()), content);
});

// ---------------------------------------------------------------------------
// Unit: generatePlaceholder
// ---------------------------------------------------------------------------

test('generatePlaceholder – starts with ROTATED-', () => {
  const p = generatePlaceholder('ANTHROPIC_API_KEY');
  assert.ok(p.startsWith('ROTATED-'), `expected prefix "ROTATED-", got: ${p}`);
});

test('generatePlaceholder – embeds sanitised key name', () => {
  const p = generatePlaceholder('STRIPE_SECRET_KEY');
  assert.ok(p.includes('STRIPE_SECRET_KEY'), `key name not embedded in placeholder: ${p}`);
});

test('generatePlaceholder – is unique across consecutive calls', () => {
  const a = generatePlaceholder('ANTHROPIC_API_KEY');
  const b = generatePlaceholder('ANTHROPIC_API_KEY');
  assert.notEqual(a, b, 'two consecutive placeholders must differ (random component)');
});

test('generatePlaceholder – contains only safe characters (no whitespace)', () => {
  const p = generatePlaceholder('ANTHROPIC_API_KEY');
  assert.doesNotMatch(p, /\s/, 'placeholder must not contain whitespace');
});

// ---------------------------------------------------------------------------
// Integration: getRotatableKeys
// ---------------------------------------------------------------------------

test('getRotatableKeys – returns ANTHROPIC_API_KEY and STRIPE_SECRET_KEY', withFileGuard(() => {
  const keys = getRotatableKeys();
  assert.ok(keys.includes('ANTHROPIC_API_KEY'), 'must include ANTHROPIC_API_KEY');
  assert.ok(keys.includes('STRIPE_SECRET_KEY'), 'must include STRIPE_SECRET_KEY');
}));

test('getRotatableKeys – does not return unsupported keys', withFileGuard(() => {
  const keys = getRotatableKeys();
  for (const k of keys) {
    assert.ok(
      SUPPORTED_KEY_NAMES.includes(k),
      `Unexpected key returned: ${k}`
    );
  }
}));

test('getRotatableKeys – throws when env file is missing', withFileGuard(() => {
  // Temporarily remove the env file to trigger the error path.
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  fs.unlinkSync(ENV_FILE);
  try {
    assert.throws(() => getRotatableKeys(), /not found/i);
  } finally {
    fs.writeFileSync(ENV_FILE, content, 'utf8');
  }
}));

// ---------------------------------------------------------------------------
// Integration: rotateKey – success paths
// ---------------------------------------------------------------------------

test('rotateKey – updates ANTHROPIC_API_KEY in .env.test', withFileGuard(() => {
  const before = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries: beforeEntries } = parseEnv(before);
  const oldValue = beforeEntries.get('ANTHROPIC_API_KEY');

  rotateKey('ANTHROPIC_API_KEY');

  const after = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries: afterEntries } = parseEnv(after);
  const newValue = afterEntries.get('ANTHROPIC_API_KEY');

  assert.ok(newValue, 'key must still exist after rotation');
  assert.notEqual(newValue, oldValue, 'value must change after rotation');
  assert.ok(newValue.startsWith('ROTATED-'), 'new value must be a placeholder');
}));

test('rotateKey – updates STRIPE_SECRET_KEY in .env.test', withFileGuard(() => {
  const before = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries: beforeEntries } = parseEnv(before);
  const oldValue = beforeEntries.get('STRIPE_SECRET_KEY');

  rotateKey('STRIPE_SECRET_KEY');

  const after = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries: afterEntries } = parseEnv(after);
  const newValue = afterEntries.get('STRIPE_SECRET_KEY');

  assert.ok(newValue, 'key must still exist after rotation');
  assert.notEqual(newValue, oldValue, 'value must change after rotation');
  assert.ok(newValue.startsWith('ROTATED-'), 'new value must be a placeholder');
}));

test('rotateKey – does NOT disturb other keys in .env.test', withFileGuard(() => {
  const before = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries: beforeEntries } = parseEnv(before);

  rotateKey('ANTHROPIC_API_KEY');

  const after = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries: afterEntries } = parseEnv(after);

  // Every key that wasn't targeted must be unchanged.
  for (const [k, v] of beforeEntries) {
    if (k === 'ANTHROPIC_API_KEY') continue;
    assert.equal(afterEntries.get(k), v, `Unrelated key "${k}" must not change`);
  }
}));

test('rotateKey – preserves comment lines in .env.test', withFileGuard(() => {
  rotateKey('ANTHROPIC_API_KEY');
  const after = fs.readFileSync(ENV_FILE, 'utf8');
  assert.ok(
    after.includes('# Synthetic test credentials'),
    'comment header must survive rotation'
  );
}));

test('rotateKey – returns object with keyName and timestamp (no value)', withFileGuard(() => {
  const result = rotateKey('STRIPE_SECRET_KEY');

  assert.ok(Object.prototype.hasOwnProperty.call(result, 'keyName'),
    'result must have keyName');
  assert.ok(Object.prototype.hasOwnProperty.call(result, 'timestamp'),
    'result must have timestamp');
  assert.equal(result.keyName, 'STRIPE_SECRET_KEY');

  // Verify timestamp is ISO-8601.
  assert.ok(!isNaN(Date.parse(result.timestamp)), 'timestamp must be a valid date string');

  // The returned object must NOT contain any key value.
  const resultStr = JSON.stringify(result);
  assert.ok(!resultStr.includes('ROTATED-') || resultStr.includes('STRIPE_SECRET_KEY'),
    'result must not leak actual secret value');
  // More specifically: returned object has exactly two keys.
  assert.equal(Object.keys(result).length, 2, 'result must have exactly keyName and timestamp');
}));

test('rotateKey – tmp file does not linger after successful rotation', withFileGuard(() => {
  rotateKey('ANTHROPIC_API_KEY');
  assert.ok(!fs.existsSync(TMP_FILE), '.env.test.tmp must not exist after successful rotation');
}));

// ---------------------------------------------------------------------------
// Integration: rotateKey – rotation-log.json
// ---------------------------------------------------------------------------

test('rotateKey – creates rotation-log.json if it does not exist', withFileGuard(() => {
  if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);
  rotateKey('ANTHROPIC_API_KEY');
  assert.ok(fs.existsSync(LOG_FILE), 'rotation-log.json must be created');
}));

test('rotateKey – log entry contains timestamp and keyName', withFileGuard(() => {
  if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);

  const before = new Date();
  rotateKey('ANTHROPIC_API_KEY');
  const after  = new Date();

  const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert.ok(Array.isArray(log), 'log must be an array');
  assert.equal(log.length, 1);

  const entry = log[0];
  assert.equal(entry.keyName, 'ANTHROPIC_API_KEY');
  assert.equal(entry.status,  'success');

  const entryTime = new Date(entry.timestamp);
  assert.ok(entryTime >= before && entryTime <= after,
    'log timestamp must fall within the rotation window');
}));

test('rotateKey – log does NOT contain any key value', withFileGuard(() => {
  if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);

  // Capture the new value written to .env.test so we can assert it's absent.
  rotateKey('STRIPE_SECRET_KEY');

  const newEnvContent = fs.readFileSync(ENV_FILE, 'utf8');
  const { entries }   = parseEnv(newEnvContent);
  const newValue      = entries.get('STRIPE_SECRET_KEY');

  const logContent = fs.readFileSync(LOG_FILE, 'utf8');
  assert.ok(
    !logContent.includes(newValue),
    'rotation-log.json must NOT contain the actual key value'
  );
}));

test('rotateKey – log accumulates multiple entries across rotations', withFileGuard(() => {
  if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);

  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  rotateKey('ANTHROPIC_API_KEY');

  const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert.equal(log.length, 3, 'log must have one entry per rotation');
  assert.equal(log[0].keyName, 'ANTHROPIC_API_KEY');
  assert.equal(log[1].keyName, 'STRIPE_SECRET_KEY');
  assert.equal(log[2].keyName, 'ANTHROPIC_API_KEY');
}));

test('rotateKey – log entry has NO extra fields beyond timestamp/keyName/status',
  withFileGuard(() => {
    if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);
    rotateKey('ANTHROPIC_API_KEY');

    const log   = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
    const entry = log[0];
    const keys  = Object.keys(entry).sort();

    assert.deepEqual(keys, ['keyName', 'status', 'timestamp'],
      `Log entry must have exactly {timestamp, keyName, status}, got: ${keys}`);
  })
);

// ---------------------------------------------------------------------------
// Integration: rotateKey – error / edge-case paths
// ---------------------------------------------------------------------------

test('rotateKey – throws on unsupported key name', withFileGuard(() => {
  assert.throws(
    () => rotateKey('DATABASE_URL'),
    /unsupported key name/i
  );
}));

test('rotateKey – throws when env file is missing', withFileGuard(() => {
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  fs.unlinkSync(ENV_FILE);
  try {
    assert.throws(
      () => rotateKey('ANTHROPIC_API_KEY'),
      /not found/i
    );
  } finally {
    fs.writeFileSync(ENV_FILE, content, 'utf8');
  }
}));

test('rotateKey – throws when key is missing from env file', withFileGuard(() => {
  // Write an env file that omits ANTHROPIC_API_KEY.
  fs.writeFileSync(ENV_FILE, 'STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE\n', 'utf8');
  assert.throws(
    () => rotateKey('ANTHROPIC_API_KEY'),
    /not found in/i
  );
}));

test('rotateKey – logs failure event when key is unsupported', withFileGuard(() => {
  if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);

  try { rotateKey('BOGUS_KEY'); } catch { /* expected */ }

  const log = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert.equal(log.length, 1);
  assert.equal(log[0].keyName, 'BOGUS_KEY');
  assert.equal(log[0].status,  'failure');
  assert.ok(log[0].error,      'failure entry must include an error message');
}));

test('rotateKey – cleans up stale tmp file before writing', withFileGuard(() => {
  // Create a stale tmp file to simulate a previously interrupted rotation.
  fs.writeFileSync(TMP_FILE, 'stale content', 'utf8');

  // Rotation must succeed despite the stale file.
  assert.doesNotThrow(() => rotateKey('ANTHROPIC_API_KEY'));
  assert.ok(!fs.existsSync(TMP_FILE), 'stale tmp file must be cleaned up');
}));

test('rotateKey – env file is a valid .env format after rotation', withFileGuard(() => {
  rotateKey('STRIPE_SECRET_KEY');

  const content = fs.readFileSync(ENV_FILE, 'utf8');
  // Every non-blank, non-comment line must contain '='.
  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    assert.ok(trimmed.includes('='), `Line is not valid env format: "${line}"`);
  }
}));

